//! Bounded, read-only parsers for OLE Compound File Binary legacy Office files.
//!
//! This module intentionally implements only document viewing primitives. It
//! never instantiates OLE objects, follows links, decrypts content, or executes
//! macros. Unsupported records are skipped inside their declared boundaries and
//! reported through diagnostics.

use std::collections::{BTreeMap, HashMap, HashSet, VecDeque};
use std::rc::Rc;

use crate::diagnostic::{Diagnostic, DiagnosticCode, Fidelity, Phase};
use crate::font_metrics::FontMetricTable;
use crate::format::embedded_media::embedded_media_type;
use crate::limits::Limits;
use crate::model::{
    Document, DocumentFormat, DocumentKind, FillRule, Geometry, GradientStop, ImageCrop,
    MappingQuality, MediaKind, Object, ObjectKind, Paint, PathCommand, PathFillMode, PathLayer,
    Rect, Shadow, SheetAxis, SheetAxisSpan, SourceLocator, SourceRef, StrokeStyle, TextAlign,
    TextEffect, TextHorizontalOverflow, TextLayout, TextOrientation, TextParagraphLayout, TextRun,
    TextTabLeader, TextTabStop, TextVerticalAlign, Unit, UnitKind, Visual, VisualBrushChild,
};
use crate::package::Package;
use crate::protocol::MAX_RICH_TEXT_RUNS;
use crate::xml::{XmlEvent, parse_xml};

use super::drawingml::{Chart, ChartDataLabel, ChartFill, ChartKind, ChartSeries};
use super::{
    diamond_geometry, polygon_geometry as ppt_polygon_geometry,
    regular_polygon_geometry as ppt_regular_polygon_geometry,
};

const CFB_MAGIC: &[u8; 8] = b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1";
const FREE_SECTOR: u32 = 0xffff_ffff;
const END_OF_CHAIN: u32 = 0xffff_fffe;
const FAT_SECTOR: u32 = 0xffff_fffd;
const DIFAT_SECTOR: u32 = 0xffff_fffc;
const MAX_REGULAR_SECTOR: u32 = 0xffff_fffa;
const DIRECTORY_ENTRY_BYTES: usize = 128;
const CFB_HEADER_BYTES: usize = 512;
const CFB_MINI_STREAM_CUTOFF: usize = 4096;

/// Detects an OLE CFB file and parses a supported binary DOC, XLS, or PPT
/// stream. Detection is content-based; a CFB file with no supported native
/// stream returns `Ok(None)`.
pub fn detect_and_parse(bytes: &[u8], limits: Limits) -> Result<Option<Document>, Diagnostic> {
    detect_and_parse_with_font_metrics(bytes, limits, &FontMetricTable::default())
}

pub fn detect_and_parse_with_font_metrics(
    bytes: &[u8],
    limits: Limits,
    font_metrics: &FontMetricTable,
) -> Result<Option<Document>, Diagnostic> {
    if !bytes.starts_with(CFB_MAGIC) {
        return Ok(None);
    }
    limits.validate().map_err(|error| {
        Diagnostic::fatal(
            DiagnosticCode::InvalidLimits,
            Phase::Input,
            None,
            error.to_string(),
        )
    })?;
    if bytes.len() > limits.max_input_bytes {
        return Err(Diagnostic::fatal(
            DiagnosticCode::InputTooLarge,
            Phase::Input,
            None,
            "OLE input exceeds the configured byte limit",
        ));
    }

    let cfb = CompoundFile::open(bytes, limits)?;
    let candidates = [
        (LegacyKind::Doc, cfb.has_stream("WordDocument")),
        (
            LegacyKind::Xls,
            cfb.has_stream("Workbook") || cfb.has_stream("Book"),
        ),
        (LegacyKind::Ppt, cfb.has_stream("PowerPoint Document")),
    ];
    let mut detected = candidates
        .into_iter()
        .filter_map(|(kind, present)| present.then_some(kind));
    let Some(kind) = detected.next() else {
        return Ok(None);
    };
    if detected.next().is_some() {
        return Err(container_error(
            "OLE directory contains multiple incompatible Office document streams",
        ));
    }

    let mut diagnostics = cfb.security_diagnostics();
    let document = match kind {
        LegacyKind::Doc => parse_doc(&cfb, limits, &mut diagnostics, font_metrics)?,
        LegacyKind::Xls => parse_xls(&cfb, limits, &mut diagnostics)?,
        LegacyKind::Ppt => parse_ppt(&cfb, limits, &mut diagnostics)?,
    };
    Ok(Some(document))
}

/// Reads a Microsoft Graph chart from an embedded OLE object without activating it.
#[cfg(feature = "native-formats")]
pub(super) fn parse_msgraph_chart(
    bytes: &[u8],
    limits: Limits,
    colors: [u32; 6],
) -> Result<Option<Chart>, Diagnostic> {
    if !bytes.starts_with(CFB_MAGIC) {
        return Ok(None);
    }
    let cfb = CompoundFile::open(bytes, limits)?;
    let workbook = if cfb.has_stream(XLS_WORKBOOK_STREAM) {
        cfb.stream(XLS_WORKBOOK_STREAM)?
    } else if cfb.has_stream(XLS_BOOK_STREAM) {
        cfb.stream(XLS_BOOK_STREAM)?
    } else {
        return Ok(None);
    };
    let records = parse_biff_records(&workbook, limits, "Microsoft Graph Workbook")?;
    let Some(chart_start) = records.iter().position(|record| {
        matches!(record.id, 0x0009 | 0x0209 | 0x0409 | 0x0809)
            && record.data.len() >= 4
            && read_u16(record.data, 2, "Microsoft Graph BOF").is_ok_and(|value| value == 0x8000)
    }) else {
        return Ok(None);
    };
    parse_biff_chart(&records, chart_start, limits, colors)
}

// BIFF chart geometry is shared by XLS and embedded Microsoft Graph. Their
// cache encodings differ: MSGraph uses a row/column table; XLS SIIndex separates
// categories and values and its cache cells are not worksheet cells.
fn parse_biff_chart(
    records: &[BiffRecord<'_>],
    chart_start: usize,
    limits: Limits,
    colors: [u32; 6],
) -> Result<Option<Chart>, Diagnostic> {
    let msgraph = read_u16(records[chart_start].data, 2, "BIFF chart BOF")? == 0x8000;
    let chart_font = records
        .iter()
        .find(|record| record.id == 0x1060 && record.data.get(6..8) == Some(&[0, 0]))
        .and_then(parse_msgraph_fbi)
        .and_then(|(width, height, font_index)| {
            records
                .iter()
                .filter(|record| record.id == 0x0031)
                .nth(usize::from(
                    font_index.saturating_sub(u16::from(font_index >= 5)),
                ))
                .and_then(parse_msgraph_font)
                .map(|font| (font, width, height))
        });
    let chart_records = &records[chart_start + 1..];
    let legend_bounds = chart_records
        .iter()
        .find(|record| record.id == 0x1015)
        .and_then(parse_msgraph_legend_bounds);
    let plot_area_border = parse_msgraph_plot_area_border(chart_records);
    let view_3d = chart_records
        .iter()
        .find(|record| record.id == 0x103a)
        .map(|record| {
            let flags = read_u16(record.data, 12, "Microsoft Graph 3-D flags")?;
            Ok(super::drawingml::ChartView3D {
                rot_x: read_u16(record.data, 2, "Microsoft Graph 3-D elevation")? as i16,
                rot_y: read_u16(record.data, 0, "Microsoft Graph 3-D rotation")?,
                right_angle_axes: flags & 1 == 0,
                perspective: read_u16(record.data, 4, "Microsoft Graph 3-D perspective")?,
                height_percent: None,
                depth_percent: None,
            })
        })
        .transpose()?;
    let three_d = view_3d.is_some();
    let bar_record = chart_records.iter().find(|record| record.id == 0x1017);
    let bar_flags = bar_record
        .map(|record| read_u16(record.data, 4, "Microsoft Graph bar flags"))
        .transpose()?
        .unwrap_or(0);
    let bar_gap_width_percent = bar_record
        .map(|record| read_u16(record.data, 2, "Microsoft Graph bar gap"))
        .transpose()?
        .map_or(150.0, f32::from);
    let category_axis_reversed = chart_records
        .iter()
        .find(|record| record.id == 0x1020)
        .map(|record| read_u16(record.data, 6, "Microsoft Graph category axis flags"))
        .transpose()?
        .is_some_and(|flags| flags & 4 != 0);
    let attached_label_flags = chart_records
        .iter()
        .filter(|record| record.id == 0x100c)
        .filter_map(|record| record.data.first().copied())
        .fold(0, |combined, flags| combined | flags);
    let show_values = attached_label_flags & 0x01 != 0;
    let show_percent = attached_label_flags & 0x02 != 0;
    let show_category_name = attached_label_flags & 0x04 != 0;
    let kind = if chart_records.iter().any(|record| record.id == 0x1017) {
        ChartKind::Bar
    } else if let Some(record) = chart_records.iter().find(|record| record.id == 0x1061) {
        let split_position = read_u16(record.data, 4, "Microsoft Graph bar-of-pie split")?;
        ChartKind::BarOfPie(split_position)
    } else if chart_records.iter().any(|record| record.id == 0x1019) {
        ChartKind::Pie
    } else if chart_records
        .iter()
        .any(|record| matches!(record.id, 0x103e | 0x1040))
    {
        ChartKind::Radar
    } else {
        return Ok(None);
    };
    let mut labels = BTreeMap::<(u16, u16), String>::new();
    let mut numbers = BTreeMap::<(u16, u16), f32>::new();
    let mut number_formats = BTreeMap::<(u16, u16), u16>::new();
    let mut cache_index = 0;
    for record in chart_records
        .iter()
        .take_while(|record| record.id != 0x000a)
    {
        if !msgraph {
            match record.id {
                0x1065 => cache_index = read_u16(record.data, 0, "BIFF chart SIIndex")?,
                0x0204 if cache_index == 2 => {
                    let point = read_u16(record.data, 0, "BIFF chart label")?;
                    let series = read_u16(record.data, 2, "BIFF chart label")?;
                    let value = parse_standalone_biff_string(
                        record.data.get(6..).unwrap_or_default(),
                        "BIFF chart label",
                    )?;
                    if point >= 32000 || series >= 255 {
                        return Err(format_error(
                            "BIFF chart",
                            "chart cache coordinates are out of range",
                        ));
                    }
                    labels.insert((series, point + 1), value);
                }
                0x0203 if cache_index == 1 => {
                    require_biff_length(record.data, 14, "BIFF chart", "Number")?;
                    let point = read_u16(record.data, 0, "BIFF chart number")?;
                    let series = read_u16(record.data, 2, "BIFF chart number")?;
                    if point >= 32000
                        || series >= 255
                        || numbers.len() >= limits.max_document_objects
                    {
                        return Err(object_limit("BIFF chart cache exceeds the object limit"));
                    }
                    let value =
                        f64::from_bits(read_u64(record.data, 6, "BIFF chart number")?) as f32;
                    // Preserve sparse slots instead of shifting later values to earlier labels.
                    numbers.insert((series + 1, point + 1), value);
                }
                _ => {}
            }
            continue;
        }
        if record.id == 0x0004 && record.data.len() >= 9 {
            let row = read_u16(record.data, 0, "Microsoft Graph label")?;
            let column = read_u16(record.data, 2, "Microsoft Graph label")?;
            let length = read_u16(record.data, 7, "Microsoft Graph label")? as usize;
            let end = 9usize.checked_add(length).ok_or_else(|| {
                format_error("Microsoft Graph Workbook", "label length overflows")
            })?;
            let value = record
                .data
                .get(9..end)
                .ok_or_else(|| format_error("Microsoft Graph Workbook", "label is truncated"))?;
            labels.insert(
                (row, column),
                value.iter().map(|byte| char::from(*byte)).collect(),
            );
        } else if record.id == 0x0003 && record.data.len() >= 14 {
            let row = read_u16(record.data, 0, "Microsoft Graph number")?;
            let column = read_u16(record.data, 2, "Microsoft Graph number")?;
            let start = record.data.len() - 8;
            let value = f64::from_le_bytes(
                record.data[start..]
                    .try_into()
                    .map_err(|_| format_error("Microsoft Graph Workbook", "number is truncated"))?,
            ) as f32;
            if value.is_finite() {
                numbers.insert((row, column), value);
                number_formats.insert(
                    (row, column),
                    if record.data.len() >= 15 {
                        u16::from(record.data[5])
                    } else {
                        read_u16(record.data, 4, "Microsoft Graph number format")?
                    },
                );
            }
        }
    }
    let max_row = numbers.keys().map(|(row, _)| *row).max().unwrap_or(0);
    let max_column = numbers.keys().map(|(_, column)| *column).max().unwrap_or(0);
    if usize::from(max_row).saturating_mul(usize::from(max_column)) > limits.max_document_objects {
        return Err(object_limit(
            "BIFF chart cache extent exceeds the object limit",
        ));
    }
    let categories = (1..=max_column)
        .map(|column| labels.get(&(0, column)).cloned().unwrap_or_default())
        .collect::<Vec<_>>();
    let series = (1..=max_row)
        .filter_map(|row| {
            let mut values = (1..=max_column)
                .filter_map(|column| {
                    numbers
                        .get(&(row, column))
                        .copied()
                        .or_else(|| (!msgraph).then_some(f32::NAN))
                })
                .collect::<Vec<_>>();
            let mut series_categories = if msgraph {
                categories.clone()
            } else {
                (1..=max_column)
                    .map(|column| labels.get(&(row - 1, column)).cloned().unwrap_or_default())
                    .collect()
            };
            if category_axis_reversed {
                series_categories.reverse();
                values.reverse();
            }
            let number_format = (1..=max_column)
                .filter_map(|column| number_formats.get(&(row, column)).copied())
                .find_map(|format| match format {
                    9 => Some("0%".to_owned()),
                    10 => Some("0.00%".to_owned()),
                    _ => None,
                });
            let point_colors = matches!(kind, ChartKind::Pie | ChartKind::BarOfPie(_))
                .then(|| colors.into_iter().collect())
                .unwrap_or_default();
            (!values.is_empty()).then(|| ChartSeries {
                kind,
                first_slice_angle: 0.0,
                grouping: super::drawingml::ChartGrouping::Standard,
                bar_horizontal: kind == ChartKind::Bar && bar_flags & 1 != 0,
                bar_depth: false,
                bar_cone: false,
                bar_cone_to_max: false,
                bar_cylinder: false,
                bar_gap_depth_percent: 150.0,
                three_d,
                axis_id: None,
                name: labels.get(&(row, 0)).cloned().unwrap_or_default(),
                category_levels: Vec::new(),
                categories: series_categories,
                x_values: Vec::new(),
                values,
                raw_values: Vec::new(),
                bubble_sizes: Vec::new(),
                color: Some(colors[usize::from(row - 1) % colors.len()]),
                fill: None,
                point_colors,
                point_fills: Vec::new(),
                point_explosions: Vec::new(),
                effects: Default::default(),
                point_border_colors: Vec::new(),
                point_border_widths: Vec::new(),
                stroke_width: None,
                line_visible: true,
                smooth: false,
                marker_symbol: None,
                marker_size: None,
                subtotals: Vec::new(),
                show_values,
                show_category_name,
                show_percent,
                number_format,
                data_label_position: (matches!(kind, ChartKind::Pie | ChartKind::BarOfPie(_))
                    && show_category_name
                    && show_percent)
                    .then(|| "outEnd".to_owned()),
                data_label_text_color: None,
                data_label_font_size: None,
                data_label_font_bold: None,
                data_label_rotation_degrees: None,
                hidden_labels: Vec::new(),
                data_labels: Vec::new(),
                data_label_border: None,
                linear_trendline: false,
                show_trendline_equation: false,
                show_trendline_r_squared: false,
                trendline_label_offset: None,
                trendline_label_font_size: None,
                x_error_bars: None,
                y_error_bars: None,
            })
        })
        .collect::<Vec<_>>();
    let axis_number_format = series
        .iter()
        .find_map(|series| series.number_format.clone());
    let mut horizontal_axis_options = super::drawingml::ChartValueAxis::default();
    horizontal_axis_options.number_format = axis_number_format;
    horizontal_axis_options.position =
        (kind == ChartKind::Bar && bar_flags & 1 != 0 && category_axis_reversed)
            .then(|| "t".to_owned());
    let mut chart = Chart {
        source_part: "Microsoft Graph Workbook".to_owned(),
        date_1904: false,
        series,
        show_title: false,
        title: String::new(),
        title_fill: None,
        title_position: None,
        title_font_size: None,
        title_font_bold: None,
        title_text_color: None,
        show_legend: legend_bounds.is_some(),
        legend_position: super::drawingml::ChartLegendPosition::Right,
        deleted_legend_entries: Vec::new(),
        chart_area_no_fill: false,
        chart_area_fill: None,
        chart_area_border: None,
        plot_area_fill: None,
        legend_fill: None,
        legend_stroke: None,
        legend_stroke_width: 0.0,
        plot_area_color: None,
        plot_area_border_color: plot_area_border.map(|border| border.0),
        plot_area_border_width: plot_area_border.map_or(0.0, |border| border.1),
        data_label_position: None,
        style: None,
        classic_defaults: false,
        font_family: chart_font.as_ref().map(|font| font.0.0.clone()),
        font_size: chart_font.as_ref().map(|font| font.0.1),
        font_bold: chart_font.as_ref().is_some_and(|font| font.0.2),
        font_scale_basis: chart_font.map(|font| (font.1, font.2)),
        native_size: None,
        value_axis_options: super::drawingml::ChartValueAxis::default(),
        secondary_value_axis_options: None,
        horizontal_axis_options,
        series_axis_options: None,
        scatter_has_lines: false,
        series_lines: false,
        data_table: None,
        up_down_bars: None,
        plot_bounds: None,
        legend_bounds,
        view_3d,
        surface_band_fills: Vec::new(),
        bar_gap_width_percent,
        category_gap_width: None,
    };
    if !msgraph {
        chart.source_part = XLS_WORKBOOK_STREAM.to_owned();
        apply_biff_chart_styles(&mut chart, chart_records, records, limits)?;
    }
    Ok((!chart.series.is_empty()).then_some(chart))
}

fn apply_biff_chart_styles(
    chart: &mut Chart,
    records: &[BiffRecord<'_>],
    workbook_records: &[BiffRecord<'_>],
    limits: Limits,
) -> Result<(), Diagnostic> {
    let part = XLS_WORKBOOK_STREAM;
    let fonts = workbook_records
        .iter()
        .filter(|record| record.id == 0x0031)
        .collect::<Vec<_>>();
    let mut data_format = None;
    let mut text_record = None;
    let mut text_depth = 0usize;
    let mut text = String::new();
    let mut font = None;
    let mut series_index = 0usize;
    let mut series_count = 0usize;
    // Each format block ends at its matching End, not a nested frame's End.
    let mut depth = 0usize;
    let mut format_depth = 0usize;
    for record in records.iter().take_while(|record| record.id != 0x000a) {
        match record.id {
            0x1033 => depth += 1,
            0x1034 => {
                depth = depth.saturating_sub(1);
                if depth == format_depth {
                    data_format = None;
                }
                if depth == text_depth {
                    text_record = None;
                }
            }
            0x1003 => {
                series_index = series_count;
                series_count += 1;
            }
            0x100d if text_record.is_none() => {
                if let Some(series) = chart.series.get_mut(series_index) {
                    series.name = parse_biff_series_text(record.data, part)?;
                }
            }
            0x1006 => {
                let point = read_u16(record.data, 0, part)?;
                let series = usize::from(read_u16(record.data, 2, part)?);
                data_format = Some((series, point));
                format_depth = depth;
            }
            0x100a => {
                require_biff_length(record.data, 16, part, "AreaFormat")?;
                let fill = if read_u16(record.data, 8, part)? == 0 {
                    None
                } else {
                    Some(ChartFill::Solid(ppt_color(read_u32(record.data, 0, part)?)))
                };
                if let Some((series, point)) = data_format {
                    if let Some(series) = chart.series.get_mut(series) {
                        if point == u16::MAX {
                            series.fill = fill;
                        } else if usize::from(point) < series.values.len() {
                            series.point_fills.resize(series.values.len(), None);
                            series.point_fills[usize::from(point)] = fill;
                        }
                    }
                } else if text_record.is_none() && chart.chart_area_fill.is_none() {
                    chart.chart_area_fill = fill;
                }
            }
            0x1007 => {
                if let Some((series, point)) = data_format {
                    if let Some(series) = chart.series.get_mut(series) {
                        let border = parse_msgraph_line_format(record);
                        series.point_border_colors.resize(series.values.len(), None);
                        series.point_border_widths.resize(series.values.len(), 0.0);
                        let range = if point == u16::MAX {
                            0..series.values.len()
                        } else {
                            usize::from(point)..(usize::from(point) + 1).min(series.values.len())
                        };
                        for index in range {
                            series.point_border_colors[index] =
                                Some(border.map_or(0, |value| value.0));
                            series.point_border_widths[index] = border.map_or(0.0, |value| value.1);
                        }
                    }
                } else if text_record.is_none() && chart.chart_area_border.is_none() {
                    chart.chart_area_border = parse_msgraph_line_format(record)
                        .map(|(color, width)| (ChartFill::Solid(color), width));
                    chart.plot_area_border_color = None;
                    chart.plot_area_border_width = 0.0;
                }
            }
            0x1066 => {
                if let Some((series, point)) = data_format {
                    if let Some(series) = chart.series.get_mut(series) {
                        if let Some(fill) =
                            parse_biff_chart_gradient(record.data, workbook_records, limits)?
                        {
                            if point == u16::MAX {
                                series.fill = Some(fill);
                            } else if usize::from(point) < series.values.len() {
                                series.point_fills.resize(series.values.len(), None);
                                series.point_fills[usize::from(point)] = Some(fill);
                            }
                        }
                    }
                }
            }
            0x1019 => {
                let angle = f32::from(read_u16(record.data, 0, part)?);
                for series in &mut chart.series {
                    series.first_slice_angle = angle;
                }
            }
            0x104f if text_record.is_none() => {
                if read_u16(record.data, 0, part)? == 2 && read_u16(record.data, 2, part)? == 2 {
                    let bounds = Rect {
                        x: read_i32(record.data, 4, part)? as f32 / 4000.0,
                        y: read_i32(record.data, 8, part)? as f32 / 4000.0,
                        width: read_i32(record.data, 12, part)? as f32 / 4000.0,
                        height: read_i32(record.data, 16, part)? as f32 / 4000.0,
                    };
                    if bounds.is_valid() && bounds.width > 0.0 && bounds.height > 0.0 {
                        chart.plot_bounds = Some(bounds);
                    }
                }
            }
            0x1025 => {
                text_depth = depth;
                text_record = Some(record);
                text.clear();
                font = None;
            }
            0x1026 => {
                let index = read_u16(record.data, 0, part)?;
                font = fonts
                    .get(usize::from(index.saturating_sub(u16::from(index >= 5))))
                    .and_then(|record| parse_msgraph_font(record));
            }
            0x100d => text = parse_biff_series_text(record.data, part)?,
            0x1027 => {
                let Some(style) = text_record.take() else {
                    continue;
                };
                require_biff_length(style.data, 32, part, "Text")?;
                let flags = read_u16(style.data, 24, part)?;
                let color = ppt_color(read_u32(style.data, 4, part)?);
                match read_u16(record.data, 0, part)? {
                    1 => {
                        chart.show_title = flags & 0x40 == 0;
                        chart.title = text.clone();
                        chart.title_text_color = Some(color);
                        chart.title_font_size = font.as_ref().map(|font| font.1);
                        chart.title_font_bold = font.as_ref().map(|font| font.2);
                    }
                    4 => {
                        let series_index = usize::from(read_u16(record.data, 2, part)?);
                        let point = read_u16(record.data, 4, part)?;
                        let Some(series) = chart.series.get_mut(series_index) else {
                            continue;
                        };
                        let position = match read_u16(style.data, 28, part)? & 0xf {
                            1 => "outEnd",
                            2 => "inEnd",
                            3 => "ctr",
                            4 => "inBase",
                            _ => "bestFit",
                        }
                        .to_owned();
                        let show_values = flags & 4 != 0;
                        let show_category = flags & 0x4800 != 0;
                        let show_percent = flags & 0x1800 != 0;
                        if point == u16::MAX {
                            series.data_label_position = Some(position);
                            series.show_values = show_values;
                            series.show_category_name = show_category;
                            series.show_percent = show_percent;
                            series.data_label_text_color = Some(color);
                            series.data_label_font_size = font.as_ref().map(|font| font.1);
                            series.data_label_font_bold = font.as_ref().map(|font| font.2);
                        } else if usize::from(point) < series.values.len() {
                            if flags & 0x40 != 0 {
                                series.hidden_labels.push(usize::from(point));
                            }
                            series.data_labels.push(ChartDataLabel {
                                index: usize::from(point),
                                text: text.clone(),
                                text_color: Some(color),
                                font_size: font.as_ref().map(|font| font.1),
                                font_bold: font.as_ref().map(|font| font.2),
                                manual_offset: None,
                                manual_size: None,
                                border_color: None,
                                border_width: 0.0,
                                show_values: Some(show_values),
                                show_category_name: Some(show_category),
                                show_percent: Some(show_percent),
                                number_format: None,
                                position: (read_u16(style.data, 28, part)? & 0xf != 0xa)
                                    .then_some(position),
                            });
                        }
                    }
                    _ => {}
                }
            }
            _ => {}
        }
    }
    // A series fill is inherited by its points unless a point overrides it.
    for series in &mut chart.series {
        series.point_fills.resize(series.values.len(), None);
        for fill in &mut series.point_fills {
            if fill.is_none() {
                *fill = series.fill.clone();
            }
        }
    }
    Ok(())
}

fn parse_biff_series_text(data: &[u8], part: &str) -> Result<String, Diagnostic> {
    // SeriesText uses an 8-bit character count; LABEL uses a 16-bit count.
    let length = usize::from(
        *data
            .get(2)
            .ok_or_else(|| format_error(part, "SeriesText is truncated"))?,
    );
    let unicode = *data
        .get(3)
        .ok_or_else(|| format_error(part, "SeriesText is truncated"))?
        & 1
        != 0;
    let text = data
        .get(4..4 + length * if unicode { 2 } else { 1 })
        .ok_or_else(|| format_error(part, "SeriesText is truncated"))?;
    decode_biff_characters(text, length, unicode, part)
}

fn biff_palette_color(records: &[BiffRecord<'_>], color_index: u32, part: &str) -> Option<u32> {
    let Some(palette) = records.iter().find(|record| record.id == 0x0092) else {
        return super::excel_indexed_color(color_index);
    };
    let index = color_index.checked_sub(8)? as usize;
    if index >= usize::from(read_u16(palette.data, 0, part).ok()?) {
        return None;
    }
    let offset = 2 + index * 4;
    palette
        .data
        .get(offset..offset + 4)
        .and_then(|bytes| bytes.try_into().ok())
        .map(u32::from_le_bytes)
        .map(ppt_color)
}

fn parse_biff_chart_gradient(
    data: &[u8],
    records: &[BiffRecord<'_>],
    limits: Limits,
) -> Result<Option<ChartFill>, Diagnostic> {
    let part = XLS_WORKBOOK_STREAM;
    let record = ppt_record_at_in_part(data, 0, data.len(), limits, part)?;
    if record.record_type != OFFICE_ART_OPT {
        return Ok(None);
    }
    let count = usize::from(record.instance());
    if record.body_start + count * 6 > record.body_end {
        return Err(format_error(part, "GelFrame properties are truncated"));
    }
    let mut props = HashMap::new();
    for index in 0..count {
        let offset = record.body_start + index * 6;
        let id = read_u16(data, offset, part)?;
        if id & 0x8000 == 0 {
            props.insert(id & 0x3fff, read_u32(data, offset + 2, part)?);
        }
    }
    let kind = props.get(&0x0180).copied().unwrap_or(0);
    if !matches!(kind, 4 | 7 | 8) {
        return Ok(None);
    }
    let color = |id| -> Option<u32> {
        let value = *props.get(&id)?;
        if value >> 24 & 8 != 0 {
            biff_palette_color(records, value & 0xffff, part)
        } else {
            ppt_office_art_color(value, None)
        }
    };
    let (Some(start), Some(end)) = (color(0x0181), color(0x0183)) else {
        return Ok(None);
    };
    let angle = props.get(&0x018b).copied().unwrap_or(0) as i32;
    let focus = props.get(&0x018c).copied().unwrap_or(0) as i32;
    Ok(Some(ChartFill::LinearGradient {
        angle_degrees: 90.0 - angle as f32 / 65536.0,
        angle_scaled: false,
        stops: ppt_gradient_stops(start, end, kind, focus, false),
    }))
}

fn parse_msgraph_legend_bounds(record: &BiffRecord<'_>) -> Option<Rect> {
    let read = |offset| {
        record
            .data
            .get(offset..offset + 4)
            .and_then(|bytes| bytes.try_into().ok())
            .map(i32::from_le_bytes)
    };
    let (x, y, width, height) = (read(0)?, read(4)?, read(8)?, read(12)?);
    (x >= 0 && y >= 0 && width > 0 && height > 0).then(|| Rect {
        x: x as f32 / 4000.0,
        y: y as f32 / 4000.0,
        width: width as f32 / 4000.0,
        height: height as f32 / 4000.0,
    })
}

fn parse_msgraph_plot_area_border(records: &[BiffRecord<'_>]) -> Option<(u32, f32)> {
    let plot_area = records.iter().position(|record| record.id == 0x1032)?;
    records[plot_area + 1..]
        .iter()
        .take_while(|record| record.id != 0x1034)
        .find(|record| record.id == 0x1007)
        .and_then(parse_msgraph_line_format)
}

fn parse_msgraph_line_format(record: &BiffRecord<'_>) -> Option<(u32, f32)> {
    let data = record.data;
    let style = u16::from_le_bytes(data.get(4..6)?.try_into().ok()?);
    if style == 5 {
        return None;
    }
    let weight = u16::from_le_bytes(data.get(6..8)?.try_into().ok()?);
    let color = u32::from(*data.first()?) << 24
        | u32::from(*data.get(1)?) << 16
        | u32::from(*data.get(2)?) << 8
        | 0xff;
    Some((
        color,
        [0.75, 1.0, 2.0, 3.0]
            .get(usize::from(weight))
            .copied()
            .unwrap_or(0.75),
    ))
}

fn parse_msgraph_fbi(record: &BiffRecord<'_>) -> Option<(f32, f32, u16)> {
    let data = record.data;
    let width = u16::from_le_bytes(data.get(0..2)?.try_into().ok()?);
    let height = u16::from_le_bytes(data.get(2..4)?.try_into().ok()?);
    let font_index = u16::from_le_bytes(data.get(8..10)?.try_into().ok()?);
    (width > 0 && height > 0).then(|| (f32::from(width), f32::from(height), font_index))
}

fn parse_msgraph_font(record: &BiffRecord<'_>) -> Option<(String, f32, bool)> {
    let data = record.data;
    let height_twips = u16::from_le_bytes(data.get(0..2)?.try_into().ok()?);
    let weight = u16::from_le_bytes(data.get(6..8)?.try_into().ok()?);
    let length = usize::from(*data.get(14)?);
    let unicode = data.get(15).is_some_and(|flags| flags & 0x01 != 0);
    let name = if unicode {
        let bytes = data.get(16..16usize.checked_add(length.checked_mul(2)?)?)?;
        String::from_utf16_lossy(
            &bytes
                .chunks_exact(2)
                .map(|pair| u16::from_le_bytes([pair[0], pair[1]]))
                .collect::<Vec<_>>(),
        )
    } else {
        data.get(16..16usize.checked_add(length)?)?
            .iter()
            .map(|byte| char::from(*byte))
            .collect()
    };
    (!name.is_empty()).then(|| (name, f32::from(height_twips) / 15.0, weight >= 700))
}

/// Extracts a directly embedded raster stream without activating the OLE object.
pub(super) fn parse_embedded_raster(
    bytes: &[u8],
    limits: Limits,
) -> Result<Option<(&'static str, Vec<u8>)>, Diagnostic> {
    if !bytes.starts_with(CFB_MAGIC) {
        return Ok(None);
    }
    let cfb = CompoundFile::open(bytes, limits)?;
    let stream_indexes: Vec<_> = cfb
        .entries
        .iter()
        .enumerate()
        .filter(|(_, entry)| entry.object_type == 2)
        .map(|(index, _)| index)
        .collect();
    for index in stream_indexes {
        let stream = cfb.stream_at(index)?;
        if let Some(offset) = stream.windows(2).position(|header| header == b"BM")
            && let Some(header) = stream.get(offset..)
            && let Some(length) = header
                .get(2..6)
                .and_then(|bytes| <[u8; 4]>::try_from(bytes).ok())
                .map(u32::from_le_bytes)
                .and_then(|length| usize::try_from(length).ok())
            && length >= 18
            && let Some(bitmap) = header.get(..length)
            && bitmap
                .get(14..18)
                .and_then(|bytes| <[u8; 4]>::try_from(bytes).ok())
                .map(u32::from_le_bytes)
                .is_some_and(|size| matches!(size, 12 | 16 | 40 | 52 | 56 | 64 | 108 | 124))
        {
            return Ok(Some(("image/bmp", bitmap.to_vec())));
        }
        if let Some(offset) = stream
            .windows(4)
            .position(|header| matches!(header, b"II*\0" | b"MM\0*"))
        {
            return Ok(Some(("image/tiff", stream[offset..].to_vec())));
        }
    }
    Ok(None)
}

/// Extracts an embedded Rich Text stream without activating the OLE object.
#[cfg(feature = "native-formats")]
pub(super) fn parse_embedded_rtf(
    bytes: &[u8],
    limits: Limits,
) -> Result<Option<Vec<u8>>, Diagnostic> {
    if !bytes.starts_with(CFB_MAGIC) {
        return Ok(None);
    }
    let cfb = CompoundFile::open(bytes, limits)?;
    for index in 0..cfb.entries.len() {
        if cfb.entries[index].object_type != 2 {
            continue;
        }
        let stream = cfb.stream_at(index)?;
        let Some(start) = stream.windows(5).position(|bytes| bytes == b"{\\rtf") else {
            continue;
        };
        let Some(end) = stream.iter().rposition(|byte| *byte == b'}') else {
            continue;
        };
        if end >= start {
            return Ok(Some(stream[start..=end].to_vec()));
        }
    }
    Ok(None)
}

#[cfg(feature = "native-formats")]
pub(super) fn parse_embedded_wordart(
    bytes: &[u8],
    limits: Limits,
) -> Result<Option<String>, Diagnostic> {
    if !bytes.starts_with(CFB_MAGIC) {
        return Ok(None);
    }
    let cfb = CompoundFile::open(bytes, limits)?;
    if !cfb.has_stream("Contents") {
        return Ok(None);
    }
    let contents = cfb.stream("Contents")?;
    let Some(rest) = contents.strip_prefix(b"WordArt \0\x02") else {
        return Ok(None);
    };
    let Some((&length, text)) = rest.split_first() else {
        return Ok(None);
    };
    let Some(text) = text.get(..usize::from(length)) else {
        return Ok(None);
    };
    Ok(std::str::from_utf8(text)
        .ok()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_owned))
}

#[cfg(feature = "native-formats")]
pub(super) fn parse_embedded_equation(
    bytes: &[u8],
    limits: Limits,
) -> Result<Option<String>, Diagnostic> {
    parse_embedded_equation_mtef(bytes, limits, |mtef| {
        if let Some(equation) = parse_mtef3_big_operator(mtef)? {
            return Ok(Some(equation.plain_text()));
        }
        parse_mtef3_equation_text(mtef)
    })
}

fn parse_embedded_equation_mtef<T>(
    bytes: &[u8],
    limits: Limits,
    parser: impl FnOnce(&[u8]) -> Result<Option<T>, Diagnostic>,
) -> Result<Option<T>, Diagnostic> {
    if !bytes.starts_with(CFB_MAGIC) {
        return Ok(None);
    }
    let cfb = CompoundFile::open(bytes, limits)?;
    if !cfb.has_stream("Equation Native") {
        return Ok(None);
    }
    let stream = cfb.stream("Equation Native")?;
    let Some(mtef) = stream.get(28..) else {
        return Ok(None);
    };
    parser(mtef)
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct EmbeddedEquation {
    operator: char,
    upper: String,
    lower: String,
    main: String,
}

impl EmbeddedEquation {
    #[cfg(feature = "native-formats")]
    fn plain_text(&self) -> String {
        format!(
            "{}{}{} {}",
            self.operator,
            superscript(&self.upper),
            subscript(&self.lower),
            self.main
        )
    }
}

fn parse_embedded_equation_parts(
    bytes: &[u8],
    limits: Limits,
) -> Result<Option<EmbeddedEquation>, Diagnostic> {
    parse_embedded_equation_mtef(bytes, limits, parse_mtef3_big_operator)
}

fn parse_mtef3_big_operator(bytes: &[u8]) -> Result<Option<EmbeddedEquation>, Diagnostic> {
    if bytes.get(..5) != Some(&[3, 1, 1, 3, 1]) {
        return Ok(None);
    }
    let mut cursor = 5;
    while bytes
        .get(cursor)
        .is_some_and(|tag| matches!(tag & 0x0f, 9..=14))
    {
        cursor += if bytes[cursor] & 0x0f == 9 { 3 } else { 1 };
    }
    if bytes.get(cursor).map(|tag| tag & 0x0f) != Some(1) {
        return Ok(None);
    }
    cursor += 1;
    let Some(&template) = bytes.get(cursor) else {
        return Ok(None);
    };
    if template & 0x0f != 3 || !matches!(bytes.get(cursor + 1), Some(29 | 30)) {
        return Ok(None);
    }
    cursor += 4;
    let main = parse_simple_mtef3_line(bytes, &mut cursor)?;
    skip_mtef3_sizes(bytes, &mut cursor);
    let lower = parse_simple_mtef3_line(bytes, &mut cursor)?;
    let upper = parse_simple_mtef3_line(bytes, &mut cursor)?;
    skip_mtef3_sizes(bytes, &mut cursor);
    let operator = parse_simple_mtef3_char(bytes, &mut cursor)?.unwrap_or('\u{2211}');
    Ok((!main.is_empty()).then_some(EmbeddedEquation {
        operator,
        upper,
        lower,
        main,
    }))
}

#[cfg(feature = "native-formats")]
fn parse_mtef3_equation_text(bytes: &[u8]) -> Result<Option<String>, Diagnostic> {
    if bytes.get(..4) != Some(&[3, 1, 1, 3]) {
        return Ok(None);
    }
    let mut cursor = 4;
    let Some(text) = parse_mtef3_text_line(bytes, &mut cursor, 0)? else {
        return Ok(None);
    };
    Ok((!text.is_empty()).then_some(text))
}

#[cfg(feature = "native-formats")]
fn parse_mtef3_text_line(
    bytes: &[u8],
    cursor: &mut usize,
    depth: usize,
) -> Result<Option<String>, Diagnostic> {
    // ponytail: bound recursive templates here; promote this to Limits only if MTEF needs a host knob.
    if depth > 64 {
        return Err(format_error(
            "Equation Native",
            "MTEF template nesting exceeds the supported limit",
        ));
    }
    skip_mtef3_sizes(bytes, cursor);
    let Some(&tag) = bytes.get(*cursor) else {
        return Err(format_error("Equation Native", "MTEF line is truncated"));
    };
    if tag & 0x0f != 1 {
        return Ok(None);
    }
    *cursor += 1;
    skip_mtef3_nudge(bytes, cursor, tag)?;
    if tag & 0x10 != 0 {
        return Ok(Some(String::new()));
    }
    if tag & 0x40 != 0 {
        bytes
            .get(*cursor..*cursor + 2)
            .ok_or_else(|| format_error("Equation Native", "MTEF line spacing is truncated"))?;
        *cursor += 2;
    }
    if tag & 0x20 != 0 {
        return Ok(None);
    }
    let mut text = String::new();
    loop {
        skip_mtef3_sizes(bytes, cursor);
        match bytes.get(*cursor).map(|tag| tag & 0x0f) {
            Some(0) => {
                *cursor += 1;
                return Ok(Some(text));
            }
            Some(2) => text.push(
                parse_simple_mtef3_char(bytes, cursor)?
                    .ok_or_else(|| format_error("Equation Native", "invalid MTEF character"))?,
            ),
            Some(3) => {
                let Some(template) = parse_mtef3_text_template(bytes, cursor, depth + 1)? else {
                    return Ok(None);
                };
                text.push_str(&template);
            }
            Some(_) => return Ok(None),
            None => return Err(format_error("Equation Native", "MTEF line is truncated")),
        }
    }
}

#[cfg(feature = "native-formats")]
fn parse_mtef3_text_template(
    bytes: &[u8],
    cursor: &mut usize,
    depth: usize,
) -> Result<Option<String>, Diagnostic> {
    let tag = *bytes
        .get(*cursor)
        .ok_or_else(|| format_error("Equation Native", "MTEF template is truncated"))?;
    *cursor += 1;
    skip_mtef3_nudge(bytes, cursor, tag)?;
    let header = bytes
        .get(*cursor..*cursor + 3)
        .ok_or_else(|| format_error("Equation Native", "MTEF template header is truncated"))?;
    let selector = header[0];
    let variation = u16::from_le_bytes([header[1], header[2]]);
    *cursor += 3;

    let text = match selector {
        14 => {
            let Some(numerator) = parse_mtef3_text_line(bytes, cursor, depth)? else {
                return Ok(None);
            };
            let Some(denominator) = parse_mtef3_text_line(bytes, cursor, depth)? else {
                return Ok(None);
            };
            format!("({numerator})/({denominator})")
        }
        15 => {
            let (subscript, superscript) = match variation {
                0 => (
                    String::new(),
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                ),
                1 => (
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                    String::new(),
                ),
                2 => (
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                ),
                _ => return Ok(None),
            };
            format_scripts(&subscript, &superscript)
        }
        29..=38 => {
            let Some(main) = parse_mtef3_text_line(bytes, cursor, depth)? else {
                return Ok(None);
            };
            let (lower, upper) = match variation {
                0 => (
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                    String::new(),
                ),
                1 => (
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                    parse_mtef3_text_line(bytes, cursor, depth)?.unwrap_or_default(),
                ),
                2 => (String::new(), String::new()),
                _ => return Ok(None),
            };
            skip_mtef3_sizes(bytes, cursor);
            let operator = parse_simple_mtef3_char(bytes, cursor)?.unwrap_or(match selector {
                31 | 32 => '\u{220f}',
                33 | 34 => '\u{2210}',
                35 | 36 => '\u{22c3}',
                37 | 38 => '\u{22c2}',
                _ => '\u{2211}',
            });
            format!("{operator}{} {main}", format_scripts(&lower, &upper))
        }
        _ => return Ok(None),
    };
    if bytes.get(*cursor).map(|tag| tag & 0x0f) != Some(0) {
        return Err(format_error(
            "Equation Native",
            "MTEF template terminator is missing",
        ));
    }
    *cursor += 1;
    Ok(Some(text))
}

#[cfg(feature = "native-formats")]
fn format_scripts(subscript: &str, superscript: &str) -> String {
    let mut text = String::new();
    if !subscript.is_empty() {
        text.push_str(&format!("_{{{subscript}}}"));
    }
    if !superscript.is_empty() {
        text.push_str(&format!("^{{{superscript}}}"));
    }
    text
}

fn skip_mtef3_nudge(bytes: &[u8], cursor: &mut usize, tag: u8) -> Result<(), Diagnostic> {
    if tag & 0x80 == 0 {
        return Ok(());
    }
    let nudge = bytes
        .get(*cursor..*cursor + 2)
        .ok_or_else(|| format_error("Equation Native", "MTEF nudge is truncated"))?;
    *cursor += if nudge == [128, 128] { 6 } else { 2 };
    if *cursor > bytes.len() {
        return Err(format_error("Equation Native", "MTEF nudge is truncated"));
    }
    Ok(())
}

fn skip_mtef3_sizes(bytes: &[u8], cursor: &mut usize) {
    while bytes
        .get(*cursor)
        .is_some_and(|tag| matches!(tag & 0x0f, 10..=14))
    {
        *cursor += 1;
    }
}

fn parse_simple_mtef3_line(bytes: &[u8], cursor: &mut usize) -> Result<String, Diagnostic> {
    if bytes.get(*cursor).map(|tag| tag & 0x0f) != Some(1) {
        return Err(format_error("Equation Native", "MTEF line is missing"));
    }
    *cursor += 1;
    let mut text = String::new();
    loop {
        skip_mtef3_sizes(bytes, cursor);
        if bytes.get(*cursor).map(|tag| tag & 0x0f) == Some(0) {
            *cursor += 1;
            return Ok(text);
        }
        let Some(character) = parse_simple_mtef3_char(bytes, cursor)? else {
            return Err(format_error(
                "Equation Native",
                "unsupported MTEF line record",
            ));
        };
        text.push(character);
    }
}

fn parse_simple_mtef3_char(bytes: &[u8], cursor: &mut usize) -> Result<Option<char>, Diagnostic> {
    let Some(&tag) = bytes.get(*cursor) else {
        return Err(format_error(
            "Equation Native",
            "MTEF character is truncated",
        ));
    };
    if tag & 0x0f != 2 {
        return Ok(None);
    }
    *cursor += 1;
    skip_mtef3_nudge(bytes, cursor, tag)?;
    *cursor += 1;
    let value = read_u16(bytes, *cursor, "MTEF character")?;
    *cursor += 2;
    Ok(char::from_u32(u32::from(value)))
}

#[cfg(feature = "native-formats")]
fn superscript(value: &str) -> String {
    value
        .chars()
        .map(|character| match character {
            '0' => '\u{2070}',
            '1' => '\u{00b9}',
            '2' => '\u{00b2}',
            '3' => '\u{00b3}',
            '4' => '\u{2074}',
            '5' => '\u{2075}',
            '6' => '\u{2076}',
            '7' => '\u{2077}',
            '8' => '\u{2078}',
            '9' => '\u{2079}',
            _ => character,
        })
        .collect()
}

#[cfg(feature = "native-formats")]
fn subscript(value: &str) -> String {
    value
        .chars()
        .map(|character| match character {
            '0' => '\u{2080}',
            '1' => '\u{2081}',
            '2' => '\u{2082}',
            '3' => '\u{2083}',
            '4' => '\u{2084}',
            '5' => '\u{2085}',
            '6' => '\u{2086}',
            '7' => '\u{2087}',
            '8' => '\u{2088}',
            '9' => '\u{2089}',
            _ => character,
        })
        .collect()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum LegacyKind {
    Doc,
    Xls,
    Ppt,
}

/// Shared semantic scene consumed by the format-independent renderer.
///
/// Binary decoders keep their format-specific records, then materialize the
/// same bounded `Document`/`Unit`/`Object`/`Visual` contract here.
struct LegacyScene {
    document: Document,
    object_limit: usize,
}

impl LegacyScene {
    fn new(
        format: DocumentFormat,
        kind: DocumentKind,
        limits: Limits,
        diagnostics: Vec<Diagnostic>,
    ) -> Self {
        Self {
            document: Document {
                fatal: false,
                format: Some(format),
                kind: Some(kind),
                units: Vec::new(),
                outline: Vec::new(),
                objects: Vec::new(),
                embedded_fonts: Vec::new(),
                font_alternate_names: Vec::new(),
                diagnostics,
            },
            object_limit: limits.max_document_objects,
        }
    }

    fn push_unit(
        &mut self,
        part: &str,
        build: impl FnOnce(u32) -> Unit,
    ) -> Result<u32, Diagnostic> {
        let index = u32::try_from(self.units.len())
            .map_err(|_| object_limit("legacy unit index exceeds supported range").in_part(part))?;
        self.units.push(build(index));
        Ok(index)
    }

    fn push_object(
        &mut self,
        part: &str,
        build: impl FnOnce(u32) -> Object,
    ) -> Result<usize, Diagnostic> {
        if self.objects.len() >= self.object_limit {
            return Err(
                object_limit("legacy scene exceeds the configured object limit").in_part(part),
            );
        }
        let index = self.objects.len();
        let numeric_id = u32::try_from(index)
            .map_err(|_| object_limit("legacy object id exceeds supported range").in_part(part))?;
        self.objects.push(build(numeric_id));
        Ok(index)
    }

    fn finish(self) -> Document {
        self.document
    }
}

impl std::ops::Deref for LegacyScene {
    type Target = Document;

    fn deref(&self) -> &Self::Target {
        &self.document
    }
}

impl std::ops::DerefMut for LegacyScene {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.document
    }
}

#[derive(Clone, Debug)]
struct DirectoryEntry {
    slot: usize,
    name: String,
    object_type: u8,
    left_sibling: u32,
    right_sibling: u32,
    child: u32,
    parent_slot: Option<usize>,
    start_sector: u32,
    stream_size: usize,
}

struct CompoundFile<'a> {
    bytes: &'a [u8],
    limits: Limits,
    sector_size: usize,
    sector_count: usize,
    mini_sector_size: usize,
    mini_stream_cutoff: usize,
    fat: Vec<u32>,
    mini_fat: Vec<u32>,
    mini_stream: Vec<u8>,
    entries: Vec<DirectoryEntry>,
    diagnostics: Vec<Diagnostic>,
}

impl<'a> CompoundFile<'a> {
    fn open(bytes: &'a [u8], limits: Limits) -> Result<Self, Diagnostic> {
        if bytes.len() < CFB_HEADER_BYTES {
            return Err(container_error("OLE header is truncated"));
        }
        if read_u16(bytes, 28, "OLE header")? != 0xfffe {
            return Err(container_error("OLE byte order must be little-endian"));
        }
        let major_version = read_u16(bytes, 26, "OLE header")?;
        let sector_shift = read_u16(bytes, 30, "OLE header")?;
        let mini_sector_shift = read_u16(bytes, 32, "OLE header")?;
        let (expected_sector_shift, expected_directory_sectors) = match major_version {
            3 => (9, None),
            4 => (12, Some(read_u32(bytes, 40, "OLE header")? as usize)),
            _ => return Err(container_error("unsupported OLE major version")),
        };
        if sector_shift != expected_sector_shift || mini_sector_shift != 6 {
            return Err(container_error("invalid OLE sector geometry"));
        }
        let sector_size = 1usize
            .checked_shl(u32::from(sector_shift))
            .ok_or_else(|| container_error("OLE sector size overflows"))?;
        let mini_sector_size = 1usize
            .checked_shl(u32::from(mini_sector_shift))
            .ok_or_else(|| container_error("OLE mini-sector size overflows"))?;
        if bytes.len() < sector_size {
            return Err(container_error(
                "OLE file contains no complete header sector",
            ));
        }
        let data_bytes = bytes.len() - sector_size;
        let trailing_bytes = data_bytes % sector_size;
        let sector_count = data_bytes.div_ceil(sector_size);
        if sector_count == 0 || sector_count > u32::MAX as usize {
            return Err(container_error("OLE file contains no usable sectors"));
        }

        let mini_stream_cutoff = read_u32(bytes, 56, "OLE header")? as usize;
        if mini_stream_cutoff != CFB_MINI_STREAM_CUTOFF {
            return Err(container_error("invalid OLE mini-stream cutoff"));
        }
        let fat_sector_count = read_u32(bytes, 44, "OLE header")? as usize;
        if fat_sector_count == 0 || fat_sector_count > sector_count {
            return Err(container_error("invalid OLE FAT sector count"));
        }
        let first_directory_sector = read_u32(bytes, 48, "OLE header")?;
        let first_mini_fat_sector = read_u32(bytes, 60, "OLE header")?;
        let mini_fat_sector_count = read_u32(bytes, 64, "OLE header")? as usize;
        let first_difat_sector = read_u32(bytes, 68, "OLE header")?;
        let difat_sector_count = read_u32(bytes, 72, "OLE header")? as usize;
        if mini_fat_sector_count > sector_count || difat_sector_count > sector_count {
            return Err(container_error("OLE allocation-table count is impossible"));
        }

        let mut fat_sector_ids = Vec::new();
        fat_sector_ids
            .try_reserve_exact(fat_sector_count)
            .map_err(|_| allocation_error("OLE FAT sector list"))?;
        for index in 0..109usize {
            let sector = read_u32(bytes, 76 + index * 4, "OLE DIFAT header")?;
            if sector != FREE_SECTOR {
                push_unique_sector(
                    &mut fat_sector_ids,
                    sector,
                    sector_count,
                    fat_sector_count,
                    "OLE DIFAT header",
                )?;
            }
        }

        let mut difat_seen = allocate_seen(sector_count, "OLE DIFAT cycle map")?;
        let mut difat_sector = first_difat_sector;
        for index in 0..difat_sector_count {
            let sector_index = checked_sector_index(difat_sector, sector_count, "OLE DIFAT")?;
            if std::mem::replace(&mut difat_seen[sector_index], true) {
                return Err(container_error("OLE DIFAT chain contains a cycle"));
            }
            let sector = sector_bytes(bytes, sector_size, difat_sector, sector_count, "OLE DIFAT")?;
            let entries_per_sector = sector_size / 4 - 1;
            for entry_index in 0..entries_per_sector {
                let fat_sector = read_u32(sector, entry_index * 4, "OLE DIFAT sector")?;
                if fat_sector != FREE_SECTOR {
                    push_unique_sector(
                        &mut fat_sector_ids,
                        fat_sector,
                        sector_count,
                        fat_sector_count,
                        "OLE DIFAT sector",
                    )?;
                }
            }
            let next = read_u32(sector, entries_per_sector * 4, "OLE DIFAT sector trailer")?;
            if index + 1 == difat_sector_count {
                if next != END_OF_CHAIN {
                    return Err(container_error("OLE DIFAT chain does not terminate"));
                }
            } else {
                difat_sector = next;
            }
        }
        if difat_sector_count == 0 && !matches!(first_difat_sector, END_OF_CHAIN | FREE_SECTOR) {
            return Err(container_error("OLE header has an undeclared DIFAT chain"));
        }
        if fat_sector_ids.len() != fat_sector_count {
            return Err(container_error(
                "OLE DIFAT does not contain the declared FAT sector count",
            ));
        }

        let fat_entries = fat_sector_count
            .checked_mul(sector_size / 4)
            .ok_or_else(|| container_error("OLE FAT size overflows"))?;
        let mut fat = Vec::new();
        fat.try_reserve_exact(fat_entries)
            .map_err(|_| allocation_error("OLE FAT"))?;
        for &sector_id in &fat_sector_ids {
            let sector = sector_bytes(bytes, sector_size, sector_id, sector_count, "OLE FAT")?;
            for offset in (0..sector_size).step_by(4) {
                fat.push(read_u32(sector, offset, "OLE FAT")?);
            }
        }
        if fat.len() < sector_count {
            return Err(container_error("OLE FAT does not cover every file sector"));
        }
        let mut diagnostics = Vec::new();
        for &sector_id in &fat_sector_ids {
            let index = sector_id as usize;
            match fat[index] {
                FAT_SECTOR => {}
                // A small set of legacy producers incorrectly mark the FAT's
                // own sector as a one-sector chain. The DIFAT still assigns
                // its role unambiguously, so accepting EOC is safe as long as
                // ordinary chains cannot consume reserved-role sectors.
                END_OF_CHAIN => diagnostics.push(
                    Diagnostic::warning(
                        DiagnosticCode::UnsupportedFeature,
                        Phase::Container,
                        Fidelity::Approximate,
                        "OLE producer marked a DIFAT-assigned FAT sector as end-of-chain",
                    )
                    .in_part("OLE FAT"),
                ),
                _ => return Err(container_error("OLE FAT sector is not marked as FAT")),
            }
            // Normalize the internal allocation map so no ordinary stream can
            // consume this DIFAT-assigned reserved sector.
            fat[index] = FAT_SECTOR;
        }
        for (sector_id, used) in difat_seen.iter().enumerate() {
            if *used && fat[sector_id] != DIFAT_SECTOR {
                return Err(container_error("OLE DIFAT sector is not marked as DIFAT"));
            }
        }
        let mut sector_roles = allocate_sector_roles(sector_count, "OLE sector ownership map")?;
        claim_regular_sectors(&mut sector_roles, &fat_sector_ids, "OLE FAT")?;
        for (sector, used) in difat_seen.iter().enumerate() {
            if *used {
                claim_regular_sectors(&mut sector_roles, &[sector as u32], "OLE DIFAT")?;
            }
        }

        let max_directory_bytes = limits
            .max_zip_entries
            .saturating_mul(DIRECTORY_ENTRY_BYTES)
            .min(limits.max_total_uncompressed_bytes);
        let max_directory_sectors = max_directory_bytes
            .checked_add(sector_size - 1)
            .ok_or_else(|| container_error("OLE directory limit overflows"))?
            / sector_size;
        let directory_sector_ids = regular_chain_to_end(
            &fat,
            first_directory_sector,
            sector_count,
            max_directory_sectors,
            "OLE directory",
        )?;
        claim_regular_sectors(&mut sector_roles, &directory_sector_ids, "OLE directory")?;
        if let Some(expected) = expected_directory_sectors
            && directory_sector_ids.len() != expected
        {
            return Err(container_error(
                "OLE directory chain length differs from its header count",
            ));
        }
        let directory_bytes = copy_regular_sectors(
            bytes,
            sector_size,
            sector_count,
            &directory_sector_ids,
            max_directory_bytes,
            "OLE directory",
        )?;
        let entries = parse_directory(&directory_bytes, major_version, limits)?;
        let mut roots = entries.iter().filter(|entry| entry.object_type == 5);
        let Some(root) = roots.next() else {
            return Err(container_error(
                "OLE directory must contain exactly one root entry",
            ));
        };
        if roots.next().is_some() {
            return Err(container_error(
                "OLE directory must contain exactly one root entry",
            ));
        }
        let root_start_sector = root.start_sector;
        let root_stream_size = root.stream_size;

        let mini_fat = if mini_fat_sector_count == 0 {
            if !matches!(first_mini_fat_sector, END_OF_CHAIN | FREE_SECTOR) {
                return Err(container_error(
                    "OLE header has an undeclared miniFAT chain",
                ));
            }
            Vec::new()
        } else {
            let sectors = regular_chain_exact(
                &fat,
                first_mini_fat_sector,
                sector_count,
                mini_fat_sector_count,
                "OLE miniFAT",
            )?;
            claim_regular_sectors(&mut sector_roles, &sectors, "OLE miniFAT")?;
            let bytes = copy_regular_sectors(
                bytes,
                sector_size,
                sector_count,
                &sectors,
                limits.max_entry_uncompressed_bytes,
                "OLE miniFAT",
            )?;
            let mut table = Vec::new();
            table
                .try_reserve_exact(bytes.len() / 4)
                .map_err(|_| allocation_error("OLE miniFAT"))?;
            for offset in (0..bytes.len()).step_by(4) {
                table.push(read_u32(&bytes, offset, "OLE miniFAT")?);
            }
            table
        };

        if root_stream_size > limits.max_total_uncompressed_bytes {
            return Err(limit_error(
                "OLE root mini-stream exceeds the configured total byte limit",
            ));
        }
        let mini_stream = if root_stream_size == 0 {
            Vec::new()
        } else {
            let expected_sectors = root_stream_size
                .checked_add(sector_size - 1)
                .ok_or_else(|| container_error("OLE root mini-stream size overflows"))?
                / sector_size;
            let sectors = regular_chain_exact(
                &fat,
                root_start_sector,
                sector_count,
                expected_sectors,
                "OLE root mini-stream",
            )?;
            claim_regular_sectors(&mut sector_roles, &sectors, "OLE root mini-stream")?;
            let mut stream = copy_regular_sectors(
                bytes,
                sector_size,
                sector_count,
                &sectors,
                limits.max_total_uncompressed_bytes,
                "OLE root mini-stream",
            )?;
            stream.truncate(root_stream_size);
            stream
        };

        validate_stream_chain_ownership(
            &entries,
            mini_stream_cutoff,
            sector_size,
            mini_sector_size,
            &fat,
            &mini_fat,
            mini_stream.len(),
            sector_count,
            &mut sector_roles,
            trailing_bytes,
        )?;
        if trailing_bytes != 0 {
            let partial_sector = sector_count - 1;
            let message = if sector_roles[partial_sector] == 0 {
                format!(
                    "OLE producer appended {trailing_bytes} byte(s) outside the allocated sector graph; trailing data was ignored"
                )
            } else {
                format!(
                    "OLE producer omitted {} unused padding byte(s) from a referenced final stream sector; all declared stream bytes are present",
                    sector_size - trailing_bytes
                )
            };
            diagnostics.push(
                Diagnostic::warning(
                    DiagnosticCode::UnsupportedFeature,
                    Phase::Container,
                    Fidelity::Approximate,
                    message,
                )
                .in_part("OLE container"),
            );
        }

        Ok(Self {
            bytes,
            limits,
            sector_size,
            sector_count,
            mini_sector_size,
            mini_stream_cutoff,
            fat,
            mini_fat,
            mini_stream,
            entries,
            diagnostics,
        })
    }

    fn has_stream(&self, name: &str) -> bool {
        self.entries.iter().any(|entry| {
            entry.object_type == 2
                && entry.parent_slot == Some(0)
                && entry.name.eq_ignore_ascii_case(name)
        })
    }

    fn stream(&self, name: &str) -> Result<Vec<u8>, Diagnostic> {
        let index = self
            .entries
            .iter()
            .position(|entry| {
                entry.object_type == 2
                    && entry.parent_slot == Some(0)
                    && entry.name.eq_ignore_ascii_case(name)
            })
            .ok_or_else(|| format_error(name, format!("required OLE stream is missing: {name}")))?;
        self.stream_at(index)
    }

    fn stream_at(&self, index: usize) -> Result<Vec<u8>, Diagnostic> {
        let entry = self
            .entries
            .get(index)
            .filter(|entry| entry.object_type == 2)
            .ok_or_else(|| format_error("OLE directory", "requested OLE stream is missing"))?;
        let name = entry.name.as_str();
        if entry.stream_size > self.limits.max_entry_uncompressed_bytes {
            return Err(limit_error(format!(
                "OLE stream {name} exceeds the configured entry byte limit"
            ))
            .in_part(name));
        }
        if entry.stream_size == 0 {
            return Ok(Vec::new());
        }
        if entry.stream_size < self.mini_stream_cutoff {
            return read_mini_stream(
                &self.mini_stream,
                self.mini_sector_size,
                &self.mini_fat,
                entry.start_sector,
                entry.stream_size,
                self.limits.max_entry_uncompressed_bytes,
                name,
            );
        }
        read_regular_stream(
            self.bytes,
            self.sector_size,
            self.sector_count,
            &self.fat,
            entry.start_sector,
            entry.stream_size,
            self.limits.max_entry_uncompressed_bytes,
            name,
        )
    }

    fn security_diagnostics(&self) -> Vec<Diagnostic> {
        let has_macros = self.entries.iter().any(|entry| {
            entry.object_type == 1 && entry.name.eq_ignore_ascii_case("VBA")
                || entry.object_type == 2
                    && matches!(
                        entry.name.to_ascii_lowercase().as_str(),
                        "_vba_project" | "project" | "projectwm" | "macros"
                    )
        });
        let has_embedded_objects = self.entries.iter().any(|entry| {
            entry.name.eq_ignore_ascii_case("ObjectPool") || entry.name.eq_ignore_ascii_case("MBD")
        });
        let mut diagnostics = self.diagnostics.clone();
        if has_macros {
            diagnostics.push(
                Diagnostic::warning(
                    DiagnosticCode::ActiveContentBlocked,
                    Phase::Security,
                    Fidelity::Blocked,
                    "legacy Office macros were detected and will not execute",
                )
                .in_part("OLE directory"),
            );
        }
        if has_embedded_objects {
            diagnostics.push(
                Diagnostic::warning(
                    DiagnosticCode::ActiveContentBlocked,
                    Phase::Security,
                    Fidelity::Blocked,
                    "embedded OLE objects are not activated by the read-only parser",
                )
                .in_part("OLE directory"),
            );
        }
        diagnostics
    }
}

fn parse_directory(
    bytes: &[u8],
    major_version: u16,
    limits: Limits,
) -> Result<Vec<DirectoryEntry>, Diagnostic> {
    if bytes.is_empty() || !bytes.len().is_multiple_of(DIRECTORY_ENTRY_BYTES) {
        return Err(container_error("OLE directory stream is malformed"));
    }
    let slot_count = bytes.len() / DIRECTORY_ENTRY_BYTES;
    if slot_count > limits.max_zip_entries {
        return Err(limit_error(
            "OLE directory exceeds the configured entry limit",
        ));
    }
    let mut entries = Vec::new();
    entries
        .try_reserve(slot_count.min(limits.max_zip_entries))
        .map_err(|_| allocation_error("OLE directory entries"))?;
    for (slot, entry) in bytes.chunks_exact(DIRECTORY_ENTRY_BYTES).enumerate() {
        let object_type = entry[66];
        if object_type == 0 {
            continue;
        }
        if !matches!(object_type, 1 | 2 | 5) {
            return Err(container_error(format!(
                "OLE directory entry {slot} has an unsupported object type"
            )));
        }
        if !matches!(entry[67], 0 | 1) {
            return Err(container_error(format!(
                "OLE directory entry {slot} has an invalid tree color"
            )));
        }
        let name_bytes = read_u16(entry, 64, "OLE directory name")? as usize;
        if !(2..=64).contains(&name_bytes) || !name_bytes.is_multiple_of(2) {
            return Err(container_error(format!(
                "OLE directory entry {slot} has an invalid name length"
            )));
        }
        let unit_count = name_bytes / 2;
        let mut units = Vec::new();
        units
            .try_reserve_exact(unit_count)
            .map_err(|_| allocation_error("OLE directory name"))?;
        for offset in (0..name_bytes).step_by(2) {
            units.push(read_u16(entry, offset, "OLE directory name")?);
        }
        if units.last() != Some(&0) || units[..units.len() - 1].contains(&0) {
            return Err(container_error(format!(
                "OLE directory entry {slot} has an invalid terminated name"
            )));
        }
        units.pop();
        let name = String::from_utf16(&units).map_err(|_| {
            container_error(format!(
                "OLE directory entry {slot} name is not valid UTF-16"
            ))
        })?;
        if name.is_empty() {
            return Err(container_error(format!(
                "OLE directory entry {slot} has an empty name"
            )));
        }
        let stream_size_u64 = read_u64(entry, 120, "OLE directory stream size")?;
        let stream_size_u64 = if major_version == 3 {
            stream_size_u64 & u64::from(u32::MAX)
        } else {
            stream_size_u64
        };
        let stream_size = usize::try_from(stream_size_u64)
            .map_err(|_| limit_error("OLE stream size exceeds this platform"))?;
        entries.push(DirectoryEntry {
            slot,
            name,
            object_type,
            left_sibling: read_u32(entry, 68, "OLE directory left sibling")?,
            right_sibling: read_u32(entry, 72, "OLE directory right sibling")?,
            child: read_u32(entry, 76, "OLE directory child")?,
            parent_slot: None,
            start_sector: read_u32(entry, 116, "OLE directory start sector")?,
            stream_size,
        });
    }
    validate_directory_tree(entries, slot_count)
}

fn validate_directory_tree(
    mut entries: Vec<DirectoryEntry>,
    slot_count: usize,
) -> Result<Vec<DirectoryEntry>, Diagnostic> {
    let root_index = entries
        .iter()
        .position(|entry| entry.slot == 0 && entry.object_type == 5)
        .ok_or_else(|| container_error("OLE directory slot zero is not the root entry"))?;
    if entries
        .iter()
        .filter(|entry| entry.object_type == 5)
        .count()
        != 1
    {
        return Err(container_error(
            "OLE directory must contain exactly one root entry",
        ));
    }
    if !matches!(entries[root_index].left_sibling, FREE_SECTOR)
        || !matches!(entries[root_index].right_sibling, FREE_SECTOR)
    {
        return Err(container_error("OLE root entry has sibling links"));
    }
    let mut by_slot = Vec::new();
    by_slot
        .try_reserve_exact(slot_count)
        .map_err(|_| allocation_error("OLE directory slot map"))?;
    by_slot.resize(slot_count, None);
    for (index, entry) in entries.iter().enumerate() {
        by_slot[entry.slot] = Some(index);
    }
    let mut visited = allocate_seen(slot_count, "OLE directory reachability map")?;
    visited[0] = true;
    let root_child = entries[root_index].child;
    visit_directory_sibling_tree(root_child, 0, &mut entries, &by_slot, &mut visited)?;

    // Active orphan slots can exist in damaged files, but they are not members
    // of the root storage and therefore must never participate in detection.
    entries.retain(|entry| entry.slot == 0 || visited[entry.slot]);
    let mut sibling_names = HashSet::new();
    for entry in entries.iter().filter(|entry| entry.object_type != 5) {
        let parent = entry
            .parent_slot
            .ok_or_else(|| container_error("reachable OLE entry has no parent storage"))?;
        if !sibling_names.insert((parent, entry.name.to_ascii_lowercase())) {
            return Err(container_error(format!(
                "OLE storage contains a duplicate child name: {}",
                entry.name
            )));
        }
    }
    Ok(entries)
}

fn visit_directory_sibling_tree(
    slot: u32,
    parent_slot: usize,
    entries: &mut [DirectoryEntry],
    by_slot: &[Option<usize>],
    visited: &mut [bool],
) -> Result<(), Diagnostic> {
    let mut stack = Vec::new();
    stack
        .try_reserve_exact(visited.len())
        .map_err(|_| allocation_error("OLE directory traversal stack"))?;
    if slot != FREE_SECTOR {
        stack.push((slot, parent_slot));
    }
    while let Some((slot, parent_slot)) = stack.pop() {
        let slot = usize::try_from(slot)
            .map_err(|_| container_error("OLE directory link exceeds supported range"))?;
        let entry_index = by_slot
            .get(slot)
            .and_then(|index| *index)
            .ok_or_else(|| container_error("OLE directory link targets an unused slot"))?;
        if std::mem::replace(&mut visited[slot], true) {
            return Err(container_error(
                "OLE directory tree contains a cycle or duplicate parent",
            ));
        }
        if entries[entry_index].object_type == 5 {
            return Err(container_error(
                "OLE root entry appears inside its child tree",
            ));
        }
        entries[entry_index].parent_slot = Some(parent_slot);
        let left = entries[entry_index].left_sibling;
        let right = entries[entry_index].right_sibling;
        let child = entries[entry_index].child;
        let object_type = entries[entry_index].object_type;
        if object_type != 1 && child != FREE_SECTOR {
            return Err(container_error("OLE stream entry has a child tree"));
        }
        for (link, link_parent) in [
            (right, parent_slot),
            (if object_type == 1 { child } else { FREE_SECTOR }, slot),
            (left, parent_slot),
        ] {
            if link == FREE_SECTOR {
                continue;
            }
            if stack.len() >= visited.len() {
                return Err(container_error(
                    "OLE directory traversal exceeds the directory slot bound",
                ));
            }
            stack.push((link, link_parent));
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn read_regular_stream(
    bytes: &[u8],
    sector_size: usize,
    sector_count: usize,
    fat: &[u32],
    start: u32,
    size: usize,
    max_bytes: usize,
    part: &str,
) -> Result<Vec<u8>, Diagnostic> {
    if size > max_bytes {
        return Err(limit_error(format!("{part} exceeds its configured byte limit")).in_part(part));
    }
    let expected_sectors = size
        .checked_add(sector_size - 1)
        .ok_or_else(|| format_error(part, "stream sector count overflows"))?
        / sector_size;
    let chain = regular_chain_exact(fat, start, sector_count, expected_sectors, part)?;
    let mut output = Vec::new();
    output
        .try_reserve_exact(size)
        .map_err(|_| allocation_error(part))?;
    for sector in chain {
        let index = checked_sector_index(sector, sector_count, part)?;
        let offset = (index + 1)
            .checked_mul(sector_size)
            .ok_or_else(|| format_error(part, "OLE sector offset overflows"))?;
        let required = (size - output.len()).min(sector_size);
        let end = offset
            .checked_add(required)
            .ok_or_else(|| format_error(part, "OLE stream sector end overflows"))?;
        let available = bytes
            .get(offset..end)
            .ok_or_else(|| format_error(part, "OLE stream is truncated inside its sector"))?;
        output.extend_from_slice(available);
    }
    Ok(output)
}

fn read_mini_stream(
    root_stream: &[u8],
    mini_sector_size: usize,
    mini_fat: &[u32],
    start: u32,
    size: usize,
    max_bytes: usize,
    part: &str,
) -> Result<Vec<u8>, Diagnostic> {
    if size > max_bytes {
        return Err(limit_error(format!("{part} exceeds its configured byte limit")).in_part(part));
    }
    let expected = size
        .checked_add(mini_sector_size - 1)
        .ok_or_else(|| format_error(part, "mini-stream sector count overflows"))?
        / mini_sector_size;
    if expected == 0 {
        return Ok(Vec::new());
    }
    if mini_fat.is_empty() {
        return Err(format_error(part, "OLE mini-stream has no miniFAT"));
    }
    let mut seen = allocate_seen(mini_fat.len(), "OLE mini-stream cycle map")?;
    let mut current = start;
    let mut output = Vec::new();
    output
        .try_reserve_exact(size)
        .map_err(|_| allocation_error(part))?;
    for _ in 0..expected {
        let index = checked_sector_index(current, mini_fat.len(), part)?;
        if std::mem::replace(&mut seen[index], true) {
            return Err(format_error(part, "OLE mini-stream chain contains a cycle"));
        }
        let offset = index
            .checked_mul(mini_sector_size)
            .ok_or_else(|| format_error(part, "mini-sector offset overflows"))?;
        let end = offset
            .checked_add(mini_sector_size)
            .ok_or_else(|| format_error(part, "mini-sector end overflows"))?;
        let sector = root_stream
            .get(offset..end)
            .ok_or_else(|| format_error(part, "mini-sector lies outside the root stream"))?;
        let remaining = size - output.len();
        output.extend_from_slice(&sector[..remaining.min(mini_sector_size)]);
        current = mini_fat[index];
    }
    if current != END_OF_CHAIN {
        return Err(format_error(
            part,
            "OLE mini-stream chain length differs from its declared size",
        ));
    }
    Ok(output)
}

fn regular_chain_exact(
    fat: &[u32],
    start: u32,
    sector_count: usize,
    expected: usize,
    part: &str,
) -> Result<Vec<u32>, Diagnostic> {
    if expected == 0 {
        if !matches!(start, END_OF_CHAIN | FREE_SECTOR) {
            return Err(format_error(
                part,
                "empty OLE stream has an allocated chain",
            ));
        }
        return Ok(Vec::new());
    }
    let mut seen = allocate_seen(sector_count, "OLE chain cycle map")?;
    let mut chain = Vec::new();
    chain
        .try_reserve_exact(expected)
        .map_err(|_| allocation_error(part))?;
    let mut current = start;
    for _ in 0..expected {
        let index = checked_sector_index(current, sector_count, part)?;
        if std::mem::replace(&mut seen[index], true) {
            return Err(format_error(part, "OLE sector chain contains a cycle"));
        }
        chain.push(current);
        current = *fat
            .get(index)
            .ok_or_else(|| format_error(part, "OLE FAT lookup is out of bounds"))?;
    }
    if current != END_OF_CHAIN {
        return Err(format_error(
            part,
            "OLE sector chain length differs from its declared size",
        ));
    }
    Ok(chain)
}

fn regular_chain_to_end(
    fat: &[u32],
    start: u32,
    sector_count: usize,
    max_sectors: usize,
    part: &str,
) -> Result<Vec<u32>, Diagnostic> {
    if max_sectors == 0 {
        return Err(limit_error(format!("{part} has no available chain budget")));
    }
    let mut seen = allocate_seen(sector_count, "OLE chain cycle map")?;
    let mut chain = Vec::new();
    chain
        .try_reserve(max_sectors.min(sector_count))
        .map_err(|_| allocation_error(part))?;
    let mut current = start;
    loop {
        if chain.len() >= max_sectors {
            return Err(
                limit_error(format!("{part} exceeds its configured chain limit")).in_part(part),
            );
        }
        let index = checked_sector_index(current, sector_count, part)?;
        if std::mem::replace(&mut seen[index], true) {
            return Err(format_error(part, "OLE sector chain contains a cycle"));
        }
        chain.push(current);
        current = *fat
            .get(index)
            .ok_or_else(|| format_error(part, "OLE FAT lookup is out of bounds"))?;
        if current == END_OF_CHAIN {
            break;
        }
    }
    Ok(chain)
}

fn copy_regular_sectors(
    bytes: &[u8],
    sector_size: usize,
    sector_count: usize,
    sectors: &[u32],
    max_bytes: usize,
    part: &str,
) -> Result<Vec<u8>, Diagnostic> {
    let byte_count = sectors
        .len()
        .checked_mul(sector_size)
        .ok_or_else(|| format_error(part, "OLE chain byte count overflows"))?;
    if byte_count > max_bytes {
        return Err(limit_error(format!("{part} exceeds its configured byte limit")).in_part(part));
    }
    let mut output = Vec::new();
    output
        .try_reserve_exact(byte_count)
        .map_err(|_| allocation_error(part))?;
    for &sector in sectors {
        output.extend_from_slice(sector_bytes(
            bytes,
            sector_size,
            sector,
            sector_count,
            part,
        )?);
    }
    Ok(output)
}

fn sector_bytes<'a>(
    bytes: &'a [u8],
    sector_size: usize,
    sector: u32,
    sector_count: usize,
    part: &str,
) -> Result<&'a [u8], Diagnostic> {
    let index = checked_sector_index(sector, sector_count, part)?;
    let offset = (index + 1)
        .checked_mul(sector_size)
        .ok_or_else(|| format_error(part, "OLE sector offset overflows"))?;
    bytes
        .get(offset..offset + sector_size)
        .ok_or_else(|| format_error(part, "OLE sector is truncated"))
}

fn checked_sector_index(sector: u32, sector_count: usize, part: &str) -> Result<usize, Diagnostic> {
    if sector > MAX_REGULAR_SECTOR {
        return Err(format_error(
            part,
            "OLE chain references a reserved sector id",
        ));
    }
    let index = sector as usize;
    if index >= sector_count {
        return Err(format_error(part, "OLE chain references a sector past EOF"));
    }
    Ok(index)
}

fn push_unique_sector(
    sectors: &mut Vec<u32>,
    sector: u32,
    sector_count: usize,
    maximum: usize,
    part: &str,
) -> Result<(), Diagnostic> {
    checked_sector_index(sector, sector_count, part)?;
    if sectors.contains(&sector) {
        return Err(container_error(format!(
            "{part} contains a duplicate FAT sector"
        )));
    }
    if sectors.len() >= maximum {
        return Err(container_error(format!(
            "{part} contains more FAT sectors than declared"
        )));
    }
    sectors.push(sector);
    Ok(())
}

fn allocate_seen(length: usize, label: &str) -> Result<Vec<bool>, Diagnostic> {
    let mut seen = Vec::new();
    seen.try_reserve_exact(length)
        .map_err(|_| allocation_error(label))?;
    seen.resize(length, false);
    Ok(seen)
}

fn allocate_sector_roles(length: usize, label: &str) -> Result<Vec<u32>, Diagnostic> {
    let mut roles = Vec::new();
    roles
        .try_reserve_exact(length)
        .map_err(|_| allocation_error(label))?;
    roles.resize(length, 0);
    Ok(roles)
}

fn claim_regular_sectors(roles: &mut [u32], sectors: &[u32], role: &str) -> Result<(), Diagnostic> {
    for &sector in sectors {
        let index = usize::try_from(sector)
            .map_err(|_| container_error("OLE sector id exceeds supported range"))?;
        let assigned = roles
            .get_mut(index)
            .ok_or_else(|| container_error("OLE sector ownership lies past EOF"))?;
        if *assigned != 0 {
            return Err(container_error(format!(
                "OLE sector is assigned to multiple chains while claiming {role}"
            )));
        }
        *assigned = 1;
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn validate_stream_chain_ownership(
    entries: &[DirectoryEntry],
    mini_stream_cutoff: usize,
    sector_size: usize,
    mini_sector_size: usize,
    fat: &[u32],
    mini_fat: &[u32],
    mini_stream_bytes: usize,
    sector_count: usize,
    regular_roles: &mut [u32],
    trailing_bytes: usize,
) -> Result<(), Diagnostic> {
    let available_mini_sectors = mini_stream_bytes.div_ceil(mini_sector_size);
    let mut mini_roles =
        allocate_sector_roles(available_mini_sectors, "OLE mini-sector ownership map")?;
    for (stream_index, entry) in entries
        .iter()
        .filter(|entry| entry.object_type == 2)
        .enumerate()
    {
        if entry.stream_size == 0 {
            continue;
        }
        let claim_generation = u32::try_from(stream_index)
            .ok()
            .and_then(|value| value.checked_add(2))
            .ok_or_else(|| object_limit("OLE stream count exceeds supported range"))?;
        if entry.stream_size < mini_stream_cutoff {
            let expected = entry
                .stream_size
                .checked_add(mini_sector_size - 1)
                .ok_or_else(|| format_error(&entry.name, "mini-stream size overflows"))?
                / mini_sector_size;
            claim_mini_chain_exact(
                mini_fat,
                entry.start_sector,
                available_mini_sectors,
                expected,
                &mut mini_roles,
                claim_generation,
                &entry.name,
            )?;
        } else {
            let expected = entry
                .stream_size
                .checked_add(sector_size - 1)
                .ok_or_else(|| format_error(&entry.name, "stream size overflows"))?
                / sector_size;
            claim_regular_chain_exact(
                fat,
                entry.start_sector,
                sector_count,
                expected,
                regular_roles,
                claim_generation,
                &entry.name,
            )?;
            if trailing_bytes != 0 {
                validate_partial_final_stream_sector(
                    fat,
                    entry.start_sector,
                    expected,
                    entry.stream_size,
                    sector_size,
                    sector_count - 1,
                    trailing_bytes,
                    &entry.name,
                )?;
            }
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn validate_partial_final_stream_sector(
    fat: &[u32],
    start: u32,
    expected: usize,
    stream_size: usize,
    sector_size: usize,
    partial_sector: usize,
    trailing_bytes: usize,
    part: &str,
) -> Result<(), Diagnostic> {
    let mut current = start;
    for chain_index in 0..expected {
        let index = usize::try_from(current)
            .map_err(|_| format_error(part, "OLE sector id exceeds supported range"))?;
        if index == partial_sector {
            let required = if chain_index + 1 == expected {
                let prior_bytes = chain_index
                    .checked_mul(sector_size)
                    .ok_or_else(|| format_error(part, "OLE stream offset overflows"))?;
                stream_size
                    .checked_sub(prior_bytes)
                    .ok_or_else(|| format_error(part, "OLE stream size underflows its chain"))?
            } else {
                sector_size
            };
            if required > trailing_bytes {
                return Err(format_error(
                    part,
                    "OLE stream is truncated inside its referenced final sector",
                ));
            }
        }
        current = *fat
            .get(index)
            .ok_or_else(|| format_error(part, "OLE FAT lookup is out of bounds"))?;
    }
    Ok(())
}

fn claim_regular_chain_exact(
    fat: &[u32],
    start: u32,
    sector_count: usize,
    expected: usize,
    roles: &mut [u32],
    claim_generation: u32,
    part: &str,
) -> Result<(), Diagnostic> {
    let mut current = start;
    for _ in 0..expected {
        let index = checked_sector_index(current, sector_count, part)?;
        let assigned = roles
            .get_mut(index)
            .ok_or_else(|| format_error(part, "OLE sector ownership lies past EOF"))?;
        if *assigned == claim_generation {
            return Err(format_error(part, "OLE sector chain contains a cycle"));
        }
        if *assigned != 0 {
            return Err(container_error(format!(
                "OLE sector is assigned to multiple chains while claiming {part}"
            )));
        }
        *assigned = claim_generation;
        current = *fat
            .get(index)
            .ok_or_else(|| format_error(part, "OLE FAT lookup is out of bounds"))?;
    }
    if current != END_OF_CHAIN {
        return Err(format_error(
            part,
            "OLE sector chain length differs from its declared size",
        ));
    }
    Ok(())
}

fn claim_mini_chain_exact(
    mini_fat: &[u32],
    start: u32,
    available_mini_sectors: usize,
    expected: usize,
    roles: &mut [u32],
    claim_generation: u32,
    part: &str,
) -> Result<(), Diagnostic> {
    if expected == 0 {
        return Ok(());
    }
    if mini_fat.is_empty() {
        return Err(format_error(part, "OLE mini-stream has no miniFAT"));
    }
    let mut current = start;
    for _ in 0..expected {
        let index = checked_sector_index(current, mini_fat.len(), part)?;
        if index >= available_mini_sectors {
            return Err(format_error(
                part,
                "mini-sector lies outside the root mini-stream",
            ));
        }
        if roles[index] == claim_generation {
            return Err(format_error(part, "OLE mini-stream chain contains a cycle"));
        }
        if roles[index] != 0 {
            return Err(container_error(format!(
                "OLE mini-sector is shared by multiple chains while claiming {part}"
            )));
        }
        roles[index] = claim_generation;
        current = mini_fat[index];
    }
    if current != END_OF_CHAIN {
        return Err(format_error(
            part,
            "OLE mini-stream chain length differs from its declared size",
        ));
    }
    Ok(())
}

// --- Binary DOC -----------------------------------------------------------

const DOC_STREAM: &str = "WordDocument";
const DOC_PAGE_WIDTH: f32 = 816.0;
const DOC_PAGE_HEIGHT: f32 = 1056.0;
const DOC_PAGE_MARGIN: f32 = 48.0;
const DOC_DEFAULT_FONT_SIZE: f32 = 40.0 / 3.0;

#[derive(Clone, Copy, Debug, PartialEq)]
struct DocPageLayout {
    width: f32,
    height: f32,
    margin_left: f32,
    margin_right: f32,
    margin_top: f32,
    margin_bottom: f32,
    grid_line_pitch: Option<f32>,
}

impl Default for DocPageLayout {
    fn default() -> Self {
        Self {
            width: DOC_PAGE_WIDTH,
            height: DOC_PAGE_HEIGHT,
            margin_left: DOC_PAGE_MARGIN,
            margin_right: DOC_PAGE_MARGIN,
            margin_top: DOC_PAGE_MARGIN,
            margin_bottom: DOC_PAGE_MARGIN,
            grid_line_pitch: None,
        }
    }
}

struct DocSection {
    layout: DocPageLayout,
    columns: Vec<(f32, f32)>,
    column_separator: bool,
    cp_start: usize,
    header_distance: f32,
    title_page: bool,
    facing_pages: bool,
    // Default, first, even. None inherits; a present empty paragraph is blank.
    headers: [Option<Rc<Vec<NativeParagraph>>>; 3],
}

impl Default for DocSection {
    fn default() -> Self {
        Self {
            layout: DocPageLayout::default(),
            columns: Vec::new(),
            column_separator: false,
            cp_start: 0,
            header_distance: 48.0,
            title_page: false,
            facing_pages: false,
            headers: Default::default(),
        }
    }
}

#[derive(Clone, Copy)]
struct FibInfo {
    n_fib: u16,
    flags: u16,
    fc_min: usize,
    fc_mac: usize,
    ccp_text: usize,
    ccp_ftn: usize,
    ccp_hdd: usize,
    textbox_range: (usize, usize),
    plcf_txbx_txt: Option<(usize, usize)>,
    stshf: Option<(usize, usize)>,
    plcf_fnd_ref: Option<(usize, usize)>,
    plcf_fnd_txt: Option<(usize, usize)>,
    plcf_sed: Option<(usize, usize)>,
    plcf_hdd: Option<(usize, usize)>,
    plcf_bte_chpx: Option<(usize, usize)>,
    plcf_bte_papx: Option<(usize, usize)>,
    sttbf_ffn: Option<(usize, usize)>,
    dop: Option<(usize, usize)>,
    clx: Option<(usize, usize)>,
    plcf_spa_mom: Option<(usize, usize)>,
    dgg_info: Option<(usize, usize)>,
    plf_lst: Option<(usize, usize)>,
    plf_lfo: Option<(usize, usize)>,
}

#[derive(Clone, Debug, PartialEq)]
struct DocCharStyle {
    picture_offset: Option<u32>,
    ole2: bool,
    symbol: Option<(u16, u16)>,
    hidden: bool,
    font_ids: [Option<u16>; 4],
    font_size: f32,
    font_size_bi: Option<f32>,
    color: u32,
    color_bi: u32,
    bold: bool,
    bold_bi: bool,
    italic: bool,
    italic_bi: bool,
    bidi: bool,
    complex_scripts: bool,
    hint: u8,
    underline: bool,
    strikethrough: bool,
    baseline_shift: f32,
}

impl Default for DocCharStyle {
    fn default() -> Self {
        Self {
            picture_offset: None,
            ole2: false,
            symbol: None,
            hidden: false,
            font_ids: [None; 4],
            font_size: DOC_DEFAULT_FONT_SIZE,
            font_size_bi: None,
            color: 0x0000_00ff,
            color_bi: 0x0000_00ff,
            bold: false,
            bold_bi: false,
            italic: false,
            italic_bi: false,
            bidi: false,
            complex_scripts: false,
            hint: 0,
            underline: false,
            strikethrough: false,
            baseline_shift: 0.0,
        }
    }
}

#[derive(Clone, Debug)]
struct DocCharRun {
    fc_start: usize,
    fc_end: usize,
    patch: DocCharPatch,
}

struct DocCharState {
    current: DocCharStyle,
    style_baseline: DocCharStyle,
    current_style_id: u16,
    direct_values: DocCharPatch,
}

impl DocCharState {
    fn new(paragraph_baseline: &DocCharStyle) -> Self {
        Self {
            current: paragraph_baseline.clone(),
            style_baseline: paragraph_baseline.clone(),
            current_style_id: 0x000a,
            direct_values: DocCharPatch::default(),
        }
    }

    fn reset_to_paragraph(&mut self, paragraph_baseline: &DocCharStyle) {
        let mut reset = paragraph_baseline.clone();
        reset.bidi = self.current.bidi;
        reset.complex_scripts = self.current.complex_scripts;
        reset.hint = self.current.hint;
        self.current = reset.clone();
        self.style_baseline = reset;
        self.current_style_id = 0x000a;
        self.direct_values = DocCharPatch::default();
    }
}

#[derive(Clone, Debug, Default, PartialEq)]
struct DocCharPatch {
    picture_offset: Option<u32>,
    ole2: Option<bool>,
    symbol: Option<(u16, u16)>,
    hidden: Option<u8>,
    style_id: Option<u16>,
    ordered_grpprl: Option<Vec<u8>>,
    font_ids: [Option<u16>; 4],
    font_size: Option<f32>,
    font_size_bi: Option<f32>,
    color: Option<u32>,
    color_bi: Option<u32>,
    bold: Option<u8>,
    bold_bi: Option<u8>,
    italic: Option<u8>,
    italic_bi: Option<u8>,
    bidi: Option<u8>,
    complex_scripts: Option<u8>,
    hint: Option<u8>,
    underline: Option<bool>,
    strikethrough: Option<u8>,
    baseline_half_points: Option<i16>,
    script: Option<u8>,
}

impl DocCharPatch {
    fn is_empty(&self) -> bool {
        self.picture_offset.is_none()
            && self.ole2.is_none()
            && self.hidden.is_none()
            && self.symbol.is_none()
            && self.style_id.is_none()
            && self.ordered_grpprl.is_none()
            && self.font_ids.iter().all(Option::is_none)
            && self.font_size.is_none()
            && self.font_size_bi.is_none()
            && self.color.is_none()
            && self.color_bi.is_none()
            && self.bold.is_none()
            && self.bold_bi.is_none()
            && self.italic.is_none()
            && self.italic_bi.is_none()
            && self.bidi.is_none()
            && self.complex_scripts.is_none()
            && self.hint.is_none()
            && self.underline.is_none()
            && self.strikethrough.is_none()
            && self.baseline_half_points.is_none()
            && self.script.is_none()
    }

    fn record_resolved_values(&mut self, source: &DocCharPatch, resolved: &DocCharStyle) {
        if source.ole2.is_some() {
            self.ole2 = Some(resolved.ole2);
        }
        if source.picture_offset.is_some() {
            self.picture_offset = resolved.picture_offset;
        }
        if source.symbol.is_some() {
            self.symbol = resolved.symbol;
        }
        if source.hidden.is_some() {
            self.hidden = Some(u8::from(resolved.hidden));
        }
        for ((target, source), value) in self
            .font_ids
            .iter_mut()
            .zip(source.font_ids)
            .zip(resolved.font_ids)
        {
            if source.is_some() {
                *target = value;
            }
        }
        if source.font_size.is_some() {
            self.font_size = Some(resolved.font_size);
        }
        if source.font_size_bi.is_some() {
            self.font_size_bi = resolved.font_size_bi;
        }
        if source.color.is_some() {
            self.color = Some(resolved.color);
        }
        if source.color_bi.is_some() {
            self.color_bi = Some(resolved.color_bi);
        }
        if source.bold.is_some() {
            self.bold = Some(u8::from(resolved.bold));
        }
        if source.bold_bi.is_some() {
            self.bold_bi = Some(u8::from(resolved.bold_bi));
        }
        if source.italic.is_some() {
            self.italic = Some(u8::from(resolved.italic));
        }
        if source.italic_bi.is_some() {
            self.italic_bi = Some(u8::from(resolved.italic_bi));
        }
        if source.bidi.is_some() {
            self.bidi = Some(u8::from(resolved.bidi));
        }
        if source.complex_scripts.is_some() {
            self.complex_scripts = Some(u8::from(resolved.complex_scripts));
        }
        if source.hint.is_some() {
            self.hint = Some(resolved.hint);
        }
        if source.underline.is_some() {
            self.underline = Some(resolved.underline);
        }
        if source.strikethrough.is_some() {
            self.strikethrough = Some(u8::from(resolved.strikethrough));
        }
        if source.baseline_half_points.is_some() {
            self.baseline_half_points = source.baseline_half_points;
            self.script = None;
        }
        if source.script.is_some() {
            self.baseline_half_points = None;
            self.script = source.script;
        }
    }

    fn apply(&self, baseline: &DocCharStyle) -> DocCharStyle {
        self.apply_to(baseline, baseline)
    }

    fn apply_to(&self, current: &DocCharStyle, style_baseline: &DocCharStyle) -> DocCharStyle {
        let mut style = current.clone();
        if let Some(ole2) = self.ole2 {
            style.ole2 = ole2;
        }
        if self.picture_offset.is_some() {
            style.picture_offset = self.picture_offset;
        }
        if self.symbol.is_some() {
            style.symbol = self.symbol;
        }
        if let Some(hidden) = self.hidden {
            style.hidden = doc_toggle_value(hidden, style_baseline.hidden, style.hidden);
        }
        for (target, patch) in style.font_ids.iter_mut().zip(self.font_ids) {
            if patch.is_some() {
                *target = patch;
            }
        }
        if let Some(font_size) = self.font_size {
            style.font_size = font_size;
        }
        if let Some(font_size) = self.font_size_bi {
            style.font_size_bi = Some(font_size);
        }
        if let Some(color) = self.color {
            style.color = color;
        }
        if let Some(color) = self.color_bi {
            style.color_bi = color;
        }
        if let Some(operand) = self.bold {
            style.bold = doc_toggle_value(operand, style_baseline.bold, style.bold);
        }
        if let Some(operand) = self.bold_bi {
            style.bold_bi = doc_toggle_value(operand, style_baseline.bold_bi, style.bold_bi);
        }
        if let Some(operand) = self.italic {
            style.italic = doc_toggle_value(operand, style_baseline.italic, style.italic);
        }
        if let Some(operand) = self.italic_bi {
            style.italic_bi = doc_toggle_value(operand, style_baseline.italic_bi, style.italic_bi);
        }
        if let Some(operand) = self.bidi {
            style.bidi = doc_toggle_value(operand, style_baseline.bidi, style.bidi);
        }
        if let Some(operand) = self.complex_scripts {
            style.complex_scripts = doc_toggle_value(
                operand,
                style_baseline.complex_scripts,
                style.complex_scripts,
            );
        }
        if let Some(hint) = self.hint {
            style.hint = hint;
        }
        if let Some(underline) = self.underline {
            style.underline = underline;
        }
        if let Some(operand) = self.strikethrough {
            style.strikethrough =
                doc_toggle_value(operand, style_baseline.strikethrough, style.strikethrough);
        }
        if let Some(half_points) = self.baseline_half_points {
            style.baseline_shift = half_points as f32 * (2.0 / 3.0);
        }
        if let Some(script) = self.script {
            style.baseline_shift = match script {
                1 => style.font_size / 3.0,
                2 => -style.font_size / 5.0,
                _ => 0.0,
            };
        }
        style
    }
}

