    #[test]
    fn ppt_embedded_ole_reference_and_storage_are_bounded() {
        let mut atom = vec![0; 24];
        atom[8..12].copy_from_slice(&8_u32.to_le_bytes());
        atom[16..20].copy_from_slice(&3_u32.to_le_bytes());
        let atom = ppt_record(0x0001, RT_EXTERNAL_OLE_OBJECT_ATOM, &atom);
        let bytes = ppt_record(0x000f, RT_EXTERNAL_OLE_EMBED, &atom);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();
        assert_eq!(
            parse_ppt_embedded_ole_reference(&bytes, record, Limits::default()).unwrap(),
            Some((8, 3))
        );
        assert_eq!(
            inflate_ppt_zlib(
                b"\x78\x01\x01\x05\x00\xfa\xffhello\x06\x2c\x02\x15",
                5,
                Limits::default(),
            )
            .unwrap(),
            b"hello"
        );
    }

