    #[test]
    fn supplied_doc_report_renders_header_above_body() {
        let document = detect_and_parse(
            include_bytes!("../../tests/fixtures/report-drop-cap.doc"),
            Limits::default(),
        )
        .unwrap()
        .unwrap();
        let header = document
            .objects
            .iter()
            .find(|object| {
                object.unit_index == 0
                    && object.text.as_deref() == Some("Simple Home Styling")
                    && object.bounds.y < 80.0
            })
            .expect("the first page must render its real header, not only the matching body title");
        assert!(header.bounds.y >= 0.0);
        assert!(header.bounds.height > 0.0);
        assert_eq!(header.bounds.x, 96.0);
        assert_eq!(header.bounds.y, 40.0);
        assert!(matches!(
            header.source.locator,
            SourceLocator::Legacy {
                kind: "paragraph",
                text_range: Some((1461, 1481)),
                ..
            }
        ));
        for unit in &document.units {
            assert_eq!(
                document
                    .objects
                    .iter()
                    .filter(|object| object.unit_index == unit.index
                        && object.stable_id.starts_with("doc:header:"))
                    .count(),
                1
            );
        }
        assert!(document.objects.iter().any(|object| object.text.as_deref()
            == Some("Simple Home Styling")
            && object.bounds.y > header.bounds.y + header.bounds.height));
    }

    #[test]
    fn supplied_doc_header_variants_inherit_blank_and_isolate_bad_ranges() {
        let limits = Limits::default();
        let cfb = CompoundFile::open(
            include_bytes!("../../tests/fixtures/report-drop-cap.doc"),
            limits,
        )
        .unwrap();
        for mode in ["invalid", "inherit", "even", "first"] {
            let mut word = cfb.stream(DOC_STREAM).unwrap();
            let mut fib = parse_fib(&word).unwrap();
            let mut table = cfb
                .stream(if fib.flags & (1 << 9) != 0 {
                    "1Table"
                } else {
                    "0Table"
                })
                .unwrap();
            let header_offset = fib.plcf_hdd.unwrap().0;
            match mode {
                "invalid" => write_u32(&mut table, header_offset + 8 * 4, fib.ccp_hdd as u32 + 1),
                "inherit" => {
                    let sed = table_range(&table, fib.plcf_sed.unwrap(), "DOC PlcfSed").unwrap()
                        [8..20]
                        .to_vec();
                    let start = table.len();
                    for cp in [0, 500, 1000, fib.ccp_text as u32] {
                        table.extend_from_slice(&cp.to_le_bytes());
                    }
                    for _ in 0..3 {
                        table.extend_from_slice(&sed);
                    }
                    fib.plcf_sed = Some((start, table.len() - start));
                    let start = table.len();
                    // Section 2 inherits; section 3 has an explicit empty paragraph
                    // using the source footer's two final paragraph marks.
                    for cp in [
                        0u32,
                        3,
                        6,
                        6,
                        9,
                        12,
                        12,
                        12,
                        33,
                        33,
                        43,
                        43,
                        43,
                        43,
                        43,
                        43,
                        43,
                        43,
                        43,
                        43,
                        45,
                        45,
                        45,
                        45,
                        45,
                        u32::MAX,
                    ] {
                        table.extend_from_slice(&cp.to_le_bytes());
                    }
                    fib.plcf_hdd = Some((start, table.len() - start));
                }
                "even" | "first" => {
                    let cps = if mode == "even" {
                        [12u32, 33, 33, 33, 45, 45]
                    } else {
                        [12u32, 12, 12, 12, 12, 33]
                    };
                    for (slot, cp) in cps.into_iter().enumerate() {
                        write_u32(&mut table, header_offset + (6 + slot) * 4, cp);
                    }
                    if mode == "even" {
                        table[fib.dop.unwrap().0] |= 1;
                    } else {
                        let sed = fib.plcf_sed.unwrap().0 + 10;
                        let sepx = read_u32(&table, sed, "DOC PlcfSed").unwrap() as usize;
                        let size = read_u16(&word, sepx, "DOC Sepx").unwrap() as usize;
                        let mut properties = word[sepx + 2..sepx + 2 + size].to_vec();
                        properties.extend_from_slice(&[0x0a, 0x30, 1]);
                        write_u32(&mut table, sed, word.len() as u32);
                        word.extend_from_slice(&(properties.len() as u16).to_le_bytes());
                        word.extend_from_slice(&properties);
                    }
                }
                _ => unreachable!(),
            }
            let mut diagnostics = Vec::new();
            let formatting =
                parse_doc_formatting(&word, &table, &[], fib, limits, &mut diagnostics).unwrap();
            let mut body = ParagraphCollector::new(
                limits.max_total_uncompressed_bytes,
                limits.max_document_objects,
            );
            let mut notes = ParagraphCollector::new(
                limits.max_total_uncompressed_bytes,
                limits.max_document_objects,
            );
            let sections = parse_clx_text(
                &word,
                &table,
                fib,
                limits,
                &formatting,
                &mut body,
                &mut notes,
                &mut HashMap::new(),
                &mut diagnostics,
            )
            .unwrap();
            let (paragraphs, _) = body.finish().unwrap();
            assert!(
                paragraphs.iter().any(|p| p.text == "Simple Home Styling"),
                "{mode}: body survives"
            );
            if mode == "invalid" {
                assert!(
                    diagnostics
                        .iter()
                        .any(|d| d.code == DiagnosticCode::FormatInvalid
                            && d.message.contains("headers"))
                );
                assert!(
                    sections
                        .iter()
                        .all(|s| s.headers.iter().all(Option::is_none))
                );
                continue;
            }
            if mode == "inherit" {
                assert!(Rc::ptr_eq(
                    sections[0].headers[0].as_ref().unwrap(),
                    sections[1].headers[0].as_ref().unwrap()
                ));
                assert!(
                    sections[2].headers[0]
                        .as_ref()
                        .unwrap()
                        .iter()
                        .all(|p| p.text.is_empty())
                );
            }
            let mut scene =
                LegacyScene::new(DocumentFormat::Doc, DocumentKind::Text, limits, diagnostics);
            let page_count = if mode == "inherit" { 3 } else { 2 };
            for index in 0..page_count {
                let section_index = if mode == "inherit" { index } else { 0 };
                push_doc_page(&mut scene, sections[section_index].layout).unwrap();
                let mut paragraph = paragraphs[0].clone();
                paragraph.cp_start = sections[section_index].cp_start as u32;
                paragraph.cp_end = paragraph.cp_start + 1;
                push_doc_paragraph_object(
                    &mut scene,
                    paragraph,
                    index,
                    Rect {
                        x: 96.0,
                        y: 120.0,
                        width: 500.0,
                        height: 20.0,
                    },
                    20.0,
                    0,
                    false,
                )
                .unwrap();
            }
            render_doc_headers(
                &mut scene,
                &sections,
                &HashMap::new(),
                &FontMetricTable::default(),
            )
            .unwrap();
            let visible_pages = scene
                .objects
                .iter()
                .filter(|o| {
                    o.text.as_deref() == Some("Simple Home Styling")
                        && o.stable_id.starts_with("doc:header:")
                })
                .map(|o| o.unit_index)
                .collect::<Vec<_>>();
            assert_eq!(
                visible_pages,
                match mode {
                    "inherit" => vec![0, 1],
                    "even" => vec![1],
                    "first" => vec![0],
                    _ => unreachable!(),
                },
                "{mode}"
            );
        }
    }

    #[test]
    fn supplied_doc_report_wraps_body_beside_drop_cap() {
        let document = detect_and_parse(
            include_bytes!("../../tests/fixtures/report-drop-cap.doc"),
            Limits::default(),
        )
        .unwrap()
        .unwrap();
        let cap = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("T"))
            .expect("source drop cap must be retained");
        let body = document
            .objects
            .iter()
            .find(|o| {
                o.text
                    .as_deref()
                    .is_some_and(|t| t.starts_with("o get started"))
            })
            .unwrap();
        assert_eq!(cap.unit_index, body.unit_index);
        assert!(
            (cap.bounds.y - body.bounds.y).abs() < 1.0,
            "cap {:?}, body {:?}",
            cap.bounds,
            body.bounds
        );
        assert!(body.bounds.x >= cap.bounds.x + cap.bounds.width - 0.1);
    }

    #[test]
    fn supplied_doc_report_retains_group_picture() {
        let document = detect_and_parse(
            include_bytes!("../../tests/fixtures/report-drop-cap.doc"),
            Limits::default(),
        )
        .unwrap()
        .unwrap();
        let image = document
            .objects
            .iter()
            .find(|o| o.kind == ObjectKind::Image)
            .expect("source group picture must render");
        assert!(
            (image.bounds.width - 602.6667).abs() < 1.0,
            "{:?}",
            image.bounds
        );
        assert!(
            (image.bounds.height - 309.3333).abs() < 1.0,
            "{:?}",
            image.bounds
        );
        assert_eq!(image.bounds.x, 96.0, "Spa bx=0 anchors at the margin");
        let body = document
            .objects
            .iter()
            .find(|o| {
                o.text
                    .as_deref()
                    .is_some_and(|text| text.starts_with("It’s easy"))
            })
            .unwrap();
        assert!(
            image.bounds.y >= body.bounds.y + body.bounds.height,
            "top/bottom wrapped picture must not cover its anchor paragraph: image {:?}, body {:?}",
            image.bounds,
            body.bounds
        );
        assert!(
            matches!(&image.visual, Visual::Image { media_type, bytes, .. }
            if media_type == "image/jpeg" && bytes.starts_with(&[0xff, 0xd8, 0xff]))
        );
        let Visual::Image { crop, .. } = &image.visual else {
            unreachable!()
        };
        assert!(
            (crop.top - 15092.0 / 65536.0).abs() < 0.0001,
            "authored group picture crop: {crop:?}"
        );
    }

    #[test]
    fn supplied_doc_invalid_crop_keeps_the_picture_with_a_diagnostic() {
        let limits = Limits::default();
        let cfb = CompoundFile::open(
            include_bytes!("../../tests/fixtures/report-drop-cap.doc"),
            limits,
        )
        .unwrap();
        let word = cfb.stream(DOC_STREAM).unwrap();
        let fib = parse_fib(&word).unwrap();
        let mut table = cfb
            .stream(if fib.flags & (1 << 9) != 0 {
                "1Table"
            } else {
                "0Table"
            })
            .unwrap();
        let bounds = fib.dgg_info.unwrap();
        let drawing = table_range(&table, bounds, "DOC DggInfo").unwrap();
        let property = drawing
            .windows(6)
            .position(|bytes| bytes == [0, 1, 0xf4, 0x3a, 0, 0])
            .unwrap();
        table[bounds.0 + property + 2..bounds.0 + property + 6]
            .copy_from_slice(&0x0002_0000_u32.to_le_bytes());
        let mut diagnostics = Vec::new();
        let images =
            parse_doc_office_art_content(&word, &table, bounds, limits, &mut diagnostics).unwrap();
        assert_eq!(images.len(), 1);
        let DocFloatingContent::Image(_, crop) = images.values().next().unwrap() else {
            panic!("expected image");
        };
        assert_eq!(*crop, ImageCrop::default());
        assert!(diagnostics.iter().any(|diagnostic| {
            diagnostic
                .message
                .contains("invalid binary DOC picture crop")
        }));
    }

    #[test]
    fn native_doc_drop_caps_preserve_margin_orphan_and_continuation_text() {
        let make = |text: &str, style, cp_start| NativeParagraph {
            text: text.to_owned(),
            runs: vec![TextRun {
                text: text.to_owned(),
                ..doc_default_text_run()
            }],
            empty_run: None,
            list_prefix: None,
            style,
            cp_start,
            cp_end: cp_start + text.len() as u32 + 1,
            record_offset: 0,
            page_layout: DocPageLayout::default(),
            table_cell_end: false,
            section_break: false,
            picture_anchor: None,
        };
        for (in_margin, body) in [
            (false, "".to_owned()),
            (true, "short".to_owned()),
            (false, "body ".repeat(200)),
        ] {
            let mut style = DocParagraphStyle::default();
            apply_doc_paragraph_grpprl(
                &[
                    0x2c,
                    0x44,
                    3 * 8 + if in_margin { 2 } else { 1 },
                    0xff,
                    0x2f,
                    0x84,
                    60,
                    0,
                ],
                &mut style,
            )
            .unwrap();
            assert_eq!(style.drop_cap, Some((in_margin, 3)));
            assert_eq!(style.frame_text_space, 4.0);
            let mut cap = make("T", style, 0);
            cap.runs[0].font_size = 50.0;
            let mut paragraphs = vec![cap];
            if !body.is_empty() {
                paragraphs.push(make(&body, DocParagraphStyle::default(), 2));
            }
            let document = layout_doc(
                paragraphs,
                vec![],
                &HashMap::new(),
                vec![],
                HashMap::new(),
                Limits::default(),
                vec![],
                &FontMetricTable::default(),
                &[],
            )
            .unwrap();
            let objects = &document.objects;
            assert_eq!(
                objects
                    .iter()
                    .filter_map(|o| o.text.as_deref())
                    .collect::<String>(),
                format!("T{body}")
            );
            if in_margin {
                assert!(objects[0].bounds.x < objects[1].bounds.x);
                assert_eq!(objects[0].bounds.y, objects[1].bounds.y);
            } else if !body.is_empty() {
                assert!(objects[1].bounds.x > objects[0].bounds.x);
                assert_eq!(
                    objects[2].bounds.x, objects[0].bounds.x,
                    "text below the cap returns to full width"
                );
                assert!(objects[2].bounds.y >= objects[0].bounds.y + objects[0].bounds.height);
            }
        }
    }

