    #[test]
    fn native_doc_uses_the_ffn_alternate_font_name() {
        let primary = "Liberation Sans";
        let alternate = "Arial";
        let mut names = Vec::new();
        for unit in primary.encode_utf16().chain(std::iter::once(0)) {
            names.extend_from_slice(&unit.to_le_bytes());
        }
        let alternate_offset = primary.encode_utf16().count() + 1;
        for unit in alternate.encode_utf16().chain(std::iter::once(0)) {
            names.extend_from_slice(&unit.to_le_bytes());
        }
        let mut record = vec![0u8; 39];
        record[4] = alternate_offset as u8;
        record.extend_from_slice(&names);
        let mut table = Vec::new();
        table.extend_from_slice(&1u16.to_le_bytes());
        table.extend_from_slice(&0u16.to_le_bytes());
        table.push(record.len() as u8);
        table.extend_from_slice(&record);

        assert_eq!(
            parse_doc_font_table(&table, (0, table.len()), 4).unwrap(),
            vec!["Arial"]
        );
    }

    #[test]
    fn native_doc_extracts_cached_officeart_jpeg_and_emf() {
        let jpeg = b"\xff\xd8\xff\xe0\x00\xff\xd9";
        let mut jpeg_record = vec![0u8; 8 + 16];
        jpeg_record[2..4].copy_from_slice(&0xf01du16.to_le_bytes());
        jpeg_record[4..8].copy_from_slice(&(16u32 + jpeg.len() as u32).to_le_bytes());
        jpeg_record.extend_from_slice(jpeg);
        let extracted = extract_doc_office_art_blip(&jpeg_record, 0, 5, Limits::default()).unwrap();
        assert_eq!(
            extracted,
            Some(DocImage {
                media_type: "image/jpeg",
                bytes: jpeg.to_vec(),
            })
        );

        let mut emf = vec![0u8; 44];
        emf[40..44].copy_from_slice(b" EMF");
        let mut metafile = vec![0u8; 34];
        metafile[0..4].copy_from_slice(&(emf.len() as u32).to_le_bytes());
        metafile[28..32].copy_from_slice(&(emf.len() as u32).to_le_bytes());
        metafile[32] = 0xfe;
        let payload_length = 16 + metafile.len() + emf.len();
        let mut emf_record = vec![0u8; 8 + 16];
        emf_record[2..4].copy_from_slice(&0xf01au16.to_le_bytes());
        emf_record[4..8].copy_from_slice(&(payload_length as u32).to_le_bytes());
        emf_record.extend_from_slice(&metafile);
        emf_record.extend_from_slice(&emf);
        let extracted = extract_doc_office_art_blip(&emf_record, 0, 2, Limits::default()).unwrap();
        assert_eq!(
            extracted,
            Some(DocImage {
                media_type: "image/x-emf",
                bytes: emf,
            })
        );
    }

