    #[cfg(feature = "legacy-office-formats")]
    #[test]
    fn supplied_ppt_slide_number_field() {
        let bytes = include_bytes!("../../tests/fixtures/tdf169705.ppt");

        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let footer = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("*"))
            .or_else(|| {
                document
                    .objects
                    .iter()
                    .find(|object| object.text.as_deref() == Some("1"))
            })
            .expect("slide number object");
        assert_eq!(footer.text.as_deref(), Some("1"));
        fn runs(visual: &Visual) -> &[TextRun] {
            match visual {
                Visual::TextLayout { visual, .. } | Visual::TextEffects { visual, .. } => {
                    runs(visual)
                }
                Visual::RichText { runs, .. } => runs,
                _ => panic!("expected text"),
            }
        }
        assert_eq!(
            runs(&footer.visual)
                .iter()
                .map(|run| run.text.as_str())
                .collect::<String>(),
            "1"
        );
        let source = "\r😀* / *";
        let positions = ppt_normalized_field_positions(source, &[3, 1000]);
        assert_eq!(positions, vec![1]);
        let mut normalized = normalize_ppt_text(source.to_owned());
        ppt_replace_slide_number(&mut normalized, &positions, 0, "12");
        assert_eq!(normalized, "😀12 / *");
        let mut styled_tail = "* / *".to_owned();
        ppt_replace_slide_number(&mut styled_tail, &positions, 1, "12");
        assert_eq!(styled_tail, "12 / *");
    }

