    #[cfg(feature = "legacy-office-formats")]
    #[test]
    fn supplied_ppt_97_arc_opens_with_bounded_geometry() {
        let document = detect_and_parse(
            include_bytes!("../../tests/fixtures/tdf122899_Arc_90_to_91_clockwise.ppt"),
            Limits::default(),
        )
        .unwrap()
        .unwrap();
        let arc = document
            .objects
            .iter()
            .find(|o| o.bounds.width < 400.0)
            .unwrap();
        assert!((arc.bounds.width - 340.0).abs() < 0.5);
        let Visual::Group { children } = &arc.visual else {
            panic!("arc keeps separate endpoint paints");
        };
        assert_eq!(children.len(), 3);
        let Visual::Shape {
            geometry: Geometry::LayeredPath { layers },
            ..
        } = &children[0].visual
        else {
            panic!("arc fill and stroke are separate");
        };
        assert_eq!(layers.len(), 2);
        assert!(!layers[0].stroke);
        assert_eq!(layers[1].fill, PathFillMode::None);
        assert!(layers[0].commands.iter().any(|command| matches!(command, PathCommand::LineTo { x, y } if (*x - 170.0).abs() < 0.01 && (*y - 113.3333).abs() < 0.01)));
        assert_eq!(
            layers[1]
                .commands
                .iter()
                .filter(|c| matches!(c, PathCommand::BezierCurveTo { .. }))
                .count(),
            4
        );
    }

