    #[cfg(feature = "legacy-office-formats")]
    #[test]
    fn supplied_ppt_fill_patterns_preserve_all_authored_tiles() {
        let bytes = include_bytes!("../../tests/fixtures/FillPatterns.ppt");
        let cfb = CompoundFile::open(bytes, Limits::default()).unwrap();
        let pictures = cfb.stream(PPT_PICTURES_STREAM).unwrap();
        let image = extract_doc_office_art_blip(&pictures, 0, 7, Limits::default())
            .unwrap()
            .unwrap();
        assert_eq!(image.bytes, pictures[25..105]);
        assert_eq!(office_art_blip_kind(OFFICE_ART_DIB), Some(7));
        let mut truncated = pictures[..32].to_vec();
        truncated[4..8].copy_from_slice(&24u32.to_le_bytes());
        assert!(
            extract_doc_office_art_blip(&truncated, 0, 7, Limits::default())
                .unwrap()
                .is_none()
        );
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let tiles: Vec<_> = document
            .objects
            .iter()
            .filter_map(|object| match &object.visual {
                Visual::PaintedShape {
                    fill:
                        Paint::Image {
                            media_type,
                            bytes,
                            tile: true,
                            ..
                        },
                    ..
                } => {
                    assert_eq!(media_type, "image/bmp");
                    assert_eq!(&bytes[4..12], &[8, 0, 0, 0, 8, 0, 0, 0]);
                    assert_eq!(&bytes[40..48], &[0, 0, 255, 0, 255, 255, 255, 0]);
                    Some(bytes[48..].to_vec())
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            tiles.len(),
            48,
            "all authored pattern tiles must reach the shared brush renderer"
        );
        // The source corpus specifies foreground at (0,0) and (4,4), background elsewhere.
        for y in 0..8 {
            for x in 0..8 {
                let foreground = tiles[0][(7 - y) * 4] & (0x80 >> x) == 0;
                assert_eq!(foreground, (x == 0 && y == 0) || (x == 4 && y == 4));
            }
        }
        assert_eq!(
            tiles.iter().collect::<std::collections::HashSet<_>>().len(),
            37
        );
    }

