    #[test]
    fn native_doc_reads_table_cell_boundaries_and_vertical_flags() {
        let mut operand = vec![0u8; 3 + 3 * 2 + 2 * 20];
        operand[2] = 2;
        for (index, edge) in [450i16, 1_440, 3_000].into_iter().enumerate() {
            operand[3 + index * 2..5 + index * 2].copy_from_slice(&edge.to_le_bytes());
        }
        let tc_offset = 3 + 3 * 2;
        operand[tc_offset..tc_offset + 2].copy_from_slice(&0x00e0u16.to_le_bytes());
        operand[tc_offset + 20..tc_offset + 22].copy_from_slice(&0x00a0u16.to_le_bytes());
        let mut style = DocParagraphStyle::default();

        apply_doc_paragraph_sprm(0xd608, &operand, &mut style).unwrap();
        apply_doc_paragraph_sprm(0x5400, &1u16.to_le_bytes(), &mut style).unwrap();
        apply_doc_paragraph_sprm(0x9601, &(-108i16).to_le_bytes(), &mut style).unwrap();
        apply_doc_paragraph_sprm(0x9602, &540i16.to_le_bytes(), &mut style).unwrap();

        assert_eq!(style.table_cell_count, 2);
        assert_eq!(style.table_cell_edges[..3], [450, 1_440, 3_000]);
        assert_eq!(style.table_vertical_merge[..2], [3, 1]);
        assert_eq!(style.table_vertical_align[..2], [1, 1]);
        assert_eq!(style.table_justification, 1);
        assert_eq!(style.table_left, -108);
        assert_eq!(style.table_gap_half, 540);
    }

