    #[test]
    fn supplied_complex_doc_isolates_a_damaged_picture_without_reassigning_others() {
        let bytes = include_bytes!("../../tests/fixtures/complex1-nor.doc");
        let limits = Limits::default();
        let cfb = CompoundFile::open(bytes, limits).unwrap();
        let original = detect_and_parse(bytes, limits).unwrap().unwrap();
        let pictures = |document: &Document| {
            document
                .objects
                .iter()
                .filter_map(|object| {
                    let SourceLocator::Legacy {
                        text_range: Some((cp, _)),
                        ..
                    } = object.source.locator
                    else {
                        return None;
                    };
                    let Visual::Image {
                        media_type, bytes, ..
                    } = &object.visual
                    else {
                        return None;
                    };
                    (11705..11737).contains(&cp).then(|| {
                        (
                            cp,
                            object.unit_index,
                            object.bounds,
                            media_type.clone(),
                            bytes.clone(),
                        )
                    })
                })
                .collect::<Vec<_>>()
        };
        let expected = pictures(&original);
        assert_eq!(expected.len(), 7);
        // Mutate only the cougar's real PICF header in the supplied compound file.
        let data_entry = cfb
            .entries
            .iter()
            .find(|entry| entry.name == "Data")
            .unwrap();
        let physical_offset = |offset: usize| {
            let mut sector = data_entry.start_sector;
            for _ in 0..offset / cfb.sector_size {
                sector = cfb.fat[sector as usize];
            }
            (sector as usize + 1) * cfb.sector_size + offset % cfb.sector_size
        };
        let mut damaged = bytes.to_vec();
        damaged[physical_offset(26372 + 4)] = 0;
        let document = detect_and_parse(&damaged, limits).unwrap().unwrap();
        assert_eq!(pictures(&document), expected[1..]);
        assert!(
            document
                .diagnostics
                .iter()
                .any(|d| d.code == DiagnosticCode::FormatInvalid
                    && d.message.contains("picture at Data offset 26372"))
        );

        // Invalid crop metadata degrades this same authored picture to uncropped.
        let mut damaged = bytes.to_vec();
        for (index, value) in [0x00, 0x01, 0x00, 0x00, 0x02, 0x00].into_iter().enumerate() {
            damaged[physical_offset(26372 + 100 + index)] = value;
        }
        let document = detect_and_parse(&damaged, limits).unwrap().unwrap();
        assert_eq!(pictures(&document), expected);
        assert!(
            document
                .diagnostics
                .iter()
                .any(|d| d.message.contains("crop uses the uncropped image"))
        );
    }

    #[test]
    fn supplied_complex_doc_preserves_character_table_cells() {
        let bytes = include_bytes!("../../tests/fixtures/complex1-nor.doc");
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let cells: Vec<_> = document
            .objects
            .iter()
            .filter(|object| {
                matches!(&object.visual, Visual::TextLayout { visual, .. }
                if matches!(visual.as_ref(), Visual::RichText { stroke: Paint::Solid(_), .. }))
            })
            .collect();
        assert_eq!(
            cells.len(),
            519,
            "all character-table cells and three-column table cells survive"
        );
        let header = cells
            .iter()
            .find(|object| object.text.as_deref() == Some("-F"))
            .unwrap();
        assert!((header.bounds.x - 692.3333).abs() < 0.01);
        assert!((header.bounds.width - 36.4667).abs() < 0.01);
        assert!(cells.iter().filter(|object| object.unit_index == 0).count() >= 170);
        for text in [
            "Bullet (Alt+0183)\t•",
            "Copyright (Alt+0211)\t©",
            "Greek delta (Alt+098)\tβ",
        ] {
            assert!(
                document
                    .objects
                    .iter()
                    .any(|object| object.text.as_deref() == Some(text)),
                "{text}"
            );
        }
        assert!(!document.objects.iter().any(|object| {
            object
                .text
                .as_deref()
                .is_some_and(|text| text.contains("Caps Hidden"))
        }));
        assert!(
            !document
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == DiagnosticCode::FormatInvalid)
        );

        let bullet = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("Bullet (Alt+0183)\t•"))
            .unwrap();
        let greek = document
            .objects
            .iter()
            .find(|o| o.text.as_deref() == Some("Greek delta (Alt+098)\tβ"))
            .unwrap();
        assert!(
            (greek.bounds.x - 432.0).abs() < 0.01,
            "Greek symbol belongs to the second column: {:?}",
            greek.bounds
        );
        assert!((greek.bounds.y - bullet.bounds.y).abs() < 0.01);
        let unequal: Vec<_> = document.objects.iter().filter(|o| matches!(o.source.locator,
            SourceLocator::Legacy { text_range: Some((start, _)), .. } if (4472..5049).contains(&start))).collect();
        assert_eq!(unequal.len(), 2);
        assert!((unequal[0].bounds.width - 176.0).abs() < 0.01);
        assert!((unequal[1].bounds.width - 352.0).abs() < 0.01);
        assert_eq!(
            unequal
                .iter()
                .map(|o| o.text.as_deref().unwrap_or(""))
                .collect::<String>(),
            "The two columns here are not of the same width. There is 0.5 inches between the columns. The first column is 1.83 inches wide. The second column is 3.67 inches wide. In addition, the left margin of the first column and the right margin of the second column should line up with the left and right margins of the first column. The columns should appear unbalanced, the text being fully justified. Verify that each of these columns are indeed 1.83 and 3.67 inches wide respectively. Please also verify the 0.5 inch space between the columns. The edges should not appear ragged.  "
        );

        // Corrupt only a real PrcData reference, preserving the other properties and stories.
        let cfb = CompoundFile::open(bytes, Limits::default()).unwrap();
        let word = cfb.stream(DOC_STREAM).unwrap();
        let fib = parse_fib(&word).unwrap();
        let table_name = if fib.flags & 0x200 != 0 {
            "1Table"
        } else {
            "0Table"
        };
        let table = cfb.stream(table_name).unwrap();
        for reference in [173u32, u32::MAX] {
            let mut data = cfb.stream("Data").unwrap();
            assert_eq!(&data[175..177], &[0x6b, 0x64]);
            data[177..181].copy_from_slice(&reference.to_le_bytes());
            let mut diagnostics = Vec::new();
            let formatting = parse_doc_formatting(
                &word,
                &table,
                &data,
                fib,
                Limits::default(),
                &mut diagnostics,
            )
            .unwrap();
            let mut collector = ParagraphCollector::new(1 << 24, 10000);
            let mut footnotes = ParagraphCollector::new(1 << 24, 10000);
            parse_clx_text(
                &word,
                &table,
                fib,
                Limits::default(),
                &formatting,
                &mut collector,
                &mut footnotes,
                &mut HashMap::new(),
                &mut diagnostics,
            )
            .unwrap();
            let (paragraphs, _) = collector.finish().unwrap();
            assert!(paragraphs.iter().any(|paragraph| paragraph.text == "-F"));
            assert!(
                diagnostics
                    .iter()
                    .any(|diagnostic| diagnostic.code == DiagnosticCode::FormatInvalid)
            );
        }
    }

    #[test]
    fn supplied_doc_punctuation_compression_matches_word_pagination() {
        let cfb = CompoundFile::open(
            include_bytes!("../../tests/fixtures/word-table-auto-height.doc"),
            Limits::default(),
        )
        .unwrap();
        let fib = parse_fib(&cfb.stream(DOC_STREAM).unwrap()).unwrap();
        let table = cfb
            .stream(if fib.flags & 0x0200 != 0 {
                "1Table"
            } else {
                "0Table"
            })
            .unwrap();
        let dop = table_range(&table, fib.dop.unwrap(), "DOC DOP").unwrap();
        assert_eq!((dop[90] >> 1) & 3, 1, "authored punctuation compression");
        let document = detect_and_parse(
            include_bytes!("../../tests/fixtures/word-table-auto-height.doc"),
            Limits::default(),
        )
        .unwrap()
        .unwrap();
        assert_eq!(document.units.len(), 24);
        let last = document
            .objects
            .iter()
            .filter(|o| o.unit_index == 0)
            .last()
            .unwrap();
        assert!(
            last.text.as_deref().unwrap().ends_with("第三方提"),
            "{:?} {:?}",
            last.bounds,
            last.text
        );
        let deletion = document
            .objects
            .iter()
            .position(|o| {
                o.text
                    .as_deref()
                    .is_some_and(|text| text.starts_with("个人信息删除："))
            })
            .unwrap();
        let mut height = 0.0;
        for object in &document.objects[deletion..] {
            height += object.bounds.height;
            let Visual::TextLayout { layout, .. } = &object.visual else {
                panic!("text layout")
            };
            if !layout.continues_after {
                break;
            }
        }
        assert!(
            (height - 83.2).abs() < 0.01,
            "deletion paragraph occupies two lines"
        );
    }

    #[test]
    fn native_doc_preserves_supplied_first_page_break_and_continuation() {
        let bytes = include_bytes!("../../tests/fixtures/word-table-auto-height.doc");
        let document = detect_and_parse_with_font_metrics(
            bytes,
            Limits::default(),
            &FontMetricTable::default(),
        )
        .unwrap()
        .unwrap();
        assert!((document.objects[0].bounds.height - 62.4).abs() < 0.01);
        assert!((document.objects[1].bounds.height - 62.4).abs() < 0.01);
        assert!((document.objects[3].bounds.height - 41.6).abs() < 0.01);
        let last = document
            .objects
            .iter()
            .filter(|o| o.unit_index == 0)
            .last()
            .unwrap();
        // Word leaves three lines of this paragraph on page one.
        assert!(
            (last.bounds.height - 124.8).abs() < 0.01,
            "{:?}",
            last.bounds
        );
        let Visual::TextLayout { layout, visual } = &last.visual else {
            panic!("text layout")
        };
        assert!(layout.continues_after);
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("rich text")
        };
        assert_eq!(
            runs.iter().map(|run| run.text.as_str()).collect::<String>(),
            last.text.as_deref().unwrap()
        );
        let first = document.objects.iter().find(|o| o.unit_index == 1).unwrap();
        assert_eq!(
            format!(
                "{}{}",
                last.text.as_deref().unwrap(),
                first.text.as_deref().unwrap()
            ),
            "需要特别说明的是，本协议不适用于其他第三方向您提供的服务，为确保流畅的产品体验，您可能会收到来自第三方提供的内容或网络链接。请您谨慎选择是否访问第三方提供的链接、内容、产品和服务。在向第三方提交个人信息之前，请认真阅读这些第三方的隐私协议。"
        );
        let Visual::TextLayout { layout, .. } = &first.visual else {
            panic!("text layout")
        };
        assert_eq!(layout.paragraphs[0].first_line_indent, 0.0);
        assert!(!layout.continues_after);
        assert!((first.bounds.height - 83.2).abs() < 0.01);
    }

    #[test]
    fn native_doc_preserves_supplied_auto_table_row_height() {
        let bytes = include_bytes!("../../tests/fixtures/word-table-auto-height.doc");
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let cells: Vec<_> = document
            .objects
            .iter()
            .filter(|object| {
                matches!(&object.visual, Visual::TextLayout { visual, .. }
                if matches!(visual.as_ref(), Visual::RichText { stroke: Paint::Solid(_), .. }))
            })
            .collect();
        assert_eq!(cells.len(), 15);
        assert_eq!(cells[2].text.as_deref(), Some("123123"));
        // Word's native PDF has 16.08 pt rows (21.44 px). The legacy
        // font-size line-box estimate may differ by up to 1.5 px.
        for (index, cell) in cells.iter().enumerate() {
            assert!(
                (cell.bounds.height - 21.44).abs() < 1.5,
                "{:?}",
                cell.bounds
            );
            assert!((cell.bounds.width - 113.6).abs() < 0.1);
            assert!((cell.bounds.y - cells[index / 5 * 5].bounds.y).abs() < 0.01);
            if index >= 5 {
                let above = &cells[index - 5];
                assert!((cell.bounds.y - above.bounds.y - above.bounds.height).abs() < 0.01);
            }
            let Visual::TextLayout { layout, .. } = &cell.visual else {
                unreachable!()
            };
            assert_eq!((layout.inset_top, layout.inset_bottom), (0.0, 0.0));
        }
    }

