    #[test]
    fn native_doc_preserves_direct_character_formatting() {
        let cfb = build_cfb(&[
            ("WordDocument", formatted_doc_word_stream()),
            ("0Table", formatted_doc_table_stream()),
        ]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        let Visual::TextLayout { visual, .. } = &document.objects[0].visual else {
            panic!("DOC paragraph must preserve text layout");
        };
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("DOC paragraph must render as rich text");
        };
        assert_eq!(runs.len(), 2);
        assert_eq!(runs[0].text, "Bold");
        assert_eq!(runs[0].font_family, "Arial");
        assert!((runs[0].font_size - 20.0 * 96.0 / 72.0).abs() < 0.01);
        assert_eq!(runs[0].color, 0xff00_00ff);
        assert!(runs[0].bold);
        assert!(!runs[0].italic);
        assert_eq!(runs[1].text, "Italic");
        assert_eq!(runs[1].font_family, "Courier New");
        assert!((runs[1].font_size - 14.0 * 96.0 / 72.0).abs() < 0.01);
        assert!(!runs[1].bold);
        assert!(runs[1].italic);
        assert!(runs[1].underline);
    }

    #[test]
    fn native_doc_preserves_character_reset_order() {
        let baseline = DocCharStyle::default();
        let italic_patch = DocCharPatch {
            italic: Some(1),
            ..DocCharPatch::default()
        };
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: baseline.clone(),
            default_char_style: baseline.clone(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles: vec![
                None,
                Some(DocResolvedStyle {
                    is_paragraph: false,
                    paragraph: DocParagraphStyle::default(),
                    character: italic_patch.apply(&baseline),
                    base: None,
                    character_patch: italic_patch,
                }),
            ],
        };
        let mut style_chain = Vec::new();

        let plain_after_bold =
            parse_doc_character_patch(&[0x35, 0x08, 0x01, 0x33, 0x2a, 0x00]).unwrap();
        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&plain_after_bold, &baseline, &mut state, &mut style_chain)
            .unwrap();
        assert!(!state.current.bold);
        assert!(!state.current.italic);

        let style_after_bold =
            parse_doc_character_patch(&[0x35, 0x08, 0x01, 0x30, 0x4a, 0x01, 0x00]).unwrap();
        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&style_after_bold, &baseline, &mut state, &mut style_chain)
            .unwrap();
        assert!(!state.current.bold);
        assert!(state.current.italic);

        let bold_after_style =
            parse_doc_character_patch(&[0x30, 0x4a, 0x01, 0x00, 0x35, 0x08, 0x01]).unwrap();
        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&bold_after_style, &baseline, &mut state, &mut style_chain)
            .unwrap();
        assert!(state.current.bold);
        assert!(state.current.italic);
    }

    #[test]
    fn native_doc_applies_character_style_permutations() {
        let mut hit = vec![
            0x5a, 0x08, 0x01, // sprmCFBiDi
            0x6f, 0x28, 0x02, // sprmCIdctHint: cs
            0x31, 0xca, 0x07, // sprmCIstdPermute operand length
            0x00, 0x0a, 0x00, 0x0a, 0x00, 0x01, 0x00,
        ];
        let (patch, reset) = parse_doc_character_patch_state(&hit).unwrap();
        assert!(reset);
        assert_eq!(patch.style_id, Some(1));
        assert_eq!(patch.bidi, Some(1));
        assert_eq!(patch.hint, Some(2));

        hit[10] = 0x0b;
        hit[12] = 0x0b;
        let (patch, reset) = parse_doc_character_patch_state(&hit).unwrap();
        assert!(!reset);
        assert_eq!(patch.style_id, None);
        assert_eq!(patch.bidi, Some(1));
        assert_eq!(patch.hint, Some(2));
    }

    #[test]
    fn native_doc_reapplies_direct_character_formatting_after_style_permutation() {
        let baseline = DocCharStyle::default();
        let replacement_patch = DocCharPatch {
            font_ids: [Some(3), None, None, None],
            font_size: Some(12.0),
            color: Some(0x0000_ffff),
            bold: Some(1),
            ..DocCharPatch::default()
        };
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: baseline.clone(),
            default_char_style: baseline.clone(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles: vec![
                None,
                Some(DocResolvedStyle {
                    is_paragraph: false,
                    paragraph: DocParagraphStyle::default(),
                    character: replacement_patch.apply(&baseline),
                    base: None,
                    character_patch: replacement_patch,
                }),
            ],
        };
        let (patch, reset) = parse_doc_character_patch_state(&[
            0x35, 0x08, 0x81, // sprmCFBold: invert the old style baseline
            0x36, 0x08, 0x01, // sprmCFItalic
            0x4f, 0x4a, 0x07, 0x00, // sprmCRgFtc0
            0x43, 0x4a, 0x28, 0x00, // sprmCHps: 20 pt
            0x42, 0x2a, 0x06, // sprmCIco: red
            0x31, 0xca, 0x07, // sprmCIstdPermute operand length
            0x00, 0x0a, 0x00, 0x0a, 0x00, 0x01, 0x00,
        ])
        .unwrap();

        assert!(reset);
        assert_eq!(patch.style_id, Some(1));
        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&patch, &baseline, &mut state, &mut Vec::new())
            .unwrap();
        assert!(state.style_baseline.bold);
        assert!(state.current.bold);
        assert!(state.current.italic);
        assert_eq!(state.current.font_ids[0], Some(7));
        assert!((state.current.font_size - 20.0 * 96.0 / 72.0).abs() < 0.01);
        assert_eq!(state.current.color, 0xff00_00ff);
    }

    #[test]
    fn native_doc_preserves_character_formatting_order_across_repeated_style_permutations() {
        let baseline = DocCharStyle::default();
        let bold_patch = DocCharPatch {
            bold: Some(1),
            ..DocCharPatch::default()
        };
        let plain_patch = DocCharPatch {
            bold: Some(0),
            ..DocCharPatch::default()
        };
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: baseline.clone(),
            default_char_style: baseline.clone(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles: vec![
                None,
                Some(DocResolvedStyle {
                    is_paragraph: false,
                    paragraph: DocParagraphStyle::default(),
                    character: bold_patch.apply(&baseline),
                    base: None,
                    character_patch: bold_patch,
                }),
                Some(DocResolvedStyle {
                    is_paragraph: false,
                    paragraph: DocParagraphStyle::default(),
                    character: plain_patch.apply(&baseline),
                    base: None,
                    character_patch: plain_patch,
                }),
            ],
        };
        let (patch, reset) = parse_doc_character_patch_state(&[
            0x35, 0x08, 0x81, // old baseline=false, so direct bold=true
            0x31, 0xca, 0x07, // style 10 -> style 1 (bold baseline=true)
            0x00, 0x0a, 0x00, 0x0a, 0x00, 0x01, 0x00, 0x35, 0x08,
            0x81, // new baseline=true, so direct bold=false
            0x31, 0xca, 0x07, // style 1 -> style 2 (bold baseline=false)
            0x00, 0x01, 0x00, 0x01, 0x00, 0x02, 0x00,
        ])
        .unwrap();

        assert!(reset);
        assert_eq!(patch.style_id, Some(2));
        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&patch, &baseline, &mut state, &mut Vec::new())
            .unwrap();
        assert!(!state.style_baseline.bold);
        assert!(!state.current.bold);
    }

    #[test]
    fn native_doc_reuses_a_short_character_style_chain_scratch() {
        let baseline = DocCharStyle::default();
        let bold_patch = DocCharPatch {
            bold: Some(1),
            ..DocCharPatch::default()
        };
        let italic_patch = DocCharPatch {
            italic: Some(1),
            ..DocCharPatch::default()
        };
        let mut styles = vec![None; 4093];
        styles[1] = Some(DocResolvedStyle {
            is_paragraph: false,
            paragraph: DocParagraphStyle::default(),
            character: bold_patch.apply(&baseline),
            base: None,
            character_patch: bold_patch,
        });
        styles[2] = Some(DocResolvedStyle {
            is_paragraph: false,
            paragraph: DocParagraphStyle::default(),
            character: italic_patch
                .apply(&styles[1].as_ref().expect("base style must exist").character),
            base: Some(1),
            character_patch: italic_patch,
        });
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: baseline.clone(),
            default_char_style: baseline.clone(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles,
        };
        let patch = DocCharPatch {
            style_id: Some(2),
            ..DocCharPatch::default()
        };
        let mut style_chain = Vec::new();

        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&patch, &baseline, &mut state, &mut style_chain)
            .unwrap();
        assert!(state.current.bold);
        assert!(state.current.italic);
        assert!(style_chain.capacity() <= 8);
        let capacity = style_chain.capacity();

        let mut state = DocCharState::new(&baseline);
        formatting
            .apply_character_patch_state(&patch, &baseline, &mut state, &mut style_chain)
            .unwrap();
        assert!(state.current.bold);
        assert!(state.current.italic);
        assert_eq!(style_chain.capacity(), capacity);
    }

    #[test]
    fn native_doc_keeps_ascii_other_and_bi_character_channels_separate() {
        let patch = parse_doc_character_patch(&[
            0x43, 0x4a, 20, 0, // sprmCHps: 10 pt
            0x61, 0x4a, 40, 0, // sprmCHpsBi: 20 pt
            0x4f, 0x4a, 0, 0, // sprmCRgFtc0: ASCII
            0x51, 0x4a, 1, 0, // sprmCRgFtc2: Other
            0x5e, 0x4a, 2, 0, // sprmCFtcBi: Bi
            0x5c, 0x08, 1, // sprmCFBoldBi
            0x5d, 0x08, 1, // sprmCFItalicBi
        ])
        .unwrap();
        let style = patch.apply(&DocCharStyle::default());
        let fonts = vec!["ASCII".to_owned(), "Other".to_owned(), "Bi".to_owned()];

        let ascii = doc_text_run('A', &style, &fonts, false);
        assert_eq!(ascii.font_family, "ASCII");
        assert!((ascii.font_size - 10.0 * 96.0 / 72.0).abs() < 0.01);
        assert!(!ascii.bold);
        assert!(!ascii.italic);

        let other = doc_text_run('Ω', &style, &fonts, false);
        assert_eq!(other.font_family, "Other");
        assert!((other.font_size - 10.0 * 96.0 / 72.0).abs() < 0.01);
        assert!(!other.bold);
        assert!(!other.italic);

        let bi = doc_text_run('ا', &style, &fonts, false);
        assert_eq!(bi.font_family, "Bi");
        assert!((bi.font_size - 20.0 * 96.0 / 72.0).abs() < 0.01);
        assert!(bi.bold);
        assert!(bi.italic);
    }

    #[test]
    fn native_doc_honors_forced_complex_and_east_asian_character_channels() {
        let fonts = vec![
            "ASCII".to_owned(),
            "Other".to_owned(),
            "Bi".to_owned(),
            "East Asian".to_owned(),
        ];
        let base = [
            0x4f, 0x4a, 0, 0, // sprmCRgFtc0
            0x50, 0x4a, 3, 0, // sprmCRgFtc1
            0x51, 0x4a, 1, 0, // sprmCRgFtc2
            0x5e, 0x4a, 2, 0, // sprmCFtcBi
            0x61, 0x4a, 40, 0, // sprmCHpsBi: 20 pt
            0x60, 0x4a, 6, 0, // sprmCIcoBi: red
            0x5c, 0x08, 1, // sprmCFBoldBi
            0x5d, 0x08, 1, // sprmCFItalicBi
        ];
        for force in [
            [0x5a, 0x08, 1], // sprmCFBiDi
            [0x82, 0x08, 1], // sprmCFComplexScripts
            [0x6f, 0x28, 2], // sprmCIdctHint: cs
        ] {
            let mut grpprl = base.to_vec();
            grpprl.extend_from_slice(&force);
            let style = parse_doc_character_patch(&grpprl)
                .unwrap()
                .apply(&DocCharStyle::default());
            let run = doc_text_run('A', &style, &fonts, true);
            assert_eq!(run.font_family, "Bi");
            assert!((run.font_size - 20.0 * 96.0 / 72.0).abs() < 0.01);
            assert_eq!(run.color, 0xff00_00ff);
            assert!(run.bold);
            assert!(run.italic);
        }

        let mut grpprl = base.to_vec();
        grpprl.extend_from_slice(&[0x6f, 0x28, 1]);
        let style = parse_doc_character_patch(&grpprl)
            .unwrap()
            .apply(&DocCharStyle::default());
        assert_eq!(
            doc_text_run('A', &style, &fonts, false).font_family,
            "East Asian"
        );
    }

    #[test]
    fn native_doc_prefers_explicit_character_scripts_over_ambiguous_hints() {
        let fonts = vec![
            "ASCII".to_owned(),
            "East Asian".to_owned(),
            "Bi".to_owned(),
            "Other".to_owned(),
        ];
        let base = DocCharStyle {
            font_ids: [Some(0), Some(1), Some(3), Some(2)],
            ..DocCharStyle::default()
        };
        let east_asian_hint = DocCharStyle {
            hint: 1,
            ..base.clone()
        };
        assert_eq!(
            doc_text_run('ا', &east_asian_hint, &fonts, false).font_family,
            "Bi"
        );
        let complex_hint = DocCharStyle {
            hint: 2,
            ..base.clone()
        };
        assert_eq!(
            doc_text_run('中', &complex_hint, &fonts, false).font_family,
            "East Asian"
        );
        assert_eq!(doc_text_run('ᠠ', &base, &fonts, false).font_family, "Bi");
    }

    #[test]
    fn native_doc_uses_bi_color_only_for_word_97_documents() {
        let style = parse_doc_character_patch(&[
            0x42, 0x2a, 0x04, // sprmCIco: green
            0x60, 0x4a, 0x06, 0x00, // sprmCIcoBi: red
        ])
        .unwrap()
        .apply(&DocCharStyle::default());
        assert_eq!(doc_text_run('ا', &style, &[], true).color, 0xff00_00ff);
        assert_eq!(doc_text_run('ا', &style, &[], false).color, 0x00ff_00ff);
    }

