    #[test]
    fn native_doc_bounds_rich_text_runs_before_protocol_encoding() {
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: DocCharStyle::default(),
            default_char_style: DocCharStyle::default(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles: Vec::new(),
        };
        let mut saturated_run = doc_text_run(
            'x',
            &DocCharStyle::default(),
            &formatting.fonts,
            formatting.legacy_bi_color,
        );
        saturated_run.text.clear();
        saturated_run.font_family.clear();
        let mut collector = ParagraphCollector::new(usize::MAX, 1);
        collector.current_runs = vec![saturated_run; MAX_RICH_TEXT_RUNS];
        let different_style = DocCharStyle {
            bold: true,
            ..DocCharStyle::default()
        };

        let error = collector
            .append('x', &different_style, &formatting)
            .unwrap_err();
        assert_eq!(error.code, DiagnosticCode::InputTooLarge);
        assert!(error.message.contains("protocol rich-text run limit"));
        assert!(collector.current.is_empty());
    }

    #[test]
    fn native_doc_counts_empty_chpx_records_toward_limit() {
        let mut word = vec![0u8; 1024];
        word[511] = 2;
        word[1023] = 2;
        for (offset, value) in [
            (0, 0u32),
            (4, 50),
            (8, 100),
            (512, 100),
            (516, 150),
            (520, 200),
        ] {
            write_u32(&mut word, offset, value);
        }

        let mut table = vec![0u8; 20];
        for (offset, value) in [(0, 0u32), (4, 100), (8, 200), (12, 0), (16, 1)] {
            write_u32(&mut table, offset, value);
        }

        let error = parse_doc_character_runs(&word, &table, (0, table.len()), 2).unwrap_err();
        assert_eq!(error.code, DiagnosticCode::InputTooLarge);
        assert!(error.message.contains("character-format run count exceeds"));
    }

