    #[test]
    fn native_doc_preserves_direct_paragraph_formatting() {
        let cfb = build_cfb(&[
            ("WordDocument", formatted_doc_word_stream()),
            ("0Table", formatted_doc_table_stream()),
        ]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        let object = &document.objects[0];
        let Visual::TextLayout { layout, visual } = &object.visual else {
            panic!("DOC paragraph must preserve text layout");
        };
        assert_eq!(layout.paragraphs.len(), 1);
        assert_eq!(layout.paragraphs[0].align, TextAlign::Center);
        assert_eq!(layout.paragraphs[0].margin_left, 48.0);
        assert_eq!(layout.paragraphs[0].margin_right, 24.0);
        assert_eq!(layout.paragraphs[0].first_line_indent, 16.0);
        assert_eq!(layout.paragraphs[0].default_tab_stop, 28.0);
        assert_eq!(layout.default_tab_stop, 28.0);
        assert_eq!(
            layout.tab_stops,
            vec![
                TextTabStop::from(96.0),
                TextTabStop {
                    position: 384.0,
                    align: TextAlign::Center,
                    leader: TextTabLeader::Dot,
                },
                TextTabStop {
                    position: 480.0,
                    align: TextAlign::End,
                    leader: TextTabLeader::Underscore,
                },
            ]
        );
        assert_eq!(object.bounds.y, DOC_PAGE_MARGIN + 16.0);
        let Visual::RichText {
            align, line_height, ..
        } = visual.as_ref()
        else {
            panic!("DOC paragraph must render as rich text");
        };
        assert_eq!(*align, TextAlign::Center);
        assert_eq!(*line_height, 20.0);
    }

    #[test]
    fn native_doc_list_tables_distinguish_numbering_from_bullets() {
        const NUMBERED_LSID: u32 = 0x1234_5678;
        const BULLET_LSID: u32 = 0x2345_6789;
        let mut table = vec![0u8; 256];
        write_u16(&mut table, 0, 2);
        write_u32(&mut table, 2, NUMBERED_LSID);
        table[2 + 26] = 1;
        write_u32(&mut table, 30, BULLET_LSID);
        table[30 + 26] = 1;

        let mut cursor = 58;
        write_u32(&mut table, cursor, 1);
        table[cursor + 4] = 0;
        table[cursor + 6] = 1;
        table[cursor + 15] = 0;
        write_u16(&mut table, cursor + 28, 2);
        write_u16(&mut table, cursor + 30, 0);
        write_u16(&mut table, cursor + 32, 0x3001);
        cursor += 34;

        write_u32(&mut table, cursor, 1);
        table[cursor + 4] = 0x17;
        table[cursor + 15] = 1;
        write_u16(&mut table, cursor + 28, 1);
        write_u16(&mut table, cursor + 30, 0x2022);

        let lfo_offset = 160;
        write_u32(&mut table, lfo_offset, 2);
        write_u32(&mut table, lfo_offset + 4, NUMBERED_LSID);
        write_u32(&mut table, lfo_offset + 20, BULLET_LSID);
        write_u32(&mut table, lfo_offset + 36, u32::MAX);
        write_u32(&mut table, lfo_offset + 40, u32::MAX);
        let fib = FibInfo {
            n_fib: 0x00c1,
            flags: 0,
            fc_min: 0,
            fc_mac: 0,
            ccp_text: 0,
            ccp_ftn: 0,
            ccp_hdd: 0,
            textbox_range: (0, 0),
            plcf_txbx_txt: None,
            stshf: None,
            plcf_fnd_ref: None,
            plcf_fnd_txt: None,
            plcf_sed: None,
            plcf_hdd: None,
            plcf_bte_chpx: None,
            plcf_bte_papx: None,
            sttbf_ffn: None,
            dop: None,
            clx: None,
            plcf_spa_mom: None,
            dgg_info: None,
            plf_lst: Some((0, 58)),
            plf_lfo: Some((lfo_offset, 44)),
        };
        let lists = parse_doc_list_tables(&table, fib, 32).unwrap();
        let paragraph = |text: &str, list_id| NativeParagraph {
            text: text.to_owned(),
            runs: vec![TextRun {
                east_asian_line_breaks: true,
                text: text.to_owned(),
                ..doc_default_text_run()
            }],
            empty_run: None,
            list_prefix: None,
            style: DocParagraphStyle {
                list_id,
                list_level_present: true,
                ..DocParagraphStyle::default()
            },
            cp_start: 0,
            cp_end: u32::try_from(text.len()).unwrap(),
            record_offset: 0,
            page_layout: DocPageLayout::default(),
            table_cell_end: false,
            section_break: false,
            picture_anchor: None,
        };
        let mut paragraphs = vec![
            paragraph("First", 1),
            paragraph("Second", 1),
            paragraph("Bullet", 2),
        ];

        let result = materialize_doc_list_prefixes(&mut paragraphs, &lists);

        assert!(!result.missing_definition);
        assert!(!result.approximated_number_format);
        assert_eq!(
            paragraphs
                .iter()
                .map(|paragraph| paragraph.list_prefix.as_deref())
                .collect::<Vec<_>>(),
            [Some("1、\t"), Some("2、\t"), Some("• ")]
        );
        assert_eq!(
            paragraphs
                .iter()
                .map(|paragraph| paragraph.text.as_str())
                .collect::<Vec<_>>(),
            ["First", "Second", "Bullet"]
        );
        let document = layout_doc(
            paragraphs,
            Vec::new(),
            &HashMap::new(),
            Vec::new(),
            HashMap::new(),
            Limits::default(),
            Vec::new(),
            &FontMetricTable::default(),
            &[],
        )
        .unwrap();
        assert_eq!(
            document
                .objects
                .iter()
                .filter_map(|object| object.text.as_deref())
                .collect::<Vec<_>>(),
            ["1、\tFirst", "2、\tSecond", "• Bullet"]
        );
    }

    #[test]
