    #[test]
    fn native_doc_applies_heading_level_increments_from_papx_and_pcd() {
        let baseline = DocCharStyle::default();
        let heading_two_character = DocCharStyle {
            bold: true,
            ..baseline.clone()
        };
        let mut styles = vec![None; 3];
        styles[1] = Some(DocResolvedStyle {
            is_paragraph: true,
            paragraph: DocParagraphStyle::default(),
            character: baseline.clone(),
            base: None,
            character_patch: DocCharPatch::default(),
        });
        styles[2] = Some(DocResolvedStyle {
            is_paragraph: true,
            paragraph: DocParagraphStyle {
                align: TextAlign::Center,
                ..DocParagraphStyle::default()
            },
            character: heading_two_character.clone(),
            base: None,
            character_patch: DocCharPatch::default(),
        });

        let mut style_id = 1;
        let mut paragraph = DocParagraphStyle::default();
        let mut character = baseline.clone();
        apply_doc_paragraph_properties(
            &[0x02, 0x26, 0x01],
            &[],
            &mut style_id,
            &mut paragraph,
            &mut character,
            &baseline,
            &styles,
        )
        .unwrap();
        assert_eq!(style_id, 2);
        assert_eq!(paragraph.align, TextAlign::Center);
        assert_eq!(character, heading_two_character);

        style_id = 1;
        paragraph = DocParagraphStyle::default();
        character = baseline.clone();
        let piece = parse_doc_piece_formatting(0x0108, &[]).unwrap();
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: baseline,
            default_char_style: DocCharStyle::default(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles,
        };
        piece
            .apply_paragraph(&mut style_id, &mut paragraph, &mut character, &formatting)
            .unwrap();
        assert_eq!(style_id, 2);
        assert_eq!(paragraph.align, TextAlign::Center);
        assert!(character.bold);
    }

    #[test]
    fn native_doc_distinguishes_minimum_and_exact_line_spacing() {
        for (twips, expected) in [(120i16, 20.0), (360, 24.0), (-360, 24.0)] {
            let mut grpprl = vec![0x12, 0x64];
            grpprl.extend_from_slice(&twips.to_le_bytes());
            grpprl.extend_from_slice(&0u16.to_le_bytes());
            let mut style = DocParagraphStyle::default();
            apply_doc_paragraph_grpprl(&grpprl, &mut style).unwrap();
            assert!(
                (doc_line_height(style, 20.0, DocPageLayout::default()) - expected).abs() < 0.01
            );
        }
    }

