    #[test]
    fn native_doc_uses_the_ending_piece_paragraph_style_across_pcds() {
        let mut word = styled_doc_word_stream();
        write_u32(&mut word, 28, 771);
        write_u32(&mut word, 36 + 3 * 4, 6);
        write_u32(&mut word, 82 + 33 * 8 + 4, 33);
        word[512..515].copy_from_slice(b"lo\r");
        word[768..771].copy_from_slice(b"Hel");

        let chpx_fkp = &mut word[1024..1536];
        chpx_fkp.fill(0);
        write_u32(chpx_fkp, 0, 768);
        write_u32(chpx_fkp, 4, 771);
        chpx_fkp[8] = 100;
        chpx_fkp[511] = 1;
        chpx_fkp[200] = 3;
        chpx_fkp[201..204].copy_from_slice(&[0x35, 0x08, 0x00]);

        let papx_fkp = &mut word[1536..2048];
        papx_fkp.fill(0);
        for (offset, value) in [(0, 512u32), (4, 515), (8, 768), (12, 771)] {
            write_u32(papx_fkp, offset, value);
        }
        papx_fkp[16] = 100;
        papx_fkp[42] = 110;
        papx_fkp[511] = 3;
        papx_fkp[200] = 0;
        papx_fkp[201] = 1;
        write_u16(papx_fkp, 202, 1);
        papx_fkp[220] = 0;
        papx_fkp[221] = 1;
        write_u16(papx_fkp, 222, 0);

        let mut table = styled_doc_table_stream();
        table[..33].fill(0);
        table[0] = 0x02;
        write_u32(&mut table, 1, 28);
        for (offset, value) in [(5, 0u32), (9, 3), (13, 6)] {
            write_u32(&mut table, offset, value);
        }
        write_u16(&mut table, 17, 1); // fNoParaLast
        write_u32(&mut table, 19, 0x4000_0000 | (768 * 2));
        write_u16(&mut table, 23, 0x00a6); // Prm0: sprmCPlain
        write_u32(&mut table, 27, 0x4000_0000 | (512 * 2));
        write_u16(&mut table, 31, 0x010a); // Prm0: sprmPJc, center
        for (offset, value) in [(64, 768u32), (68, 771), (72, 2)] {
            write_u32(&mut table, offset, value);
        }
        for (offset, value) in [(224, 512u32), (228, 771), (232, 3)] {
            write_u32(&mut table, offset, value);
        }

        let cfb = build_cfb(&[("WordDocument", word), ("0Table", table)]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        let Visual::TextLayout { layout, visual } = &document.objects[0].visual else {
            panic!("DOC paragraph must preserve text layout");
        };
        assert_eq!(layout.paragraphs[0].align, TextAlign::Center);
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("DOC paragraph must render as rich text");
        };
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0].text, "Hello");
        assert_eq!(runs[0].font_family, "Arial");
        assert!(runs[0].bold);
    }

    #[test]
    fn native_doc_distinguishes_section_ends_from_manual_page_breaks() {
        for (section_cps, expected_units) in
            [(vec![0u32, 2, 4], vec![0, 0]), (vec![0u32, 4], vec![0, 1])]
        {
            let mut word = minimal_doc_word_stream();
            write_u32(&mut word, 28, 516);
            write_u32(&mut word, 36 + 3 * 4, 4);
            write_u32(&mut word, 82 + 6 * 8, 64);
            let section_count = section_cps.len() - 1;
            let plcf_sed_len = section_cps.len() * 4 + section_count * 12;
            write_u32(
                &mut word,
                82 + 6 * 8 + 4,
                u32::try_from(plcf_sed_len).unwrap(),
            );
            word[512..516].copy_from_slice(b"A\x0cB\r");

            let mut table = minimal_doc_table_stream();
            write_u32(&mut table, 9, 4);
            for (index, cp) in section_cps.into_iter().enumerate() {
                write_u32(&mut table, 64 + index * 4, cp);
            }

            let cfb = build_cfb(&[("WordDocument", word), ("0Table", table)]);
            let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
            assert_eq!(
                document
                    .objects
                    .iter()
                    .filter_map(|object| object.text.as_deref())
                    .collect::<Vec<_>>(),
                ["A", "B"]
            );
            // The supplied complex1_NOR.doc establishes that a manual break advances
            // the page; section boundaries remain independent of that manual break.
            assert_eq!(
                document
                    .objects
                    .iter()
                    .map(|o| o.unit_index)
                    .collect::<Vec<_>>(),
                expected_units
            );
        }
    }

    #[test]
    fn native_doc_section_properties_control_page_geometry() {
        let mut word = vec![0u8; 40];
        write_u16(&mut word, 2, 32);
        for (index, (sprm, value)) in [
            (0xb01f, 11_906u16),
            (0xb020, 16_838),
            (0xb021, 1_440),
            (0xb022, 1_080),
            (0x9023, 720),
            (0x9024, 900),
            (0x9031, 312),
            (0x5032, 2),
        ]
        .into_iter()
        .enumerate()
        {
            write_u16(&mut word, 4 + index * 4, sprm);
            write_u16(&mut word, 6 + index * 4, value);
        }

        let layout = parse_doc_section_layout(&word, 2).unwrap().layout;
        assert!((layout.width - 11_906.0 / 15.0).abs() < 0.01);
        assert!((layout.height - 16_838.0 / 15.0).abs() < 0.01);
        assert_eq!(layout.margin_left, 96.0);
        assert_eq!(layout.margin_right, 72.0);
        assert_eq!(layout.margin_top, 48.0);
        assert_eq!(layout.margin_bottom, 60.0);
        assert_eq!(layout.grid_line_pitch, Some(20.8));

        let style = DocParagraphStyle::default();
        assert!((doc_line_height(style, 26.25, layout) - 41.6).abs() < 0.01);
        let mut off_grid = style;
        apply_doc_paragraph_sprm(0x2447, &[0], &mut off_grid).unwrap();
        assert_eq!(doc_line_height(off_grid, 26.25, layout), 26.25);
        let mut table_paragraph = style;
        apply_doc_paragraph_sprm(0x2416, &[1], &mut table_paragraph).unwrap();
        assert_eq!(doc_line_height(table_paragraph, 26.25, layout), 26.25);
    }

