    #[test]
    fn native_doc_decodes_a_utf16_surrogate_pair_across_pcds() {
        let mut word = minimal_doc_word_stream();
        write_u32(&mut word, 28, 604);
        write_u32(&mut word, 36 + 3 * 4, 3);
        write_u32(&mut word, 82 + 33 * 8 + 4, 33);
        write_u16(&mut word, 512, 0xd83d);
        write_u16(&mut word, 600, 0xde00);
        write_u16(&mut word, 602, 0x000d);

        let mut table = minimal_doc_table_stream();
        table[..33].fill(0);
        table[0] = 0x02;
        write_u32(&mut table, 1, 28);
        for (offset, value) in [(5, 0u32), (9, 1), (13, 3)] {
            write_u32(&mut table, offset, value);
        }
        write_u16(&mut table, 17, 1); // fNoParaLast
        write_u32(&mut table, 19, 512);
        write_u16(&mut table, 23, 0x01aa); // Prm0: sprmCFBold, val=1
        write_u32(&mut table, 27, 600);
        write_u16(&mut table, 31, 0x01ac); // Prm0: sprmCFItalic, val=1

        let cfb = build_cfb(&[("WordDocument", word), ("0Table", table)]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        assert_eq!(document.objects[0].text.as_deref(), Some("😀"));
        let Visual::TextLayout { visual, .. } = &document.objects[0].visual else {
            panic!("DOC paragraph must preserve text layout");
        };
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("DOC paragraph must render as rich text");
        };
        assert_eq!(runs.len(), 1);
        assert!(runs[0].bold);
        assert!(!runs[0].italic);
    }

