    #[test]
    fn native_doc_coalesces_table_row_markers_with_the_preceding_cell() {
        let formatting = DocFormatting {
            fonts: Vec::new(),
            legacy_bi_color: false,
            document_char_style: DocCharStyle::default(),
            default_char_style: DocCharStyle::default(),
            char_runs: Vec::new(),
            default_paragraph_style: DocParagraphStyle::default(),
            paragraph_runs: Vec::new(),
            styles: Vec::new(),
        };
        let text_style = DocParagraphStyle {
            in_table: true,
            ..DocParagraphStyle::default()
        };
        let text_context = DocParagraphContext {
            cp_start: 0,
            cp_end: 2,
            style: text_style,
            char_style: DocCharStyle::default(),
            section_break: false,
            page_layout: DocPageLayout::default(),
        };
        let mut marker_style = text_style;
        marker_style.table_row_end = true;
        marker_style.table_cell_count = 1;
        marker_style.table_cell_edges[..2].copy_from_slice(&[0, 1_440]);
        let marker_context = DocParagraphContext {
            cp_start: 2,
            cp_end: 3,
            style: marker_style,
            char_style: DocCharStyle::default(),
            section_break: false,
            page_layout: DocPageLayout::default(),
        };
        let mut collector = ParagraphCollector::new(usize::MAX, 2);
        for (character, cp, context) in [
            ('A', (0, 1), &text_context),
            ('\u{7}', (1, 1), &text_context),
            ('\u{7}', (2, 1), &marker_context),
        ] {
            collector
                .push(
                    character,
                    cp,
                    cp.0,
                    &formatting,
                    &DocPieceFormatting::default(),
                    context,
                )
                .unwrap();
        }
        let (paragraphs, _) = collector.finish().unwrap();
        assert_eq!(paragraphs.len(), 1);
        assert_eq!(paragraphs[0].text, "A");
        assert!(paragraphs[0].table_cell_end);
        assert!(paragraphs[0].style.table_row_end);
        assert_eq!(paragraphs[0].style.table_cell_edges[..2], [0, 1_440]);
        for (lines, authored_twips, expected_height) in [
            (1, 0, 20.0),
            (2, 0, 40.0),
            (9, 0, 180.0),
            (1, 600, 40.0),
            (9, 600, 180.0),
            (9, -600, 40.0),
        ] {
            let mut cell = paragraphs[0].clone();
            cell.text = vec!["A"; lines].join("\n");
            cell.runs[0].text = cell.text.clone();
            cell.runs[0].font_size = 16.0;
            cell.style.table_row_height = authored_twips;
            let document = layout_doc(
                vec![cell],
                Vec::new(),
                &HashMap::new(),
                Vec::new(),
                HashMap::new(),
                Limits::default(),
                Vec::new(),
                &FontMetricTable::default(),
                &[],
            )
            .unwrap();
            assert!(
                (document.objects[0].bounds.height - expected_height).abs() < 0.01,
                "lines={lines}, authored_twips={authored_twips}"
            );
        }
    }

