    #[test]
    fn native_doc_appends_piece_style_permutations_to_chpx_state() {
        const CHPX: &[u8] = &[
            0x30, 0x4a, 0x02, 0x00, // sprmCIstd: Character
            0x35, 0x08, 0x01, // sprmCFBold
            0x43, 0x4a, 0x28, 0x00, // sprmCHps: 20 pt
            0x42, 0x2a, 0x06, // sprmCIco: red
        ];
        const HIT: &[u8] = &[
            0x31, 0xca, 0x17, // sprmCIstdPermute operand length
            0x00, 0x02, 0x00, 0x0a, 0x00, // map styles 2 through 10
            0x03, 0x00, // style 2 -> Replacement
            0x03, 0x00, 0x04, 0x00, 0x05, 0x00, 0x06, 0x00, 0x07, 0x00, 0x08, 0x00, 0x09, 0x00,
            0x00, 0x00, // style 10 -> Normal
        ];
        const MISS: &[u8] = &[
            0x31, 0xca, 0x07, // sprmCIstdPermute operand length
            0x00, 0x04, 0x00, 0x04, 0x00, 0x03, 0x00, // only style 4 is mapped
        ];

        for (piece_grpprl, expected_font, expected_italic, expected_underline) in [
            (HIT, "Arial", false, true),
            (MISS, "Courier New", true, false),
        ] {
            let mut word = styled_doc_word_stream();
            let clx_len = 3 + piece_grpprl.len() + 21;
            write_u32(&mut word, 82 + 33 * 8 + 4, u32::try_from(clx_len).unwrap());
            let chpx = 1024 + 200;
            word[chpx] = u8::try_from(CHPX.len()).unwrap();
            word[chpx + 1..chpx + 1 + CHPX.len()].copy_from_slice(CHPX);

            let base = styled_doc_table_stream();
            let clx = base[..21].to_vec();
            let mut table = base;
            table[..clx_len].fill(0);
            table[0] = 0x01;
            write_u16(&mut table, 1, u16::try_from(piece_grpprl.len()).unwrap());
            table[3..3 + piece_grpprl.len()].copy_from_slice(piece_grpprl);
            let clx_start = 3 + piece_grpprl.len();
            table[clx_start..clx_start + clx.len()].copy_from_slice(&clx);
            write_u16(&mut table, clx_start + 19, 0x0001); // Prm1: RgPrc[0]

            let cfb = build_cfb(&[("WordDocument", word), ("0Table", table)]);
            let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
            let Visual::TextLayout { visual, .. } = &document.objects[0].visual else {
                panic!("DOC paragraph must preserve text layout");
            };
            let Visual::RichText { runs, .. } = visual.as_ref() else {
                panic!("DOC paragraph must render as rich text");
            };
            assert_eq!(runs.len(), 1);
            assert_eq!(runs[0].text, "Styled");
            assert_eq!(runs[0].font_family, expected_font);
            assert!((runs[0].font_size - 20.0 * 96.0 / 72.0).abs() < 0.01);
            assert_eq!(runs[0].color, 0xff00_00ff);
            assert!(runs[0].bold);
            assert_eq!(runs[0].italic, expected_italic);
            assert_eq!(runs[0].underline, expected_underline);
        }
    }

