    #[test]
    fn native_ppt_resolves_outline_text_referenced_by_a_shape() {
        let mut shape_body = ppt_record((1 << 4) | 2, OFFICE_ART_SP, &[0; 8]);
        let mut properties = Vec::new();
        properties.extend_from_slice(&0x0087_u16.to_le_bytes());
        properties.extend_from_slice(&1_u32.to_le_bytes());
        shape_body.extend_from_slice(&ppt_record((1 << 4) | 3, OFFICE_ART_OPT, &properties));
        let mut anchor = Vec::new();
        for value in [600_i16, 300, 3_600, 1_200] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        shape_body.extend_from_slice(&ppt_record(
            0x000f,
            OFFICE_ART_CLIENT_TEXTBOX,
            &ppt_record(0, RT_OUTLINE_TEXT_REF_ATOM, &0_u32.to_le_bytes()),
        ));
        let shape = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);
        let (mut powerpoint_document, mut current_user) = minimal_ppt_payloads_with_slide_prefix(
            Some("Referenced title\nSubtitle"),
            "0",
            &[shape],
        );
        powerpoint_document.resize(CFB_MINI_STREAM_CUTOFF, 0);
        current_user.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[
            (PPT_STREAM, powerpoint_document),
            (PPT_CURRENT_USER_STREAM, current_user),
        ]);

        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        let title = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Referenced title\nSubtitle"))
            .expect("referenced outline text");

        assert_eq!(
            title.bounds,
            Rect {
                x: 50.0,
                y: 100.0,
                width: 550.0,
                height: 100.0,
            }
        );
        let Visual::TextLayout { layout, visual } = &title.visual else {
            panic!("referenced outline text must retain text layout");
        };
        assert_eq!(layout.vertical_align, TextVerticalAlign::Center);
        let Visual::RichText { align, runs, .. } = visual.as_ref() else {
            panic!("referenced outline text must retain rich text styling");
        };
        assert_eq!(*align, TextAlign::Center);
        assert!(runs[0].bold);
        assert!((runs[0].font_size - 44.0 * 4.0 / 3.0).abs() < 0.001);
        assert!(
            document
                .objects
                .iter()
                .any(|object| object.text.as_deref() == Some("0"))
        );
    }

    #[test]
    fn native_ppt_keeps_outline_hyperlink_underlines_on_referenced_text() {
        let mut shape_body = ppt_record((1 << 4) | 2, OFFICE_ART_SP, &[0; 8]);
        let mut anchor = Vec::new();
        for value in [600_i16, 300, 3_600, 1_200] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        shape_body.extend_from_slice(&ppt_record(
            0x000f,
            OFFICE_ART_CLIENT_TEXTBOX,
            &ppt_record(0, RT_OUTLINE_TEXT_REF_ATOM, &0_u32.to_le_bytes()),
        ));
        let shape = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);

        let mut interactive = [0u8; 16];
        interactive[4..8].copy_from_slice(&14_u32.to_le_bytes());
        interactive[8] = 4;
        interactive[12] = 8;
        let interactive = ppt_record(
            0x000f,
            RT_INTERACTIVE_INFO,
            &ppt_record(0, RT_INTERACTIVE_INFO_ATOM, &interactive),
        );
        let mut range = Vec::new();
        range.extend_from_slice(&6_i32.to_le_bytes());
        range.extend_from_slice(&9_i32.to_le_bytes());
        let range = ppt_record(0, RT_TEXT_INTERACTIVE_INFO_ATOM, &range);
        let text = "Click HERE to Visit www.campcaleb.com";
        let (mut powerpoint_document, mut current_user) = minimal_ppt_payloads_with_outline_records(
            Some(text),
            "0",
            &[shape],
            &[interactive, range],
        );
        powerpoint_document.resize(CFB_MINI_STREAM_CUTOFF, 0);
        current_user.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[
            (PPT_STREAM, powerpoint_document),
            (PPT_CURRENT_USER_STREAM, current_user),
        ]);

        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        let object = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some(text))
            .expect("referenced outline text");
        let Visual::TextLayout { visual, .. } = &object.visual else {
            panic!("referenced outline text must retain text layout");
        };
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("referenced outline text must retain rich text styling");
        };
        assert!(runs.iter().any(|run| run.text == "HERE" && run.underline));
    }

