    #[test]
    fn native_ppt_does_not_treat_metafile_or_storage_records_as_external_links() {
        let metafile = ppt_record(0, RT_META_FILE, &[]);
        let storage = ppt_record(0, RT_EXTERNAL_OLE_OBJECT_STG, &[]);
        let media_atom = ppt_record(0, RT_EXTERNAL_MEDIA_ATOM, &[0; 16]);
        let embedded_wav = ppt_record(0x000f, RT_EXTERNAL_WAV_AUDIO_EMBEDDED, &media_atom);
        let (mut powerpoint_document, mut current_user) = minimal_ppt_payloads_with_slide_prefix(
            None,
            "Text",
            &[metafile, storage, embedded_wav],
        );
        powerpoint_document.resize(CFB_MINI_STREAM_CUTOFF, 0);
        current_user.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[
            (PPT_STREAM, powerpoint_document),
            (PPT_CURRENT_USER_STREAM, current_user),
        ]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        assert!(
            !document
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == DiagnosticCode::ExternalResourceBlocked)
        );
        assert!(
            !document
                .diagnostics
                .iter()
                .any(|diagnostic| diagnostic.code == DiagnosticCode::ActiveContentBlocked)
        );
    }

    #[test]
    fn native_ppt_exposes_shape_bound_embedded_wav_for_playback() {
        const WAV: &[u8] = b"RIFF\x04\0\0\0WAVE";
        let sound_id = "7"
            .encode_utf16()
            .flat_map(u16::to_le_bytes)
            .collect::<Vec<_>>();
        let mut sound = ppt_record(0x0020, RT_CSTRING, &sound_id);
        sound.extend_from_slice(&ppt_record(0, RT_SOUND_DATA_BLOB, WAV));
        let mut sound_collection = ppt_record(0, 0x07e5, &7_u32.to_le_bytes());
        sound_collection.extend_from_slice(&ppt_record(0x000f, RT_SOUND, &sound));
        let sound_collection = ppt_record(0x000f, RT_SOUND_COLLECTION, &sound_collection);

        let mut media_atom = 42_u32.to_le_bytes().to_vec();
        media_atom.extend_from_slice(&0_u32.to_le_bytes());
        let mut embedded_atom = 7_u32.to_le_bytes().to_vec();
        embedded_atom.extend_from_slice(&1_000_i32.to_le_bytes());
        let mut embedded_wav = ppt_record(0, RT_EXTERNAL_MEDIA_ATOM, &media_atom);
        embedded_wav.extend_from_slice(&ppt_record(
            0x0011,
            RT_EXTERNAL_WAV_AUDIO_EMBEDDED_ATOM,
            &embedded_atom,
        ));
        let mut external_objects = ppt_record(0, 0x040a, &42_u32.to_le_bytes());
        external_objects.extend_from_slice(&ppt_record(
            0x000f,
            RT_EXTERNAL_WAV_AUDIO_EMBEDDED,
            &embedded_wav,
        ));
        let external_objects = ppt_record(0x000f, RT_EXTERNAL_OBJECT_LIST, &external_objects);

        let mut shape_body = ppt_record((1 << 4) | 2, OFFICE_ART_SP, &[0; 8]);
        let mut anchor = Vec::new();
        for value in [100_i16, 100, 600, 600] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        let external_reference = ppt_record(0, RT_EXTERNAL_OBJECT_REF_ATOM, &42_u32.to_le_bytes());
        shape_body.extend_from_slice(&ppt_record(
            0x000f,
            OFFICE_ART_CLIENT_DATA,
            &external_reference,
        ));
        let shape = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);

        let (mut powerpoint_document, mut current_user) =
            minimal_ppt_payloads_with_document_records(
                None,
                "",
                &[sound_collection, external_objects],
                &[shape],
            );
        powerpoint_document.resize(CFB_MINI_STREAM_CUTOFF, 0);
        current_user.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[
            (PPT_STREAM, powerpoint_document),
            (PPT_CURRENT_USER_STREAM, current_user),
        ]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();

        assert!(document.objects.iter().any(|object| matches!(
            &object.visual,
            Visual::Media {
                kind: MediaKind::Audio,
                media_type,
                bytes,
                ..
            } if media_type == "audio/wav" && bytes == WAV
        )));
    }

    #[test]
    fn native_ppt_allows_persist_seed_equal_to_the_largest_persist_id() {
        let (mut powerpoint_document, mut current_user) = minimal_ppt_payloads(None, "Text");
        let edit_offset =
            usize::try_from(read_u32(&current_user, 16, PPT_CURRENT_USER_STREAM).unwrap()).unwrap();
        write_u32(&mut powerpoint_document, edit_offset + 8 + 20, 2);
        powerpoint_document.resize(CFB_MINI_STREAM_CUTOFF, 0);
        current_user.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[
            (PPT_STREAM, powerpoint_document),
            (PPT_CURRENT_USER_STREAM, current_user),
        ]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        assert_eq!(document.objects[0].text.as_deref(), Some("Text"));
    }

