    #[test]
    fn ppt_line_preserves_office_art_arrowheads_and_sizes() {
        let mut shape_body = ppt_record((20 << 4) | 2, OFFICE_ART_SP, &[0; 8]);
        let mut properties = Vec::new();
        for (property, value) in [
            (0x01c0_u16, 0x0000_00ff_u32),
            (0x01cb, 12_700),
            (0x01d0, 1),
            (0x01d1, 5),
            (0x01d2, 2),
            (0x01d3, 2),
        ] {
            properties.extend_from_slice(&property.to_le_bytes());
            properties.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record((6 << 4) | 3, OFFICE_ART_OPT, &properties));
        let mut anchor = Vec::new();
        for value in [0_i16, 0, 1_200, 0] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        let bytes = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let (_, _, drawing) = parse_ppt_shape(
            &bytes,
            record,
            &[],
            None,
            PPT_DEFAULT_WIDTH,
            PPT_DEFAULT_HEIGHT,
            Limits::default(),
        )
        .unwrap();

        let Visual::Shape {
            geometry,
            fill,
            stroke,
            ..
        } = drawing.unwrap().visual
        else {
            panic!("line with arrowheads must remain a shape");
        };
        assert_eq!(fill, stroke);
        let Geometry::Path { commands, .. } = geometry else {
            panic!("line arrowheads must be represented by path geometry");
        };
        assert_eq!(commands.len(), 9);
        assert_eq!(commands[0], PathCommand::MoveTo { x: 0.0, y: 0.0 });
        assert_eq!(commands[1], PathCommand::LineTo { x: 200.0, y: 0.0 });
        assert_eq!(commands[5], PathCommand::ClosePath);
        assert!(matches!(
            commands.as_slice(),
            [
                ..,
                PathCommand::MoveTo { x: 192.0, y: -4.0 },
                PathCommand::LineTo { x: 200.0, y: 0.0 },
                PathCommand::LineTo { x: 192.0, y: 4.0 }
            ]
        ));
    }

