    #[test]
    fn ppt_supplied_stars_and_title() {
        let bytes = include_bytes!("../../tests/fixtures/tdf168786.ppt");
        let document = detect_and_parse(bytes, Limits::default()).unwrap().unwrap();
        let mut stars = 0;
        let mut rotated = 0;
        for object in &document.objects {
            let visual = match &object.visual {
                Visual::Layer { visual, .. } => {
                    rotated += 1;
                    visual.as_ref()
                }
                visual => visual,
            };
            if let Visual::PaintedShape {
                geometry: Geometry::Path { commands, .. },
                fill: Paint::ShapeGradient { stops, .. },
                ..
            } = visual
                && commands.len() == 11
            {
                stars += 1;
                assert_ne!(
                    stops.last().unwrap().color,
                    0xffff_ffff,
                    "procedural edge shade"
                );
            }
        }
        assert_eq!(stars, 12, "six foreground stars and six dark offset stars");
        assert!(rotated >= 8, "authored oblique star rotations");
        let title = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some("Employee of the Year - 2003"))
            .unwrap();
        let Visual::TextLayout { visual, .. } = &title.visual else {
            panic!("title layout")
        };
        let Visual::TextEffects { visual, effects } = visual.as_ref() else {
            panic!("title shadow")
        };
        assert_eq!(effects[0].shadow.as_ref().unwrap().color, 0x0000_00ff);
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("title text")
        };
        assert_eq!(runs[0].font_family, "Curlz MT");
    }

