    #[test]
    fn ppt_placeholder_is_detected_inside_office_art_client_data() {
        let mut placeholder_body = [0; 8];
        write_u32(&mut placeholder_body, 0, 7);
        let placeholder = ppt_record(0, RT_PLACEHOLDER_ATOM, &placeholder_body);
        let client_data = ppt_record(0, OFFICE_ART_CLIENT_DATA, &placeholder);
        let mut properties = Vec::new();
        properties.extend_from_slice(&0x03bf_u16.to_le_bytes());
        properties.extend_from_slice(&0x0002_0002_u32.to_le_bytes());
        let mut shape = ppt_record((1 << 4) | 3, OFFICE_ART_OPT, &properties);
        shape.extend_from_slice(&client_data);
        let bytes = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let metadata = ppt_shape_metadata(&bytes, record, Limits::default()).unwrap();
        assert!(metadata.placeholder);
        assert_eq!(metadata.placement_id, Some(7));
        assert!(metadata.hidden);
    }

