        wrap.extend_from_slice(&0x0085_u16.to_le_bytes());
        wrap.extend_from_slice(&2_u32.to_le_bytes());
        shape_body.extend_from_slice(&ppt_record((1 << 4) | 3, OFFICE_ART_OPT, &wrap));
        let mut anchor = Vec::new();
        for value in [0_i16, 0, 1_200, 600] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        let bytes = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);
