    #[test]
    fn ppt_direct_text_style_preserves_bullets_and_spacing() {
        let mut body = Vec::new();
        body.extend_from_slice(&5_u32.to_le_bytes());
        body.extend_from_slice(&0_u16.to_le_bytes());
        body.extend_from_slice(
            &((1_u32 << 12) | (1 << 11) | (1 << 7) | (1 << 6) | 1).to_le_bytes(),
        );
        body.extend_from_slice(&9_u16.to_le_bytes());
        body.extend_from_slice(&0x00a7_u16.to_le_bytes());
        body.extend_from_slice(&50_u16.to_le_bytes());
        body.extend_from_slice(&1_u16.to_le_bytes());
        body.extend_from_slice(&100_u16.to_le_bytes());
        body.extend_from_slice(&5_u32.to_le_bytes());
        body.extend_from_slice(&((1_u32 << 18) | (1 << 17) | (1 << 16) | 1).to_le_bytes());
        body.extend_from_slice(&1_u16.to_le_bytes());
        body.extend_from_slice(&3_u16.to_le_bytes());
        body.extend_from_slice(&24_u16.to_le_bytes());
        body.extend_from_slice(&0x0300_0000_u32.to_le_bytes());
        let bytes = ppt_record(0, RT_STYLE_TEXT_PROP_ATOM, &body);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let (paragraphs, runs) = parse_ppt_direct_text_style(&bytes, record, 4).unwrap();
        let paragraph = &paragraphs[0].style;

        assert_eq!(paragraph.bullet, Some(true));
        assert_eq!(paragraph.bullet_char, Some('\u{a7}'));
        assert_eq!(paragraph.bullet_size, Some(50));
        assert_eq!(paragraph.align, Some(TextAlign::Center));
        assert_eq!(paragraph.line_spacing, Some(100));
        assert!((ppt_paragraph_spacing(100, 38.4) - 38.4).abs() < 0.001);
        assert!((ppt_paragraph_spacing(-80, 38.4) - 13.333_333).abs() < 0.001);
        assert_eq!(ppt_bullet_font_size(50, 32.0), Some(16.0));
        assert_eq!(ppt_bullet_font_size(-12, 32.0), Some(16.0));
        assert_eq!(ppt_bullet_font_size(0, 32.0), None);
        assert_eq!(runs.len(), 1);
        assert_eq!(runs[0].1.font_ref, Some(3));
        assert_eq!(runs[0].1.font_size, Some(32.0));
        assert_eq!(runs[0].1.color, Some(0x0300_0000));
        assert_eq!(runs[0].1.bold, Some(true));
    }

