    #[test]
    fn native_ppt_preserves_symbol_typeface_arrow_glyphs() {
        let text = "left \u{f0df} right \u{f0e0}";
        let mut shape = ppt_record((1 << 4) | 2, OFFICE_ART_SP, &[0; 8]);
        let anchor = [600_i16, 300, 3_600, 1_200]
            .into_iter()
            .flat_map(i16::to_le_bytes)
            .collect::<Vec<_>>();
        shape.extend(ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        let mut textbox = ppt_record(0, RT_TEXT_HEADER_ATOM, &4_u32.to_le_bytes());
        textbox.extend(ppt_text_record(text));
        let mut style = 15_u32.to_le_bytes().to_vec();
        style.extend(0_u16.to_le_bytes()); // Paragraph level.
        style.extend(0_u32.to_le_bytes()); // No paragraph overrides.
        style.extend(15_u32.to_le_bytes());
        style.extend((1_u32 << 23).to_le_bytes()); // symbolTypeface.
        style.extend(1_u16.to_le_bytes()); // Wingdings; ordinary text remains Arial.
        textbox.extend(ppt_record(0, RT_STYLE_TEXT_PROP_ATOM, &style));
        shape.extend(ppt_record(0x000f, OFFICE_ART_CLIENT_TEXTBOX, &textbox));
        let shape = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape);
        let mut font = "Wingdings"
            .encode_utf16()
            .flat_map(u16::to_le_bytes)
            .collect::<Vec<_>>();
        font.resize(68, 0);
        let font = ppt_record(1 << 4, RT_FONT_ENTITY_ATOM, &font);
        let font = ppt_record(0x000f, 0x07d5, &font); // FontCollection.
        let (mut document, mut user) =
            minimal_ppt_payloads_with_document_records(None, "0", &[font], &[shape]);
        document.resize(CFB_MINI_STREAM_CUTOFF, 0);
        user.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[(PPT_STREAM, document), (PPT_CURRENT_USER_STREAM, user)]);
        let document = detect_and_parse(&cfb, Limits::default()).unwrap().unwrap();
        let object = document
            .objects
            .iter()
            .find(|object| object.text.as_deref() == Some(text))
            .unwrap();
        let Visual::TextLayout { visual, .. } = &object.visual else {
            panic!("text layout");
        };
        let Visual::RichText { runs, .. } = visual.as_ref() else {
            panic!("rich text");
        };
        assert_eq!(
            runs.iter()
                .map(|run| (run.text.as_str(), run.font_family.as_str()))
                .collect::<Vec<_>>(),
            [
                ("left ", "Arial"),
                ("\u{f0df}", "Wingdings"),
                (" right ", "Arial"),
                ("\u{f0e0}", "Wingdings")
            ]
        );
    }

    #[test]
    fn ppt_text_hyperlink_range_is_preserved() {
        let mut interactive = [0u8; 16];
        interactive[4..8].copy_from_slice(&14_u32.to_le_bytes());
        interactive[8] = 4;
        interactive[12] = 8;
        let interactive = ppt_record(0, RT_INTERACTIVE_INFO_ATOM, &interactive);
        let mut body = ppt_record(0x000f, RT_INTERACTIVE_INFO, &interactive);
        let mut range = Vec::new();
        range.extend_from_slice(&0_i32.to_le_bytes());
        range.extend_from_slice(&99_i32.to_le_bytes());
        body.extend_from_slice(&ppt_record(0, RT_TEXT_INTERACTIVE_INFO_ATOM, &range));
        let bytes = ppt_record(0x000f, OFFICE_ART_CLIENT_TEXTBOX, &body);
        let textbox = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let ranges = parse_ppt_hyperlink_ranges(&bytes, textbox, 100, Limits::default());
        assert_eq!(
            ranges,
            [PptHyperlinkRange {
                begin: 0,
                end: 100,
                visited: false,
            }]
        );
        let text = "x".repeat(100);
        let (mut runs, mut effects) =
            resolve_ppt_text_runs(&text, 4, &[], &[], None, &HashMap::new());
        let mut scheme = [0u32; 8];
        scheme[6] = 0xff00_00ff;
        apply_ppt_hyperlink_ranges(&mut runs, &mut effects, &ranges, Some(&scheme));
        assert_eq!(runs[0].color, 0xff00_00ff);
        assert!(runs[0].underline);
        assert_eq!(effects.len(), runs.len());

        let (mut runs, mut effects) =
            resolve_ppt_text_runs("abcdefgh", 4, &[], &[], None, &HashMap::new());
        apply_ppt_hyperlink_ranges(
            &mut runs,
            &mut effects,
            &[PptHyperlinkRange {
                begin: 2,
                end: 5,
                visited: false,
            }],
            Some(&scheme),
        );
        assert_eq!(
            runs.iter().map(|run| run.text.as_str()).collect::<Vec<_>>(),
            ["ab", "cde", "fgh"]
        );
        assert!(!runs[0].underline);
        assert!(runs[1].underline);
        assert!(!runs[2].underline);
        assert_eq!(effects.len(), runs.len());
    }

    #[test]
    fn ppt_character_position_preserves_superscript() {
        let mut body = Vec::new();
        body.extend_from_slice(&4_u32.to_le_bytes());
        body.extend_from_slice(&0_u16.to_le_bytes());
        body.extend_from_slice(&0_u32.to_le_bytes());
        body.extend_from_slice(&1_u32.to_le_bytes());
        body.extend_from_slice(&(1_u32 << 17).to_le_bytes());
        body.extend_from_slice(&24_u16.to_le_bytes());
        body.extend_from_slice(&2_u32.to_le_bytes());
        body.extend_from_slice(&((1_u32 << 19) | (1 << 17)).to_le_bytes());
        body.extend_from_slice(&24_u16.to_le_bytes());
        body.extend_from_slice(&30_i16.to_le_bytes());
        body.extend_from_slice(&1_u32.to_le_bytes());
        body.extend_from_slice(&0_u32.to_le_bytes());
        let bytes = ppt_record(0, RT_STYLE_TEXT_PROP_ATOM, &body);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let (_, styles) = parse_ppt_direct_text_style(&bytes, record, 3).unwrap();
        let (runs, _) = resolve_ppt_text_runs("2nd", 1, &[], &styles, None, &HashMap::new());

        assert_eq!(runs[0].text, "2");
        assert_eq!(runs[1].text, "nd");
        assert!((runs[1].font_size - 20.8).abs() < 0.001);
        assert!((runs[1].baseline_shift - 9.6).abs() < 0.001);
    }

