    #[test]
    fn ppt_text_ruler_overrides_level_margins() {
        let mut body = 0x00f8_u32.to_le_bytes().to_vec();
        for margin in [216_i16, 468, 720, 1_008, 1_296] {
            body.extend_from_slice(&margin.to_le_bytes());
        }
        let bytes = ppt_record(0, RT_TEXT_RULER_ATOM, &body);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let levels = parse_ppt_text_ruler(&bytes, record).unwrap();

        assert_eq!(levels[0].left_margin, Some(36.0));
        assert_eq!(levels[4].left_margin, Some(216.0));
        assert_eq!(levels[0].indent, None);
    }

