    #[test]
    fn ppt_character_shadow_stays_on_its_text_run() {
        let (runs, effects) = resolve_ppt_text_runs(
            "plainshadow",
            1,
            &[],
            &[
                (5, PptCharacterStyle::default()),
                (
                    6,
                    PptCharacterStyle {
                        shadow: Some(true),
                        ..PptCharacterStyle::default()
                    },
                ),
            ],
            None,
            &HashMap::new(),
        );

        assert_eq!(
            runs.iter().map(|run| run.text.as_str()).collect::<Vec<_>>(),
            ["plain", "shadow"]
        );
        assert!(effects[0].shadow.is_none());
        let shadow = effects[1].shadow.as_ref().unwrap();
        assert_eq!(shadow.color, 0xc0c0_c0ff);
        assert!((shadow.offset_x - 2.828_16).abs() < 0.000_01);
        assert_eq!(shadow.offset_x, shadow.offset_y);
    }

