    #[test]
    fn ppt_group_transform_scales_child_path_coordinates() {
        let transform = PptGroupTransform {
            source: Rect {
                x: 0.0,
                y: 0.0,
                width: 400.0,
                height: 200.0,
            },
            destination: Rect {
                x: 20.0,
                y: 30.0,
                width: 200.0,
                height: 50.0,
            },
            rotation_degrees: 0.0,
            flip_horizontal: false,
        };
        let mut drawing = NativePptDrawing {
            bounds: transform.source,
            record_offset: 0,
            kind: ObjectKind::Shape,
            visual: Visual::Shape {
                geometry: Geometry::Path {
                    fill_rule: FillRule::NonZero,
                    commands: vec![
                        PathCommand::MoveTo { x: 200.0, y: 0.0 },
                        PathCommand::LineTo { x: 400.0, y: 200.0 },
                    ],
                },
                fill: 0,
                stroke: 0,
                stroke_width: 0.0,
            },
            background: false,
            use_slide_background: false,
            external_object_id: None,
            rotation_degrees: 0.0,
            flip_horizontal: false,
        };

        transform_ppt_drawing(&mut drawing, transform);

        let Visual::Shape {
            geometry: Geometry::Path { commands, .. },
            ..
        } = drawing.visual
        else {
            panic!("grouped path must remain a shape");
        };
        assert_eq!(
            commands,
            vec![
                PathCommand::MoveTo { x: 100.0, y: 0.0 },
                PathCommand::LineTo { x: 200.0, y: 50.0 },
            ]
        );
    }

    #[test]
    fn ppt_group_rotates_landscape_children_only_for_a_portrait_destination() {
        let mut drawing = NativePptDrawing {
            bounds: Rect {
                x: 100.0,
                y: 50.0,
                width: 80.0,
                height: 40.0,
            },
            record_offset: 0,
            kind: ObjectKind::Shape,
            visual: Visual::Shape {
                geometry: Geometry::Path {
                    fill_rule: FillRule::NonZero,
                    commands: vec![
                        PathCommand::MoveTo { x: 0.0, y: 0.0 },
                        PathCommand::LineTo { x: 80.0, y: 40.0 },
                    ],
                },
                fill: 0,
                stroke: 0,
                stroke_width: 0.0,
            },
            background: false,
            use_slide_background: false,
            external_object_id: None,
            rotation_degrees: -90.0,
            flip_horizontal: false,
        };
        transform_ppt_drawing(
            &mut drawing,
            PptGroupTransform {
                source: Rect {
                    x: 0.0,
                    y: 0.0,
                    width: 400.0,
                    height: 200.0,
                },
                destination: Rect {
                    x: 20.0,
                    y: 30.0,
                    width: 50.0,
                    height: 200.0,
                },
                rotation_degrees: 90.0,
                flip_horizontal: true,
            },
        );

        assert_eq!(drawing.bounds.x, 32.5);
        assert_eq!(drawing.bounds.y, 80.0);
        assert_eq!(drawing.bounds.width, 10.0);
        assert_eq!(drawing.bounds.height, 40.0);
        let Visual::Shape {
            geometry: Geometry::Path { commands, .. },
            ..
        } = drawing.visual
        else {
            unreachable!();
        };
        assert_eq!(commands[0], PathCommand::MoveTo { x: 10.0, y: 0.0 });
        assert_eq!(commands[1], PathCommand::LineTo { x: 0.0, y: 40.0 });
    }

