    #[test]
    fn ppt_wps_32_bit_client_anchor_preserves_group_bounds() {
        let shape = ppt_record((1 << 4) | 2, OFFICE_ART_SP, &[0; 8]);
        let mut anchor = Vec::new();
        for value in [-2_i32, 1_536, 5_760, 2_206] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        let mut shape_body = shape;
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        let bytes = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let (bounds, _, _) = parse_ppt_shape(
            &bytes,
            record,
            &[],
            None,
            PPT_DEFAULT_WIDTH,
            PPT_DEFAULT_HEIGHT,
            Limits::default(),
        )
        .unwrap();

        assert_eq!(
            bounds,
            Some(Rect {
                x: -2.0 / 6.0,
                y: 256.0,
                width: 960.0 + 2.0 / 6.0,
                height: 111.666_66,
            })
        );
    }

    #[cfg(feature = "native-formats")]
    #[test]
    fn ppt_wps_e2o_table_package_preserves_grid_borders() {
        let xml = br#"<p:E2oFrame xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:tbl><a:tblGrid><a:gridCol w="100"/><a:gridCol w="100"/></a:tblGrid><a:tr h="50"><a:tc><a:tcPr><a:lnL w="30"><a:solidFill/></a:lnL><a:lnR w="10"><a:solidFill/></a:lnR><a:lnT w="30"><a:solidFill/></a:lnT><a:lnB w="10"><a:solidFill/></a:lnB></a:tcPr></a:tc><a:tc><a:tcPr><a:lnL w="10"><a:solidFill/></a:lnL><a:lnR w="30"><a:solidFill/></a:lnR><a:lnT w="30"><a:solidFill/></a:lnT><a:lnB w="10"><a:solidFill/></a:lnB></a:tcPr></a:tc></a:tr><a:tr h="50"><a:tc><a:tcPr><a:lnL w="30"><a:solidFill/></a:lnL><a:lnR w="10"><a:solidFill/></a:lnR><a:lnT w="10"><a:solidFill/></a:lnT><a:lnB w="30"><a:solidFill/></a:lnB></a:tcPr></a:tc><a:tc><a:tcPr><a:lnL w="10"><a:solidFill/></a:lnL><a:lnR w="30"><a:solidFill/></a:lnR><a:lnT w="10"><a:solidFill/></a:lnT><a:lnB w="30"><a:solidFill/></a:lnB></a:tcPr></a:tc></a:tr></a:tbl></p:E2oFrame>"#;
        let package = crate::format::presentation_image::stored_zip(&[("drs/e2oDoc.xml", xml)]);
        let mut properties = Vec::new();
        properties.extend_from_slice(&0x83a9_u16.to_le_bytes());
        properties.extend_from_slice(&(package.len() as u32).to_le_bytes());
        properties.extend_from_slice(&package);
        let mut shape_body = ppt_record((0 << 4) | 2, OFFICE_ART_SP, &[0, 0, 0, 0, 1, 2, 0, 0]);
        shape_body.extend_from_slice(&ppt_record(
            (1 << 4) | 3,
            OFFICE_ART_TERTIARY_OPT,
            &properties,
        ));
        let mut anchor = Vec::new();
        for value in [0_i16, 0, 1_200, 600] {
            anchor.extend_from_slice(&value.to_le_bytes());
        }
        shape_body.extend_from_slice(&ppt_record(0, OFFICE_ART_CLIENT_ANCHOR, &anchor));
        let bytes = ppt_record(0x000f, OFFICE_ART_SP_CONTAINER, &shape_body);
        let record = ppt_record_at(&bytes, 0, bytes.len(), Limits::default()).unwrap();

        let (_, _, drawing) = parse_ppt_shape(
            &bytes,
            record,
            &[],
            None,
            PPT_DEFAULT_WIDTH,
            PPT_DEFAULT_HEIGHT,
            Limits::default(),
        )
        .unwrap();
        let Visual::Group { children } = drawing.expect("table border visual").visual else {
            panic!("WPS E2o table must remain a grid");
        };
        assert_eq!(children.len(), 6);
    }

