    #[test]
    fn ppt_picture_store_uses_bstore_order_and_delayed_offsets() {
        let mut first_bse = vec![0u8; 36];
        first_bse[0] = 6;
        write_u32(&mut first_bse, 28, 100);
        let mut second_bse = vec![0u8; 36];
        second_bse[1] = 5;
        write_u32(&mut second_bse, 28, 20);
        let mut store_body = ppt_record(2, 0xf007, &first_bse);
        store_body.extend_from_slice(&ppt_record(2, 0xf007, &second_bse));
        let store = ppt_record((2 << 4) | 0x000f, 0xf001, &store_body);
        let dgg = ppt_record(0x000f, 0xf000, &store);
        let drawing_group = ppt_record(0x000f, RT_DRAWING_GROUP, &dgg);
        let bytes = ppt_record(0x000f, RT_DOCUMENT, &drawing_group);
        let live_directory = LivePersistDirectory {
            offsets: HashMap::from([(1, 0)]),
            document_persist_id: 1,
        };

        assert_eq!(
            ppt_picture_store_entries(&bytes, &live_directory, Limits::default(), &mut Vec::new(),)
                .unwrap(),
            Some(vec![(6, 100), (5, 20)])
        );
    }

    #[test]
    fn ppt_picture_store_falls_back_for_embedded_blips() {
        let mut bse = vec![0u8; 36];
        bse[0] = 6;
        write_u32(&mut bse, 28, u32::MAX);
        let store_body = ppt_record(2, 0xf007, &bse);
        let store = ppt_record((1 << 4) | 0x000f, 0xf001, &store_body);
        let dgg = ppt_record(0x000f, 0xf000, &store);
        let drawing_group = ppt_record(0x000f, RT_DRAWING_GROUP, &dgg);
        let bytes = ppt_record(0x000f, RT_DOCUMENT, &drawing_group);
        let live_directory = LivePersistDirectory {
            offsets: HashMap::from([(1, 0)]),
            document_persist_id: 1,
        };

        assert_eq!(
            ppt_picture_store_entries(&bytes, &live_directory, Limits::default(), &mut Vec::new(),)
                .unwrap(),
            None
        );
    }

