        write_u32(&mut table, 68, 519);
        write_u32(&mut table, 72, 2);
        let font_table = formatted_doc_font_table();
        table[80..80 + font_table.len()].copy_from_slice(&font_table);
        write_u32(&mut table, 224, 512);
        write_u32(&mut table, 228, 519);
