    #[cfg(feature = "native-formats")]
    #[test]
    fn reads_equation_editor_3_structural_templates() {
        let script = [
            3, 1, 1, 3, 10, 1, 2, 0x83, b'x', 0, 3, 15, 2, 0, 11, 1, 2, 0x88, b'i', 0, 0, 1, 2,
            0x88, b'2', 0, 0, 0, 0, 0,
        ];
        let fraction = [
            3, 1, 1, 3, 10, 1, 3, 14, 0, 0, 1, 2, 0x83, b'a', 0, 0, 1, 2, 0x83, b'b', 0, 0, 0, 0, 0,
        ];
        let product = [
            3, 1, 1, 3, 10, 1, 3, 31, 1, 0, 1, 2, 0x83, b'x', 0, 0, 1, 2, 0x83, b'i', 0, 2, 0x86,
            b'=', 0, 2, 0x88, b'1', 0, 0, 1, 2, 0x83, b'n', 0, 0, 13, 2, 0x86, 0x0f, 0x22, 0, 0, 0,
        ];

        assert_eq!(
            parse_mtef3_equation_text(&script).unwrap(),
            Some("x_{i}^{2}".to_owned())
        );
        assert_eq!(
            parse_mtef3_equation_text(&fraction).unwrap(),
            Some("(a)/(b)".to_owned())
        );
        assert_eq!(
            parse_mtef3_equation_text(&product).unwrap(),
            Some("∏_{i=1}^{n} x".to_owned())
        );
    }

    #[cfg(feature = "native-formats")]
    #[test]
    fn embedded_equation_stacks_sum_limits_at_the_same_x() {
        let mut stream = vec![0; 28];
        stream.extend_from_slice(&[
            3, 1, 1, 3, 1, 10, 1, 3, 30, 1, 0, 1, 2, 0x88, b'4', 0, 0x12, 0x83, b'x', 0, 2, 0x86,
            b'+', 0, 2, 0x88, b'6', 0, 0, 11, 1, 2, 0x88, b'6', 0, 0, 1, 2, 0x88, b'3', 0, 0, 13,
            2, 0x86, 0x11, 0x22, 0, 0,
        ]);
        stream.resize(CFB_MINI_STREAM_CUTOFF, 0);
        let cfb = build_cfb(&[("Equation Native", stream)]);
        let mut drawing = NativePptDrawing {
            bounds: Rect {
                x: 100.0,
                y: 200.0,
                width: 400.0,
                height: 160.0,
            },
            record_offset: 0,
            kind: ObjectKind::Image,
            visual: Visual::None,
            background: false,
            use_slide_background: false,
            external_object_id: None,
            rotation_degrees: 0.0,
            flip_horizontal: false,
        };

        let children = materialize_ppt_embedded_object(&mut drawing, &cfb, Limits::default())
            .expect("equation must preserve two-dimensional script layout");
        assert_eq!(children.len(), 4);
        assert!((children[1].bounds.x - children[2].bounds.x).abs() < 0.001);
        assert!(children[1].bounds.y < children[2].bounds.y);
    }

